import React, { useState, useEffect, useMemo, useRef } from 'react';
import type { SeekerProfileWeaverPanelProps, SeekerProfile, MarketItem } from '../../types';
import { 
  AgentName, 
  SeekerAvatarType, 
  SeekerClass, 
  SeekerGender, 
  SeekerEnergyAlignment, 
  SeekerAuraColor, 
  SeekerVisualFilter,
  ArtifactRarity,
  AgentRace 
} from '../../types';
import { 
  SEEKER_CLASSES, 
  ALL_GENDERS_LIST, 
  ALL_ALIGNMENTS_LIST, 
  SEEKER_AURA_OPTIONS, 
  SEEKER_VISUAL_FILTERS, 
  TRAIT_LISTS,
