// Robust JSON Parsing Helper to fix "Expected ',' or '}'" errors
const safeParseJSON = <T,>(input: string | null): T | null => {
    if (!input) return null;
    try {
        // Attempt to find JSON structure (object or array) in the string
        // This handles cases where Gemini wraps JSON in markdown ```json ... ```
        const match = input.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);
        const jsonStr = match ? match[0] : input.replace(/```json/g, '').replace(/```/g, '').trim();
        return JSON.parse(jsonStr) as T;
    } catch (e) {
        console.warn("JSON Parse Failed for input:", input.substring(0, 100) + "...", e);
        return null;
    }
};

