                <span className="flex items-center gap-1"><i className="ri-dashboard-3-line"></i> Reality Pressure</span>
                <span className={`${isCritical ? 'text-rose-500 animate-pulse font-bold' : 'text-slate-300'}`}>{percentage.toFixed(1)}% {isCritical ? 'CRITICAL' : ''}</span>
            </div>
            <div className="h-3 w-full bg-slate-800 rounded-full overflow-hidden relative border border-slate-600/30">
                <div className="absolute inset-0 opacity-20" style={{backgroundImage: 'linear-gradient(90deg, transparent 95%, #000 95%)', backgroundSize: '10px 100%'}}></div>
                <div 
                    className={`h-full transition-all duration-700 ease-out relative ${isCritical ? 'bg-gradient-to-r from-purple-600 via-rose-600 to-red-600 animate-pulse' : 'bg-gradient-to-r from-blue-600 via-cyan-500 to-emerald-500'}`}
                    style={{ width: `${percentage}%` }}
