          if (savedState.combatState) setCombatState(savedState.combatState);
          if (savedState.knownLocations) setAtlas(savedState.knownLocations);
          setGameMode('PLAYING'); 
      }
  }, [savedState]);

  // Save State
  useEffect(() => {
      if (onSaveState && gameMode === 'PLAYING') {
        const stateToSave = {
            currentLocation: location as RPGGameLocation, 
            narrativeHistory: narrativeLog,
            activeQuests: activeQuests, 
            lastActionTimestamp: Date.now(),
            currentSceneDescription: sceneDescription,
            currentSceneImageUrl: sceneImageUrl,
            availableActions: availableActions,
            achievements: unlockedAchievements,
            vitals: { integrity, sanity },
            combatState: combatState,
            knownLocations: atlas
        };
        const timer = setTimeout(() => onSaveState(stateToSave), 1000);
        return () => clearTimeout(timer);
      }
  }, [location, narrativeLog, sceneDescription, sceneImageUrl, availableActions, activeQuests, unlockedAchievements, gameMode, integrity, sanity, combatState, atlas, onSaveState]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [narrativeLog]);

  // Toast timers
  useEffect(() => { if (achievementToast) { const t = setTimeout(() => setAchievementToast(null), 4000); return () => clearTimeout(t); } }, [achievementToast]);
  useEffect(() => { if (levelUpToast) { const t = setTimeout(() => setLevelUpToast(null), 5000); return () => clearTimeout(t); } }, [levelUpToast]);

  // Achievement Logic
  useEffect(() => {
      if (!activeProfile) return;
      const newAchievements: RPGAchievement[] = [];
      if (activeProfile.flux >= 1000 && !unlockedAchievements.some(a => a.id === 'ach_high_roller')) {
          newAchievements.push(ACHIEVEMENTS_LIST.find(a => a.id === 'ach_high_roller')!);
      }
      if (integrity < 10 && !unlockedAchievements.some(a => a.id === 'ach_survivor')) {
          newAchievements.push(ACHIEVEMENTS_LIST.find(a => a.id === 'ach_survivor')!);
      }
      if (newAchievements.length > 0) {
          setUnlockedAchievements(prev => [...prev, ...newAchievements]);
          setAchievementToast(newAchievements[0]); 
          addEchoMessage(AgentName.System, `Achievements Unlocked: ${newAchievements.map(a=>a.name).join(', ')}`, 'text-yellow-300');
          globalSoundEngine.playSFX('success');
      }
  }, [activeProfile?.flux, integrity, unlockedAchievements]);

  // Helpers
  const calculateEffectiveStats = () => {
      let atk = 10;
      let def = 10;
      if (activeProfile?.stats) {
          atk = activeProfile.stats.power;
          def = activeProfile.stats.defense;
      }
      if (activeProfile?.equippedWeapon) atk += 15;
      if (activeProfile?.equippedOutfit) def += 10;
      if (activeProfile?.equippedRelic) atk += 5;
      return { atk, def };
  };

  const constructCharacterContext = (profile: any) => {
      if (!profile) return "Unknown Entity";
      const stats = calculateEffectiveStats();
      let context = `${profile.name}, a ${profile.gender} ${profile.race} ${profile.class}. Stats: ATK ${stats.atk}, DEF ${stats.def}.`;
      if (profile.bio) context += ` Bio: ${profile.bio}`; 
      const equipment = [];
      if (profile.equippedWeapon) equipment.push(`Wielding: ${profile.equippedWeapon.name}`);
      if (profile.equippedOutfit) equipment.push(`Wearing: ${profile.equippedOutfit.name}`);
      if (equipment.length > 0) context += " Equipment: " + equipment.join(". ") + ".";
      if (profile.auraColor) context += ` Aura: ${profile.auraColor}.`;
      return context;
  };

  const getInventoryContext = (profile: any) => {
      if (!profile || !profile.inventory) return "Empty";
      return profile.inventory.map((i: any) => i.name).join(", ");
  };

  const getRiskColor = (risk: number) => {
      if (risk < 15) return 'text-emerald-400';
      if (risk < 40) return 'text-amber-400';
      return 'text-rose-400';
  };

  const generateDynamicLocations = async () => {
      if(isGeneratingLocations) return;
      setIsGeneratingLocations(true);
      globalSoundEngine.playSFX('click');
      setGeneratedLocations({}); setGeneratedQuests([]); setSelectedStartLoc(null);

      const prompt = `Generate 3 unique, evocative RPG locations for a sci-fi/fantasy setting heavily influenced by entropy level ${currentEntropy.toFixed(2)}... (JSON response)`;

      try {
        const response = await invokeGemini(prompt, "You are a creative world-building AI. Respond ONLY in valid JSON.");
        if (response) {
            const locs = safeParseJSON<Record<string, { description: string, color: string, risk: string, icon: string }>>(response);
            if (locs) {
                setGeneratedLocations(locs);
                const newAtlasEntries = Object.entries(locs).map(([name, data]) => ({
                    id: `loc-${Date.now()}-${name}`, name, description: data.description, visitedAt: Date.now(), riskLevel: data.risk, icon: data.icon, color: data.color
                }));
            } else { setGeneratedLocations(FALLBACK_LOCATIONS); }
        } else { setGeneratedLocations(FALLBACK_LOCATIONS); }
      } catch (e) { console.error(e); setGeneratedLocations(FALLBACK_LOCATIONS); } finally { setIsGeneratingLocations(false); }
  };

  const generateDynamicQuests = async (locationName: string) => {
      if(isGeneratingQuests || !locationName) return;
      setIsGeneratingQuests(true);
      setGeneratedQuests([]); setSelectedQuestTemplate(null);
      const locDesc = generatedLocations[locationName]?.description || "A mysterious place.";
      const prompt = `Generate 3 RPG quest hooks for "${locationName}" (${locDesc}). Theme: Entropy ${currentEntropy.toFixed(2)}. (JSON response)`;
      try {
        const response = await invokeGemini(prompt, "Creative quest designer AI. Respond ONLY in valid JSON.");
        if (response) {
             const quests = safeParseJSON<{ id: string, title: string, desc: string, difficulty: string }[]>(response);
             if (quests) setGeneratedQuests(quests); else setGeneratedQuests(LEGENDARY_QUESTS.slice(0,3));
        } else { setGeneratedQuests(LEGENDARY_QUESTS.slice(0,3)); }
      } catch (e) { console.error(e); setGeneratedQuests(LEGENDARY_QUESTS.slice(0,3)); } finally { setIsGeneratingQuests(false); }
  };

  const handleLocationSelect = (locName: string) => {
      globalSoundEngine.playSFX('click');
      setSelectedStartLoc(locName);
      generateDynamicQuests(locName);
  };

  const visualHistory = useMemo(() => {
      return artifacts.filter(a => a.type === ArtifactType.VisualMemory).sort((a, b) => b.timestamp - a.timestamp).map(a => ({ id: a.id, url: a.imageUrl || '', loc: a.metaData?.location || 'Unknown', desc: a.description, timestamp: a.timestamp }));
  }, [artifacts]);

  const addToLog = (text: string, type: 'narration' | 'action' | 'system' | 'ambient' = 'narration') => {
    setNarrativeLog(prev => [...prev, { text, type, timestamp: Date.now() }]);
  };

  const speakNarrative = async (text: string) => {
      if (!isAudioEnabled) return;

      // Try high quality Gemini TTS first
      try {
        const arrayBuffer = await generateSpeech(text, 'Kore');
        if (arrayBuffer) {
           const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
           const audioBufferSource = audioCtx.createBufferSource();
           audioBufferSource.buffer = await audioCtx.decodeAudioData(arrayBuffer);
           audioBufferSource.connect(audioCtx.destination);
           audioBufferSource.start();
           return;
        }
      } catch (e) {
          console.warn("Gemini TTS failed/skipped, trying VoiceEngine/Browser", e);
      }

      // Fallback to WebSpeech/VoiceEngine
      const profile = voiceProfiles.find(p => p.id === activeVoiceId) || voiceProfiles.find(p => p.agent === AgentName.RPGNexusAgent);
      if (profile) voiceEngine.speak(text, profile).catch(e => console.warn("Voice Error", e));
  };

  const handlePlayAudio = () => {
      globalSoundEngine.playSFX('click');
      const textToSpeak = sceneDescription || (narrativeLog.length > 0 ? narrativeLog[narrativeLog.length - 1].text : "");
      if (textToSpeak) {
          speakNarrative(textToSpeak);
          addEchoMessage(AgentName.RPGNexusAgent, "Narrative audio stream active.", "text-indigo-400");
      }
  };

  const handleGenerateVideo = async () => {
      globalSoundEngine.playSFX('click');
      if (isVideoGenerating || !sceneImageUrl) return;
      setIsVideoGenerating(true);
      addEchoMessage(AgentName.RPGNexusAgent, "Manifesting scene into motion...", "text-fuchsia-400");
      try {
          const videoUrl = await generateVideo(sceneDescription, sceneImageUrl);
          if (videoUrl) {
              setSceneVideoUrl(videoUrl);
              addEchoMessage(AgentName.RPGNexusAgent, "Motion manifestation complete.", "text-emerald-400");
              globalSoundEngine.playSFX('success');
          } else {
              addEchoMessage(AgentName.RPGNexusAgent, "Motion synthesis failed.", "text-rose-400");
              globalSoundEngine.playSFX('fail');
          }
      } catch (error) {
          console.error("Video Gen Error", error);
          addEchoMessage(AgentName.RPGNexusAgent, "Video generation error.", "text-rose-400");
          globalSoundEngine.playSFX('fail');
      } finally {
          setIsVideoGenerating(false);
      }
  };

  const handleCompileQuestVideo = async () => {
      globalSoundEngine.playSFX('click');
      if (isVideoCompiling || (visualHistory.length === 0 && !sceneImageUrl)) {
          if (!isVideoCompiling) addEchoMessage(AgentName.System, "No visual data to compile.", "text-yellow-400");
          return;
      }

      setIsVideoCompiling(true);
      setCompilationProgress(0);
      addEchoMessage(AgentName.RPGNexusAgent, "Compiling visual chronicle into cinema reel...", "text-purple-300");

      try {
        const composer = new QuestCinemaEngine();
        const slides = visualHistory.map(v => ({ imageUrl: v.url, text: v.desc || `Scene from ${v.loc}` }));

        if (sceneImageUrl) slides.push({ imageUrl: sceneImageUrl, text: sceneDescription || "Current Scene" });
        slides.push({ imageUrl: slides[slides.length-1].imageUrl, text: "TO BE CONTINUED..." }); 

        slides.reverse(); // Chronological

        const audioGenerator = async (text: string) => {
            return await generateSpeech(text, 'Kore');
        };

        const blob = await composer.compileVideo(slides, (progress) => setCompilationProgress(Math.floor(progress * 100)), audioGenerator);

        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `Codex_Quest_Reel_${Date.now()}.webm`;
        a.click();

        addEchoMessage(AgentName.RPGNexusAgent, "Quest Reel materialized.", "text-emerald-400");
        globalSoundEngine.playSFX('success');
        setTimeout(() => URL.revokeObjectURL(url), 2000);

      } catch (e) {
          console.error("Video Compilation Error", e);
          addEchoMessage(AgentName.System, "Failed to compile quest video.", "text-rose-400");
          globalSoundEngine.playSFX('fail');
      } finally {
          setIsVideoCompiling(false);
          setCompilationProgress(0);
      }
  };

  const generateSceneVisuals = async (locationName: string, context: string) => {
      if (isImageGenerating) return;
      setIsImageGenerating(true);
      const charContext = constructCharacterContext(activeProfile);
      const visualProps = `Character: ${activeProfile?.race} ${activeProfile?.class}, ${activeProfile?.gender}. Wearing: ${activeProfile?.equippedOutfit?.name || 'Standard Gear'}. Wielding: ${activeProfile?.equippedWeapon?.name || 'Weapon'}. Aura: ${activeProfile?.auraColor}.`;
      const prompt = `Fantasy Sci-Fi RPG Scene: ${locationName}. ${context}. Visual Details: ${visualProps} Style: ${activeProfile?.visualFilter || 'Cyberpunk'}, detailed, atmospheric, entropy level ${currentEntropy.toFixed(2)}.`;

      try {
          const url = await generateImage(prompt, 'imagen-4.0-generate-001'); 
          if (url) {
              setSceneImageUrl(url);
              if (onArtifactCreated) {
                  const artifact: CodexArtifact = {
                      id: `visual-${Date.now()}`, name: `Visual: ${locationName}`, type: ArtifactType.VisualMemory, rarity: ArtifactRarity.Common, description: context, imageUrl: url, timestamp: Date.now(), metaData: { location: locationName, characterContext: visualProps }
                  };
                  onArtifactCreated(artifact);
              }
          }
      } catch (e) { console.error("Visual Gen Error", e); } finally { setIsImageGenerating(false); }
  };

  const handleAction = async (actionLabel: string, type: 'action', risk: number) => {
      if (isProcessing || criticalState) return;
      setIsProcessing(true);
      globalSoundEngine.playSFX('click');
      addToLog(actionLabel, 'action');

      const charContext = constructCharacterContext(activeProfile);
      let combatInstruction = "";
      if (combatState.isActive) {
          combatInstruction = `COMBAT MODE ACTIVE. Enemy: ${combatState.enemyName} (HP: ${combatState.enemyHp}/${combatState.enemyMaxHp}). Player ATK: ${calculateEffectiveStats().atk}, DEF: ${calculateEffectiveStats().def}. Resolve turn. Respond with JSON: { narrative, integrityDelta, enemyHpDelta, combatStatus: "ongoing"|"victory"|"defeat"|"escaped" }.`;
      }

      const systemInstruction = `You are the Game Master (Nexus Agent) for a text-based RPG. Entropy: ${currentEntropy}. Profile: ${charContext} Location: ${location}. Quest: ${activeQuests[0]?.title || 'None'}. ${combatInstruction} Respond with JSON: { narrative, integrityDelta, sanityDelta, newActions, loot, combatStart }`;
      const prompt = `Player performs: "${actionLabel}". Risk Level: ${risk}. Determine the outcome.`;

      try {
          const response = await invokeGemini(prompt, systemInstruction);
          if (response) {
             const result = safeParseJSON<any>(response);
             if (result) {
                addToLog(result.narrative, 'narration');
                setSceneDescription(result.narrative);
                speakNarrative(result.narrative);

                const newIntegrity = Math.max(0, Math.min(100, integrity + (result.integrityDelta || 0)));
                const newSanity = Math.max(0, Math.min(100, sanity + (result.sanityDelta || 0)));
                setIntegrity(newIntegrity);
                setSanity(newSanity);

                if (newIntegrity <= 0) { setCriticalState('death'); globalSoundEngine.playSFX('fail'); }
                else if (result.integrityDelta < 0) { globalSoundEngine.playSFX('pulse'); } // Damage sound

                if (newSanity <= 0) setCriticalState('madness');

                if (result.newActions && Array.isArray(result.newActions)) {
                    setAvailableActions(result.newActions.map((a: any) => ({ ...a, isDynamic: true })));
                }

                if (result.loot) {
                    const newItem: MarketItem = { id: `loot-${Date.now()}`, name: result.loot.name, type: result.loot.type || 'Relic', rarity: result.loot.rarity || 'Common', description: 'Found in the Nexus.', visualPromptMod: result.loot.name, cost: 0, icon: 'ri-treasure-map-line' };
                    const updatedProfile = { ...activeProfile!, inventory: [...activeProfile!.inventory, newItem] };
                    onUpdateProfile(updatedProfile);
                    setDroppedItem(newItem);
                    addEchoMessage(AgentName.RPGNexusAgent, `Loot acquired: ${newItem.name}`, 'text-emerald-300');
                    globalSoundEngine.playSFX('success');
                }

                // Combat Logic
                if (result.combatStart && !combatState.isActive) {
                    setCombatState({ isActive: true, enemyName: result.combatStart.name, enemyHp: result.combatStart.hp, enemyMaxHp: result.combatStart.hp, turn: 1, logs: ["Combat Started!"] });
                    setAvailableActions([ { id: 'atk', label: 'Attack', type: 'combat', risk: 20, isDynamic: true }, { id: 'def', label: 'Defend', type: 'combat', risk: 5, isDynamic: true }, { id: 'flee', label: 'Flee', type: 'combat', risk: 50, isDynamic: true } ]);
                } else if (combatState.isActive && result.enemyHpDelta) {
                    const newEnemyHp = Math.max(0, combatState.enemyHp + result.enemyHpDelta);
                    setCombatState(prev => ({ ...prev, enemyHp: newEnemyHp, turn: prev.turn + 1 }));

                    if (result.combatStatus === 'victory' || newEnemyHp <= 0) {
                        setCombatState(prev => ({ ...prev, isActive: false }));
                        addEchoMessage(AgentName.RPGNexusAgent, "Enemy Defeated!", 'text-emerald-400');
                        setAvailableActions(INITIAL_ACTIONS);
                        if (!unlockedAchievements.some(a => a.id === 'ach_first_blood')) {
                            setAchievementToast(ACHIEVEMENTS_LIST.find(a => a.id === 'ach_first_blood')!);
                            setUnlockedAchievements(prev => [...prev, ACHIEVEMENTS_LIST.find(a => a.id === 'ach_first_blood')!]);
                        }
                         globalSoundEngine.playSFX('success');
                    } else if (result.combatStatus === 'escaped') {
                         setCombatState(prev => ({ ...prev, isActive: false }));
                         setAvailableActions(INITIAL_ACTIONS);
                    }
                }

                // Quest Logic
                if (activeQuests.length > 0) {
                    const currentQuest = activeQuests[0];
                    const progressIncrement = Math.floor(5 + (risk / 5));
                    const newProgress = Math.min(100, (currentQuest.progress || 0) + progressIncrement);
                    const updatedQuest = { ...currentQuest, progress: newProgress };

                    if (newProgress >= 100) {
                         updatedQuest.status = 'completed';
                         const xpReward = updatedQuest.rewards.xp;
                         const fluxReward = updatedQuest.rewards.flux;
                         const newProfile = { ...activeProfile!, experience: activeProfile!.experience + xpReward, flux: activeProfile!.flux + fluxReward, level: Math.floor((activeProfile!.experience + xpReward) / 1000) + 1 };
                         onUpdateProfile(newProfile);
                         addEchoMessage(AgentName.RPGNexusAgent, `QUEST COMPLETE: ${currentQuest.title}.`, 'text-yellow-300 font-bold');
                         setAchievementToast({ id: `quest_done_${Date.now()}`, name: 'Quest Complete', description: currentQuest.title, icon: 'ri-flag-2-fill' });
                         setActiveQuests(prev => prev.slice(1));
                         globalSoundEngine.playSFX('success');
                    } else {
                         setActiveQuests(prev => [updatedQuest, ...prev.slice(1)]);
                    }
                }

                if (Math.random() > 0.7 || result.narrative.includes("arrive") || result.narrative.includes("fight")) {
                     generateSceneVisuals(location, result.narrative);
                }

             } else {
                 addToLog(response, 'narration');
                 setSceneDescription(response);
             }
          }
      } catch (e) {
          console.error("Action Error", e);
          addEchoMessage(AgentName.System, "Nexus connection interrupted.", "text-rose-400");
          globalSoundEngine.playSFX('fail');
      } finally {
          setIsProcessing(false);
      }
  };

  const handleForceVisualRegen = () => {
      globalSoundEngine.playSFX('click');
