                 <h2 className="text-2xl font-cinzel text-indigo-300">Planetary Atlas</h2>
                 <button onClick={() => { globalSoundEngine.playSFX('click'); setGameMode('PLAYING'); }} className="text-slate-400 hover:text-white"><i className="ri-close-line text-2xl"></i></button>
             </div>
             <div className="grid grid-cols-1 md:grid-cols-3 gap-4 overflow-y-auto custom-scrollbar">
