                             <h4 className="font-bold text-slate-200">{entry.name}</h4>
                         </div>
                         <p className="text-xs text-slate-400 mb-2">{entry.description}</p>
                         <div className="flex justify-between text-[10px] uppercase font-mono text-slate-500">
                             <span>Risk: {entry.riskLevel}</span>
                             <span>Visited: {new Date(entry.visitedAt).toLocaleDateString()}</span>
                         </div>
                     </div>
                 ))}
             </div>
