            {/* INVENTORY OVERLAY */}
            {showInventoryOverlay && <div className="absolute bottom-20 right-4 z-[60] bg-slate-900 border border-slate-600 rounded-xl shadow-2xl p-4 w-72 animate-slide-up-fade"><div className="flex justify-between items-center mb-3 border-b border-slate-700 pb-2"><h4 className="text-xs font-bold text-amber-300 uppercase tracking-wider">Inventory Bag</h4><button onClick={() => { globalSoundEngine.playSFX('click'); setShowInventoryOverlay(false); }} className="text-slate-400 hover:text-white"><i className="ri-close-line"></i></button></div>{activeProfile.inventory.length === 0 ? <p className="text-xs text-slate-500 italic text-center py-4">Bag empty.</p> : <div className="grid grid-cols-4 gap-2 max-h-48 overflow-y-auto custom-scrollbar">{activeProfile.inventory.map((item, idx) => <button key={idx} onClick={() => handleUseItem(item)} className="aspect-square bg-slate-800 border border-slate-700 rounded hover:border-amber-500 flex items-center justify-center relative group" title={`Use ${item.name}`}><i className={`${item.icon} text-lg text-slate-300`}></i>{['Consumable', 'Food'].includes(item.type) && <div className="absolute top-0 right-0 w-2 h-2 bg-green-500 rounded-full"></div>}</button>)}</div>}<p className="text-[9px] text-slate-500 mt-2 text-center">Click item to Use</p></div>}

