  HistoricalEventType, GeoMode, VisualizationMatrixMode, MutationLoomState, 
  RitualOutcome, RitualAlchemyResult, PlacedGlyph, CanvasConnection,
  GlyphMutationNode, RewovenGlyph, HistoricalEvent, Axiom, RPGGameState
} from './types';
import { AXIOM_DATA, ALL_CANONICAL_AXIOMS, AXIOM_RITUAL_ELEMENTS } from './constants';

const App: React.FC = () => {
  // -- Core System State --
  const [isBooting, setIsBooting] = useState(true);
  const [activeModal, setActiveModal] = useState<string | null>(null);
  const [isSaveLoadModalOpen, setIsSaveLoadModalOpen] = useState(false);
  const [modalContentWidth, setModalContentWidth] = useState(800);
  const [modalContentHeight, setModalContentHeight] = useState(600);

  // -- Codex Data State --
  const [currentEntropy, setCurrentEntropy] = useState<number>(0.1);
  const [codexModeId, setCodexModeId] = useState<CodexModeId>(CodexModeId.ORIGIN_STATE);
  const [echoLog, setEchoLog] = useState<EchoMessage[]>([]);
  const [artifacts, setArtifacts] = useState<CodexArtifact[]>([]);
  const [agents, setAgents] = useState<AgentNode[]>(generateInitialAgents());
  const [activeProfile, setActiveProfile] = useState<SeekerProfile | null>(null);
  const [seekerTraits, setSeekerTraits] = useState<string[]>([]);
  const [rpgState, setRpgState] = useState<RPGGameState | undefined>(undefined); 

  // -- Ritual State --
  const [placedGlyphs, setPlacedGlyphs] = useState<PlacedGlyph[]>([]);
  const [connections, setConnections] = useState<CanvasConnection[]>([]);
  const [lastRitualOutcome, setLastRitualOutcome] = useState<RitualOutcome | null>(null); // Track last ritual

  // -- Module States --
  const [mutationLoomState, setMutationLoomState] = useState<MutationLoomState>({
    glyph1Id: null, glyph2Id: null, isWeaving: false, entropyInjection: 0.1, traitFocus: []
  });
  const [geoMode, setGeoMode] = useState<GeoMode>(GeoMode.GlyphDNA);
  const [vizMode, setVizMode] = useState<VisualizationMatrixMode>(VisualizationMatrixMode.SacredLattice);
  const [negentropyLevel, setNegentropyLevel] = useState(0.5);
  const [isNegentropyStable, setIsNegentropyStable] = useState(true);
  const [selectedAgentForInspection, setSelectedAgentForInspection] = useState<AgentNode | null>(null);

  // -- Context & Hooks --
  const { invokeGemini, isGenerating: isGeminiGenerating } = useGemini();

  const stateSnapshot = useMemo(() => ({
    echoLog, 
    systemEntropy: currentEntropy, 
    ritualState: { currentPhase: 'Active', chaliceStatus: 'Flowing', placedGlyphs, connections }, 
    artifacts, 
    activeProfile, 
    rpgState
  }), [echoLog, currentEntropy, placedGlyphs, connections, artifacts, activeProfile, rpgState]);

  const { 
    saveGame, 
    loadGame, 
    getSaveSlots,
    hydrateState, 
    isHydrating, 
    saveStatus, 
    lastSavedTime,
    exportSave,
    importSave 
  } = useCodexPersistence(
    ['EchoLog', 'SystemEntropy', 'RitualState', 'Artifacts', 'ActiveProfile', 'RPGState'], 
    stateSnapshot
  );

  // -- Global Audio Listener --
  useEffect(() => {
    const handleGlobalClick = (e: MouseEvent) => {
      // Init audio context on first click if not already
      globalSoundEngine.init();
      globalSoundEngine.playUIFeedback('click');
    };

    window.addEventListener('click', handleGlobalClick);
    return () => window.removeEventListener('click', handleGlobalClick);
  }, []);

  // -- Hydration Effect --
  useEffect(() => {
    hydrateState().then((hydrated) => {
        if (hydrated) {
            if (hydrated.echoLog) setEchoLog(hydrated.echoLog);
            if (hydrated.systemEntropy !== undefined) setCurrentEntropy(hydrated.systemEntropy);
            if (hydrated.ritualState) {
                setPlacedGlyphs(hydrated.ritualState.placedGlyphs || []);
                setConnections(hydrated.ritualState.connections || []);
            }
            if (hydrated.artifacts) setArtifacts(hydrated.artifacts);
            if (hydrated.activeProfile) {
                setActiveProfile(hydrated.activeProfile);
                setSeekerTraits(hydrated.activeProfile.selfTraits);
            }
            if (hydrated.rpgState) setRpgState(hydrated.rpgState);
        }
    });
  }, [hydrateState]); 

  // -- Calculated Properties --
  const effectiveSystemEntropy = Math.max(0, Math.min(1, currentEntropy));

  // Determine dominant agent tone from recent log
  const dominantAgentTone = useMemo(() => {
      if (echoLog.length > 0) {
          const lastSource = echoLog[0].source;
          if (Object.values(AgentName).includes(lastSource as AgentName)) {
              return lastSource as AgentName;
          }
      }
      return null;
  }, [echoLog]);


  // -- Handlers --
  const addEchoMessage = useCallback((source: string, text: string, colorClass: string = 'text-slate-300', isAutoEcho: boolean = false, meta?: any) => {
    const newMessage: EchoMessage = {
      id: `echo-${Date.now()}-${Math.random()}`,
      source,
      text,
      colorClass,
      isAutoEcho,
      meta,
      timestamp: new Date().toISOString()
    };
    setEchoLog(prev => [newMessage, ...prev].slice(0, 100)); // Keep last 100
  }, []);

  const addArtifact = useCallback((artifact: CodexArtifact) => {
    setArtifacts(prev => [artifact, ...prev]);
    addEchoMessage(AgentName.ChronicleReliquaryAgent, `Artifact Acquired: ${artifact.name}`, 'text-amber-300');
  }, [addEchoMessage]);

  const handleUpdateProfile = useCallback((profile: SeekerProfile) => {
    setActiveProfile(profile);
    setSeekerTraits(profile.selfTraits); 
  }, []);

  const handleSaveRPGState = useCallback((state: RPGGameState) => {
      setRpgState(state);
      // Trigger autosave via hook implicitly through state update or explicit call if critical
      // saveGame('autosave'); // Optional: force save on RPG state change
  }, []);

  const handleSystemMetricsUpdate = useCallback((entropyDelta: number, negentropyDelta: number) => {
    setCurrentEntropy(prev => Math.min(1, Math.max(0, prev + entropyDelta)));
    setNegentropyLevel(prev => Math.min(1, Math.max(0, prev + negentropyDelta)));
  }, []);

  const handleRitualActivated = (success: boolean, details: string, type?: string, alchemyResult?: RitualAlchemyResult) => {
    addEchoMessage(AgentName.RitualEngine, success ? `Ritual Successful: ${details}` : `Ritual Fizzled: ${details}`, success ? 'text-emerald-400' : 'text-rose-400');
    setLastRitualOutcome({ success, details, type, alchemyResult });
    if (success) {
      setCurrentEntropy(prev => Math.max(0, prev - 0.05));
      setNegentropyLevel(prev => Math.min(1, prev + 0.05));
    } else {
      setCurrentEntropy(prev => Math.min(1, prev + 0.02));
      setNegentropyLevel(prev => Math.max(0, prev - 0.02));
    }
  };

  const handleImportSave = async (file: File) => {
      try {
          await importSave(file);
          window.location.reload(); 
      } catch (e) {
          alert("Import failed. Check console.");
      }
  };

  const handleLoadSlot = async (slotId: string) => {
      const hydrated = await loadGame(slotId);
       if (hydrated) {
            if (hydrated.echoLog) setEchoLog(hydrated.echoLog);
            if (hydrated.systemEntropy !== undefined) setCurrentEntropy(hydrated.systemEntropy);
            if (hydrated.ritualState) {
                setPlacedGlyphs(hydrated.ritualState.placedGlyphs || []);
                setConnections(hydrated.ritualState.connections || []);
            }
            if (hydrated.artifacts) setArtifacts(hydrated.artifacts);
            if (hydrated.activeProfile) {
                setActiveProfile(hydrated.activeProfile);
                setSeekerTraits(hydrated.activeProfile.selfTraits);
            }
            if (hydrated.rpgState) setRpgState(hydrated.rpgState);
            addEchoMessage(AgentName.System, `Timeline restored from ${slotId}.`, 'text-cyan-300');
        } else {
             addEchoMessage(AgentName.System, `Failed to load timeline from ${slotId}.`, 'text-rose-400');
        }
  };

  const onLaunchModule = (moduleId: string) => {
    setActiveModal(moduleId);
  };

  const closeModal = () => {
    setActiveModal(null);
    setSelectedAgentForInspection(null);
  };

  // -- Modal Content Renderer --
  const renderModalContent = () => {
    switch (activeModal) {
      case 'rpg_nexus':
        return <RPGNexusPanel width={modalContentWidth} height={modalContentHeight} addEchoMessage={addEchoMessage} activeProfile={activeProfile} onUpdateProfile={handleUpdateProfile} currentEntropy={effectiveSystemEntropy} systemMode={codexModeId} onArtifactCreated={addArtifact} artifacts={artifacts} savedState={rpgState} onSaveState={handleSaveRPGState} onUpdateSystemMetrics={handleSystemMetricsUpdate} />;
      case 'flux_farm':
        return <FluxFarmPanel width={modalContentWidth} height={modalContentHeight} activeProfile={activeProfile} onUpdateProfile={handleUpdateProfile} currentEntropy={effectiveSystemEntropy} addEchoMessage={addEchoMessage} />;
      // ... (Rest of switch cases identical to previous file content) ...
      case 'dreambloom':
        return <DreambloomGenesisPanel interpretations={[]} onConjurePulse={() => {}} isAutoActive={false} onToggleAuto={() => {}} isLoading={false} addEchoMessage={addEchoMessage} width={modalContentWidth} height={modalContentHeight} />;
      case 'mutation_loom':
        return <MutationLoomPanel glyphMutationNodes={[]} onWeaveGlyphs={async () => undefined} mutationLoomState={mutationLoomState} setMutationLoomState={setMutationLoomState} addEchoMessage={addEchoMessage} isGeminiGenerating={isGeminiGenerating} />;
      case 'glyph_composer':
        return <GlyphComposerPanel addEchoMessage={addEchoMessage} isBugaModeActive={false} />;
      case 'emerald_tablet':
        return <EmeraldTabletDecryptionPanel currentSystemEntropy={effectiveSystemEntropy} currentEleganceIndex={0.95} addEchoMessage={addEchoMessage} width={modalContentWidth} height={modalContentHeight} />;
      case 'celestial_anomaly':
        return <CelestialAnomalyWeaverPanel width={modalContentWidth} height={modalContentHeight} addEchoMessage={addEchoMessage} />;
      case 'crystal_garden':
        return <CrystalFormationPanel width={modalContentWidth} height={modalContentHeight} currentEntropy={effectiveSystemEntropy} />;
      case 'geometry_explorer':
        return <FlowerOfLifeEntropyExplorer currentEntropy={effectiveSystemEntropy} width={modalContentWidth} height={modalContentHeight} currentDisplayMode={geoMode} onSetDisplayMode={(m) => setGeoMode(m as GeoMode)} />;
      case 'exotic_mechanisms':
        return <ExoticMechanismsPanel currentEntropy={effectiveSystemEntropy} width={modalContentWidth} height={modalContentHeight} addEchoMessage={addEchoMessage} />;
      case 'celestial_entropy':
        return <CelestialEntropyCyclePanel currentEntropy={effectiveSystemEntropy} width={modalContentWidth} height={modalContentHeight} />;
      case 'dimension_diagram':
        return <EntropyDimensionDiagramPanel currentEntropy={effectiveSystemEntropy} width={modalContentWidth} height={modalContentHeight} isFractalModeEnabled={true} />;
      case 'glyph_vis':
        return <GlyphVisualizationPanel panelHeight={modalContentHeight} glyphData={{id:'demo', title:'Glyph Vis Demo', description:'Visualization Mode', resonance:'Harmonic', traits:[], linkedAxioms:[], ritualAffinity:'None'}} pulseDetails={{label:'Demo', glyphId:'demo', state:'Active', mode:'Visual', signatureFrequency:'432Hz', shadowArchiveDepth:'0', decryptionTraits:[]}} visualizationDetails={{initialPhase:{title:'Init',form:'Sphere',visual:'Glow',animation:'Pulse'}, sonicProfile:{description:'Hum'}, finalForm:{description:'Stable', sigilPulse:[], overlay:'None'}}} systemNote={{uses:[], concludingQuote:'System Visualization'}} />;
      case 'crm_dashboard':
        return <CosmicResonanceDashboardPanel width={modalContentWidth} height={modalContentHeight} addEchoMessage={addEchoMessage} />;
      case 'temporal_ops':
        return <TemporalOperationsConsolePanel width={modalContentWidth} height={modalContentHeight} addEchoMessage={addEchoMessage} />;
      case 'drift_differential':
        return <DriftDifferentialOverlay currentEntropy={effectiveSystemEntropy} glyphDriftHistory={[]} glyphMutationNodes={[]} currentRitualContext="System Analysis" isGeminiGenerating={isGeminiGenerating} addEchoMessage={addEchoMessage} logGeminiNarrativeDriftEvent={() => {}} />;
      case 'harmonic_core':
        return <HarmonicCorePanel lambdaValue={1.0} status="Stabilized" eleganceIndex={0.98} />;
      case 'entropy_diagnostics':
        return <EntropyDiagnosticsPanel baseEntropy={currentEntropy} effectiveEntropy={effectiveSystemEntropy} masterEntropyOverridePercent={0} entropyHistory={[currentEntropy]} playbackTime={0} isPlaying={true} />;
      case 'peptide_sim':
        return <PeptideSimulationPanel addEchoMessage={addEchoMessage} width={modalContentWidth} height={modalContentHeight} />;
      case 'codex_pandium':
        return <CodexPandiumPanel width={modalContentWidth} height={modalContentHeight} />;
      case 'datachega':
