const generateDynamicLocations = async () => {
    if(isGeneratingLocations) return;
    setIsGeneratingLocations(true);
    globalSoundEngine.playSFX('click');
    setGeneratedLocations({}); setGeneratedQuests([]); setSelectedStartLoc(null);

    const prompt = `Generate 3 unique, evocative RPG locations for a sci-fi/fantasy setting heavily influenced by entropy level ${currentEntropy.toFixed(2)}.
    Return ONLY a JSON object where keys are the location names.
    Values must have:
    - description: string
    - color: string (Tailwind text color class, e.g., text-red-400)
    - risk: string (Low, Medium, High, Extreme)
    - icon: string (RemixIcon class name, e.g., ri-skull-line)

    Example format:
    {
      "The Shattered Spire": { "description": "A crystalline tower fracturing into the sky.", "color": "text-purple-400", "risk": "High", "icon": "ri-building-line" },
      "Echo Valley": { "description": "A silent valley where sounds repeat endlessly.", "color": "text-blue-300", "risk": "Low", "icon": "ri-voiceprint-line" }
    }`;

    try {
      const response = await invokeGemini(prompt, "You are a creative world-building AI. Respond ONLY in valid JSON. Do not wrap in markdown code blocks.");
      if (response) {
          let locs = safeParseJSON<Record<string, { description: string, color: string, risk: string, icon: string }>>(response);

          // Unwrap if wrapped in a root object (e.g. { "locations": { ... } })
          if (locs) {
               const keys = Object.keys(locs);
               // If there is only one key and its value is an object that doesn't look like a location data object (missing 'description'), assume it's a wrapper.
               if (keys.length === 1 && typeof locs[keys[0]] === 'object' && !('description' in (locs[keys[0]] as any))) {
                   locs = locs[keys[0]] as any;
               }
          }

          if (locs) {
              setGeneratedLocations(locs);
              // Atlas entries are created upon game initialization, not scan
          } else { setGeneratedLocations(FALLBACK_LOCATIONS); }
      } else { setGeneratedLocations(FALLBACK_LOCATIONS); }
    } catch (e) { console.error(e); setGeneratedLocations(FALLBACK_LOCATIONS); } finally { setIsGeneratingLocations(false); }
};

import React, { useState, useEffect, useRef } from 'react';
