                                <div className="text-[10px] uppercase font-bold mt-2 text-slate-500">Risk: {data.risk}</div>
                            </div>
                        ))
                    ) : (
                        <div className="col-span-3 text-center text-slate-500 italic py-4">
                            System Idle. Scan sector to discover locations.
                        </div>
                    )}
                 </div>

                 {/* Narrative Log */}
                 <div className="bg-black/30 rounded-lg p-3 h-48 overflow-y-auto border border-slate-800 font-mono text-xs text-slate-300">
                    {gameState.narrativeHistory.length === 0 && <span className="opacity-50">Log initialized...</span>}
                    {gameState.narrativeHistory.map((entry, idx) => (
                        <div key={idx} className="mb-1">
                            <span className="text-slate-500">[{new Date(entry.timestamp).toLocaleTimeString()}]</span> {entry.text}
                        </div>
                    ))}
                    <div ref={chatEndRef} />
                 </div>

                 {/* Status Footer */}
                 <div className="grid grid-cols-2 gap-4 text-xs font-mono text-slate-400 border-t border-slate-800 pt-2">
                    <div>Location: <span className="text-indigo-300">{gameState.currentLocation}</span></div>
                    <div className="text-right">Integrity: <span className={gameState.vitals?.integrity && gameState.vitals.integrity < 30 ? "text-red-400" : "text-emerald-400"}>{gameState.vitals?.integrity}%</span></div>
                 </div>
            </div>
        </div>
    );
};

