import React, { useState, useEffect, useRef } from 'react';
import type { RPGNexusPanelProps, RPGGameState, RPGQuest, RPGGameLocation, RPGDynamicAction } from '../../types';
import { AgentName } from '../../types';
import { Button } from '../ui/Button';
import { useGemini } from '../../context/GeminiIntegrationContext';
import { globalSoundEngine } from '../../lib/SoundEngine';

// --- Helper: Robust JSON Parsing ---
const cleanAndParseJSON = <T,>(text: string | null): T | null => {
  if (!text) return null;
  try {
    // 1. Strip Markdown code blocks
    let cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();

    // 2. Parse
    let data = JSON.parse(cleanText);

    // 3. Intelligent Unwrap: If the root is just a wrapper key like "locations", "rpg_locations", "data", unwrap it.
    const keys = Object.keys(data);
    if (keys.length === 1) {
      const rootKey = keys[0];
      if (['locations', 'rpg_locations', 'points_of_interest', 'data', 'result'].includes(rootKey.toLowerCase()) || 
          (typeof data[rootKey] === 'object' && !Array.isArray(data[rootKey]) && !data[rootKey].description)) {
          // It's likely a wrapper if the value is an object but doesn't look like a location leaf node (which usually has 'description')
          data = data[rootKey];
      }
    }
    return data as T;
  } catch (e) {
    console.error("RPGNexus: JSON Parsing Failed", e);
    return null;
  }
};

const FALLBACK_LOCATIONS = {
  "The Void Edge": { description: "A precipice where reality dissolves into static.", color: "text-slate-400", risk: "Extreme", icon: "ri-mist-line" },
  "Crystal Spire": { description: "A tower of singing glass reaching into the Aethel.", color: "text-cyan-300", risk: "Low", icon: "ri-building-2-line" },
  "Axiom Forge": { description: "Industrial complex where truths are hammered into shape.", color: "text-amber-400", risk: "Medium", icon: "ri-hammer-line" }
};

const RPGNexusPanel: React.FC<RPGNexusPanelProps> = ({
  width,
  height,
  addEchoMessage,
  activeProfile,
  onUpdateProfile,
  currentEntropy,
  systemMode,
  onArtifactCreated,
  artifacts,
  savedState,
  onSaveState,
  onUpdateSystemMetrics
}) => {
  const { invokeGemini, generateImage, isGenerating } = useGemini();
  const chatEndRef = useRef<HTMLDivElement>(null);

  // -- State --
  const [gameState, setGameState] = useState<RPGGameState>(savedState || {
    currentLocation: 'The Void Edge',
    narrativeHistory: [{ text: "System Initialized. Awaiting Insertion Coordinates...", type: 'system', timestamp: Date.now() }],
    activeQuests: [],
    lastActionTimestamp: Date.now(),
    vitals: { integrity: 100, sanity: 100 },
    availableActions: [],
    achievements: [],
    combatState: { isActive: false, enemyName: '', enemyHp: 0, enemyMaxHp: 0, turn: 0, logs: [] },
    knownLocations: [],
    currentSceneDescription: "The initialization void. Static fills the air.",
    currentSceneImageUrl: null
  });

  const [scanResults, setScanResults] = useState<Record<string, any> | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [isProcessingTurn, setIsProcessingTurn] = useState(false);

  // -- Persistence --
  useEffect(() => {
    if (onSaveState) onSaveState(gameState);
  }, [gameState, onSaveState]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [gameState.narrativeHistory]);

  // -- Core Engine Functions --

  // 1. SCAN PHASE
  const handleScanSector = async () => {
    if (isScanning || isGenerating) return;
    setIsScanning(true);
    globalSoundEngine.playSFX('click');
    addEchoMessage(AgentName.RPGNexusAgent, "Scanning sector for stability variances...", "text-indigo-300");

    const prompt = `Generate 3 unique, evocative RPG locations for a sci-fi/fantasy setting with entropy level ${currentEntropy.toFixed(2)}.
    Output strictly as JSON. Keys are location names.
    Values must be objects with:
    - "description": string (1 sentence)
    - "color": string (Tailwind text class, e.g. "text-red-400")
    - "risk": string ("Low", "Medium", "High", "Extreme")
    - "icon": string (RemixIcon class, e.g. "ri-skull-line")
    Example:
    {
      "Neon Market": { "description": "A bustling hub.", "color": "text-pink-400", "risk": "Low", "icon": "ri-store-line" }
    }`;

    try {
      const response = await invokeGemini(prompt, "You are a JSON generator. Do not include markdown formatting.");
      const locations = cleanAndParseJSON<Record<string, any>>(response);
      setScanResults(locations || FALLBACK_LOCATIONS);
    } catch (err) {
      setScanResults(FALLBACK_LOCATIONS);
    } finally {
      setIsScanning(false);
    }
  };

  // 2. TRAVEL & SCENE GENERATION
  const handleTravel = async (locationName: string, locationData: any) => {
    setScanResults(null); // Clear scan to show main game view
    setIsProcessingTurn(true);
    addEchoMessage(AgentName.RPGNexusAgent, `Vectoring to ${locationName}...`, "text-cyan-300");
    globalSoundEngine.playSFX('pulse');

    // Update basic state immediately
    setGameState(prev => ({
      ...prev,
      currentLocation: locationName as RPGGameLocation,
      narrativeHistory: [...prev.narrativeHistory, { text: `Arrived at ${locationName}.`, type: 'action', timestamp: Date.now() }]
    }));

    // Parallel Generation: Description + Actions + Quest + Image
    try {
      // A. Description & Actions
      const textPrompt = `You are the Game Master. The player has just arrived at "${locationName}" (${locationData.description}).
      Current Entropy: ${currentEntropy}.
      1. Write a vivid, 2-sentence sensory description of the scene.
      2. Provide 3 distinct actions the player can take (Explore, Talk, Analyze, Ritual, etc.).
      3. Create a short quest title related to this location.

      Return JSON:
      {
        "description": "...",
        "actions": [ { "id": "act_1", "label": "...", "type": "explore", "risk": 0.2 }, ... ],
        "quest": { "title": "...", "description": "...", "rewards": { "xp": 100, "flux": 50 } }
      }`;

      const textResponseRaw = await invokeGemini(textPrompt, "Return valid JSON only.");
      const textData = cleanAndParseJSON<any>(textResponseRaw);

      if (textData) {
        // B. Image Generation (Fire and forget, update when ready)
        const imagePrompt = `Sci-fi fantasy concept art, ${locationName}, ${textData.description}, cinematic lighting, atmospheric, ${currentEntropy > 0.6 ? 'glitch, chaos, fractal' : 'clean, ethereal, serene'}.`;
        generateImage(imagePrompt).then(url => {
          if (url) {
            setGameState(prev => ({ ...prev, currentSceneImageUrl: url }));
          }
        });

        // Update State
        setGameState(prev => ({
          ...prev,
          currentSceneDescription: textData.description,
          availableActions: textData.actions,
          // Only add quest if we don't have too many
          activeQuests: prev.activeQuests.length < 3 ? [...prev.activeQuests, { ...textData.quest, id: `quest-${Date.now()}`, status: 'active' }] : prev.activeQuests,
          narrativeHistory: [...prev.narrativeHistory, { text: textData.description, type: 'narration', timestamp: Date.now() }]
        }));
      }

    } catch (e) {
      console.error("Travel generation failed", e);
      addEchoMessage(AgentName.System, "Navigational data corrupted. Using fallback protocols.", "text-rose-400");
    } finally {
      setIsProcessingTurn(false);
    }
  };

  // 3. ACTION HANDLING
  const handleAction = async (action: RPGDynamicAction) => {
    if (isProcessingTurn) return;
    setIsProcessingTurn(true);
    globalSoundEngine.playSFX('click');

    // Add player action to log
    setGameState(prev => ({
        ...prev,
        narrativeHistory: [...prev.narrativeHistory, { text: `> ${action.label}`, type: 'action', timestamp: Date.now() }]
    }));

    const prompt = `Game Master Logic:
    Location: ${gameState.currentLocation}
    Action Taken: "${action.label}"
    Entropy: ${currentEntropy}
    Profile: ${activeProfile?.name || "Seeker"} (${activeProfile?.race} ${activeProfile?.class})

    Determine the outcome. 
    1. Write a 1-2 sentence narrative result.
    2. Define any stat changes (integrity/sanity/flux).
    3. Are there new actions available? (If yes, list 2-3).

    Return JSON:
    {
      "resultText": "...",
      "deltaIntegrity": -5, 
      "deltaSanity": 0,
      "deltaFlux": 10,
      "newActions": [...] (optional)
    }`;

    try {
        const response = await invokeGemini(prompt, "Return valid JSON only.");
        const outcome = cleanAndParseJSON<any>(response);

        if (outcome) {
            // Apply updates
            const newIntegrity = Math.max(0, Math.min(100, (gameState.vitals?.integrity || 100) + (outcome.deltaIntegrity || 0)));
            const newSanity = Math.max(0, Math.min(100, (gameState.vitals?.sanity || 100) + (outcome.deltaSanity || 0)));

            setGameState(prev => ({
                ...prev,
                vitals: { integrity: newIntegrity, sanity: newSanity },
                availableActions: outcome.newActions || prev.availableActions,
                narrativeHistory: [...prev.narrativeHistory, { text: outcome.resultText, type: 'narration', timestamp: Date.now() }]
            }));

            // Update Profile Flux if needed
            if (outcome.deltaFlux && onUpdateProfile && activeProfile) {
                onUpdateProfile({ ...activeProfile, flux: activeProfile.flux + outcome.deltaFlux });
                addEchoMessage(AgentName.RPGNexusAgent, `Flux ${outcome.deltaFlux > 0 ? '+' : ''}${outcome.deltaFlux}`, outcome.deltaFlux > 0 ? 'text-amber-300' : 'text-rose-400');
            }

            // Update System Entropy if action was risky
            if (action.risk > 0.5) {
                onUpdateSystemMetrics(0.01, -0.01); 
            }
        }
    } catch (e) {
        addEchoMessage(AgentName.System, "Action resolution failed.", "text-rose-400");
    } finally {
        setIsProcessingTurn(false);
    }
  };

  // -- Renders --

  const renderInitialization = () => (
    <div className="flex flex-col items-center justify-center h-full p-6 animate-fade-in-up">
      <div className="text-4xl text-indigo-500 mb-4 animate-pulse"><i className="ri-radar-line"></i></div>
      <h3 className="text-xl font-cinzel text-indigo-300 mb-2">Campaign Initialization</h3>
      <p className="text-sm text-slate-400 mb-6 text-center max-w-md">
        The Nexus Engine requires an insertion vector. Scan the local entropy field to materialize potential timelines.
      </p>

      {scanResults ? (
         <div className="grid grid-cols-1 md:grid-cols-3 gap-4 w-full">
            {Object.entries(scanResults).map(([name, data]) => (
                <button 
                    key={name}
                    onClick={() => handleTravel(name, data)}
                    className="flex flex-col p-4 bg-slate-800/60 border border-slate-600 rounded-xl hover:bg-slate-700 hover:border-cyan-500 hover:shadow-lg hover:shadow-cyan-500/20 transition-all group text-left"
                >
                    <div className="flex items-center justify-between mb-2 w-full">
                        <i className={`${data.icon || 'ri-map-pin-line'} text-2xl ${data.color || 'text-slate-200'}`}></i>
                        <span className="text-[10px] uppercase font-bold tracking-wider bg-slate-900 px-2 py-1 rounded text-slate-400 group-hover:text-white transition-colors">{data.risk} Risk</span>
                    </div>
                    <h4 className="font-cinzel font-bold text-lg text-slate-200 group-hover:text-cyan-300 mb-1">{name}</h4>
                    <p className="text-xs text-slate-400 font-cormorant leading-tight">{data.description}</p>
                </button>
            ))}
         </div>
      ) : (
        <Button onClick={handleScanSector} disabled={isScanning} className="px-8 py-3 text-sm tracking-widest bg-indigo-600 hover:bg-indigo-500 shadow-xl shadow-indigo-500/20">
            {isScanning ? <><i className="ri-loader-4-line animate-spin mr-2"></i>SCANNING SECTOR...</> : <><i className="ri-search-eye-line mr-2"></i>SCAN FOR ANOMALIES</>}
        </Button>
      )}
    </div>
  );

  const renderGameInterface = () => (
    <div className="flex flex-col h-full">
        {/* Top Info Bar */}
        <div className="flex justify-between items-center bg-slate-900/50 p-2 border-b border-indigo-500/30 text-xs">
            <div className="flex items-center gap-4">
                <span className="text-indigo-300 font-bold"><i className="ri-map-pin-user-fill mr-1"></i>{gameState.currentLocation}</span>
                <span className="text-slate-400">Turn: {gameState.narrativeHistory.filter(n => n.type==='action').length}</span>
            </div>
            <div className="flex items-center gap-3">
                <span className={gameState.vitals!.integrity < 30 ? 'text-rose-400 animate-pulse' : 'text-emerald-400'}>
                    <i className="ri-heart-pulse-fill mr-1"></i>{gameState.vitals?.integrity}%
                </span>
                <span className="text-purple-400">
                    <i className="ri-brain-fill mr-1"></i>{gameState.vitals?.sanity}%
                </span>
            </div>
        </div>

        <div className="flex-grow flex flex-col md:flex-row min-h-0">
            {/* Left: Visual & Actions */}
            <div className="w-full md:w-2/5 p-4 flex flex-col gap-4 border-r border-slate-700/30 overflow-y-auto custom-scrollbar">
                {/* Scene Image */}
                <div className="aspect-video w-full bg-black rounded-lg border border-slate-600 overflow-hidden relative shadow-lg">
                    {gameState.currentSceneImageUrl ? (
                        <img src={gameState.currentSceneImageUrl} alt="Scene" className="w-full h-full object-cover animate-fade-in-up" />
                    ) : (
                        <div className="w-full h-full flex items-center justify-center text-slate-600 flex-col">
                            <i className="ri-image-line text-3xl mb-2"></i>
                            <span className="text-xs">Visualizing...</span>
                        </div>
                    )}
                    <div className="absolute bottom-0 inset-x-0 bg-gradient-to-t from-black/90 to-transparent p-3 pt-6">
                        <p className="text-xs text-slate-200 font-cormorant italic leading-tight">
                            {gameState.currentSceneDescription}
                        </p>
                    </div>
                </div>

                {/* Actions */}
                <div className="space-y-2">
                    <h4 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-2">Available Actions</h4>
                    {gameState.availableActions?.map((action, idx) => (
                        <button
                            key={idx}
                            onClick={() => handleAction(action as RPGDynamicAction)}
                            disabled={isProcessingTurn}
                            className="w-full text-left p-3 rounded-md bg-slate-800/80 border border-slate-700 hover:bg-slate-700 hover:border-indigo-500 transition-all group disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            <div className="flex justify-between items-center mb-0.5">
                                <span className="text-sm font-bold text-slate-200 group-hover:text-indigo-300">{action.label}</span>
                                {action.risk > 0 && (
                                    <span className={`text-[9px] uppercase px-1.5 rounded ${action.risk > 0.7 ? 'bg-rose-900 text-rose-300' : 'bg-amber-900/50 text-amber-300'}`}>
                                        {action.risk > 0.7 ? 'High Risk' : 'Risk'}
                                    </span>
                                )}
                            </div>
                            <div className="h-0.5 w-0 group-hover:w-full bg-indigo-500 transition-all duration-300"></div>
                        </button>
                    ))}
                    {(!gameState.availableActions || gameState.availableActions.length === 0) && (
                        <button onClick={() => handleScanSector()} className="w-full p-3 rounded-md bg-indigo-900/30 border border-indigo-500/50 text-indigo-300 hover:bg-indigo-900/50">
                            Scan for New Path
                        </button>
                    )}
                </div>
            </div>

            {/* Right: Narrative & Quests */}
            <div className="w-full md:w-3/5 flex flex-col min-h-0 bg-slate-900/30">
                {/* Narrative Log */}
                <div className="flex-grow overflow-y-auto custom-scrollbar p-4 space-y-3 font-cormorant text-sm leading-relaxed">
                    {gameState.narrativeHistory.map((entry, i) => (
                        <div key={i} className={`p-2 rounded-lg border-l-2 ${entry.type === 'action' ? 'border-indigo-500 bg-slate-800/30 text-slate-300' : 'border-slate-600 text-slate-400'}`}>
                            {entry.text}
                        </div>
                    ))}
                    {isProcessingTurn && <div className="text-indigo-400 animate-pulse text-xs ml-2">Calculating outcome...</div>}
                    <div ref={chatEndRef} />
                </div>

                {/* Quests Footer */}
                <div className="p-3 bg-slate-900 border-t border-slate-700/50 shrink-0">
                    <h4 className="text-xs font-bold text-amber-500 uppercase tracking-widest mb-2"><i className="ri-bookmark-3-fill mr-1"></i>Active Quests</h4>
                    <div className="flex gap-2 overflow-x-auto pb-1 custom-scrollbar-thin">
                        {gameState.activeQuests.length === 0 && <span className="text-xs text-slate-600 italic">No active quests. Explore to find opportunities.</span>}
                        {gameState.activeQuests.map(quest => (
                            <div key={quest.id} className="min-w-[200px] bg-amber-900/10 border border-amber-700/30 rounded p-2 flex flex-col justify-between">
                                <span className="text-xs font-bold text-amber-200 truncate">{quest.title}</span>
                                <div className="flex justify-between items-center mt-1">
                                    <span className="text-[9px] text-amber-400/70 uppercase">{quest.status}</span>
                                    <span className="text-[9px] text-slate-400">{quest.rewards.xp} XP</span>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    </div>
  );

  return (
    <div className="rpg-nexus-panel bg-slate-950/95 backdrop-blur-xl border border-indigo-600/50 rounded-xl shadow-2xl flex flex-col overflow-hidden transition-all duration-500" style={{ width: width || '100%', height: height || '600px' }}>
      {/* Universal Header */}
      <div className="p-3 border-b border-indigo-800/50 bg-slate-900/80 flex justify-between items-center shrink-0">
        <h3 className="text-lg font-cinzel font-bold text-indigo-300 flex items-center">
            <i className="ri-gamepad-line mr-2"></i>Nexus Engine
        </h3>
        {scanResults && (
             <button onClick={() => setScanResults(null)} className="text-xs text-slate-400 hover:text-white underline">Back to Game</button>
        )}
      </div>

      {/* Content Switcher */}
      <div className="flex-grow overflow-hidden relative">
          {(!scanResults && gameState.currentLocation === 'The Void Edge' && gameState.narrativeHistory.length <= 1) 
            ? renderInitialization() 
            : (scanResults ? renderInitialization() : renderGameInterface())
          }
      </div>
    </div>
  );
};

