// --- Helper: Robust JSON Parsing ---
const cleanAndParseJSON = <T,>(text: string | null): T | null => {
  if (!text) return null;
  try {
    let cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    let data = JSON.parse(cleanText);
    const keys = Object.keys(data);
    if (keys.length === 1) {
      const rootKey = keys[0];
      if (['locations', 'rpg_locations', 'points_of_interest', 'data', 'result', 'outcome'].includes(rootKey.toLowerCase()) || 
          (typeof data[rootKey] === 'object' && !Array.isArray(data[rootKey]) && !data[rootKey].description && !data[rootKey].resultText)) {
          data = data[rootKey];
      }
    }
    return data as T;
  } catch (e) {
    console.error("RPGNexus: JSON Parsing Failed", e);
    return null;
  }
};

