  "The Void Edge": { description: "A precipice where reality dissolves into static.", color: "text-slate-400", risk: "Extreme", icon: "ri-mist-line" },
  "Crystal Spire": { description: "A tower of singing glass reaching into the Aethel.", color: "text-cyan-300", risk: "Low", icon: "ri-building-2-line" },
  "Axiom Forge": { description: "Industrial complex where truths are hammered into shape.", color: "text-amber-400", risk: "Medium", icon: "ri-hammer-line" }
};

const DEFAULT_ACTIONS: RPGDynamicAction[] = [
    { id: 'def_explore', label: 'Survey the Area', type: 'explore', risk: 0.1, isDynamic: false },
    { id: 'def_scan', label: 'Scan for Anomalies', type: 'ritual', risk: 0.2, isDynamic: false },
    { id: 'def_rest', label: 'Recalibrate Systems', type: 'talk', risk: 0, isDynamic: false }
];

const RPGNexusPanel: React.FC<RPGNexusPanelProps> = ({
  width,
  height,
  addEchoMessage,
  activeProfile,
  onUpdateProfile,
  currentEntropy,
  onArtifactCreated,
  savedState,
  onSaveState,
  onUpdateSystemMetrics
}) => {
  const { invokeGemini, generateImage, generateVideo, generateSpeech, isGenerating } = useGemini();
  const chatEndRef = useRef<HTMLDivElement>(null);

  // -- State --
  const [gameState, setGameState] = useState<RPGGameState>(savedState || {
    currentLocation: 'The Void Edge',
    narrativeHistory: [{ text: "System Initialized. Awaiting Insertion Coordinates...", type: 'system', timestamp: Date.now() }],
    activeQuests: [],
    lastActionTimestamp: Date.now(),
    vitals: { integrity: 100, sanity: 100 },
    availableActions: DEFAULT_ACTIONS,
    achievements: [],
    combatState: { isActive: false, enemyName: '', enemyHp: 0, enemyMaxHp: 0, turn: 0, logs: [] },
    knownLocations: [],
    currentSceneDescription: "The initialization void. Static fills the air.",
    currentSceneImageUrl: null,
    sceneHistory: [] // New: Track scenes for video compilation
  });

  const [scanResults, setScanResults] = useState<Record<string, RPGScanResultLocation> | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [isProcessingTurn, setIsProcessingTurn] = useState(false);
  const [customActionInput, setCustomActionInput] = useState("");

  // -- Video & Cinema State --
  const [isAnimatingScene, setIsAnimatingScene] = useState(false);
  const [currentSceneVideoUrl, setCurrentSceneVideoUrl] = useState<string | null>(null);
  const [isCompilingStory, setIsCompilingStory] = useState(false);
  const [compilationProgress, setCompilationProgress] = useState(0);

  // -- Refs --
  const cinemaEngineRef = useRef<QuestCinemaEngine | null>(null);

  useEffect(() => {
    return () => {
        if (cinemaEngineRef.current) cinemaEngineRef.current.dispose();
    }
  }, []);

  // -- Persistence --
  useEffect(() => {
    if (onSaveState) onSaveState(gameState);
  }, [gameState, onSaveState]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [gameState.narrativeHistory]);

  const getRiskColor = (risk: number) => {
      if (risk >= 0.7) return 'border-rose-500 hover:bg-rose-900/30 text-rose-200';
      if (risk >= 0.4) return 'border-amber-500 hover:bg-amber-900/30 text-amber-200';
      return 'border-emerald-500 hover:bg-emerald-900/30 text-emerald-200';
  };

  const getRiskLabel = (risk: number) => {
      if (risk >= 0.7) return { text: 'HIGH RISK', color: 'text-rose-400' };
      if (risk >= 0.4) return { text: 'MED RISK', color: 'text-amber-400' };
      return { text: 'LOW RISK', color: 'text-emerald-400' };
  };

  // --- CORE ENGINE ---

  const handleScanSector = async () => {
    if (isScanning || isGenerating) return;
    setIsScanning(true);
    globalSoundEngine.playSFX('click');
    addEchoMessage(AgentName.RPGNexusAgent, "Scanning sector for stability variances...", "text-indigo-300");

    const prompt = `Generate 3 unique, evocative RPG locations for a sci-fi/fantasy setting with entropy level ${currentEntropy.toFixed(2)}.
    Output strictly as JSON. Keys are location names.
    Values must be objects with:
    - "description": string (1 sentence)
    - "color": string (Tailwind text class, e.g. "text-red-400")
    - "risk": string ("Low", "Medium", "High", "Extreme")
    - "icon": string (RemixIcon class, e.g. "ri-skull-line")`;

    try {
      const response = await invokeGemini(prompt, "You are a JSON generator. Do not include markdown formatting.");
      const locations = cleanAndParseJSON<Record<string, RPGScanResultLocation>>(response);
      setScanResults(locations || FALLBACK_LOCATIONS);
    } catch (err) {
      setScanResults(FALLBACK_LOCATIONS);
    } finally {
      setIsScanning(false);
    }
  };

  const handleTravel = async (locationName: string, locationData: RPGScanResultLocation) => {
    setScanResults(null); 
    setIsProcessingTurn(true);
    setCurrentSceneVideoUrl(null); // Reset video on travel
    addEchoMessage(AgentName.RPGNexusAgent, `Vectoring to ${locationName}...`, "text-cyan-300");
    globalSoundEngine.playSFX('pulse');

    setGameState(prev => ({
      ...prev,
      currentLocation: locationName as RPGGameLocation,
      narrativeHistory: [...prev.narrativeHistory, { text: `Arrived at ${locationName}.`, type: 'action', timestamp: Date.now() }]
    }));

    try {
      const textPrompt = `You are the Game Master. The player has just arrived at "${locationName}" (${locationData.description}).
      Current Entropy: ${currentEntropy}.
      1. Write a vivid, 2-sentence sensory description of the scene.
      2. Provide 3 distinct actions the player can take (Explore, Talk, Analyze, Ritual, etc.).
      3. Create a short quest title related to this location.

      Return JSON:
      {
        "description": "...",
        "actions": [ { "id": "act_1", "label": "...", "type": "explore", "risk": 0.2 }, ... ],
        "quest": { "title": "...", "description": "...", "rewards": { "xp": 100, "flux": 50 } }
      }`;

      const textResponseRaw = await invokeGemini(textPrompt, "Return valid JSON only.");
      const textData = cleanAndParseJSON<any>(textResponseRaw);

      if (textData) {
        // Image Gen
        const imagePrompt = `Sci-fi fantasy concept art, ${locationName}, ${textData.description}, cinematic lighting, atmospheric, ${currentEntropy > 0.6 ? 'glitch, chaos, fractal' : 'clean, ethereal, serene'}.`;
        generateImage(imagePrompt).then(url => {
          if (url) {
            setGameState(prev => {
                const newHistoryEntry: RPGSceneData = {
                    imageUrl: url,
                    location: locationName as RPGGameLocation,
                    description: textData.description,
                    timestamp: Date.now()
                };
                return { 
                    ...prev, 
                    currentSceneImageUrl: url,
                    sceneHistory: [...(prev.sceneHistory || []), newHistoryEntry] 
                };
            });
          }
        });

        setGameState(prev => ({
          ...prev,
          currentSceneDescription: textData.description,
          availableActions: textData.actions || DEFAULT_ACTIONS,
          activeQuests: prev.activeQuests.length < 3 ? [...prev.activeQuests, { ...textData.quest, id: `quest-${Date.now()}`, status: 'active' }] : prev.activeQuests,
          narrativeHistory: [...prev.narrativeHistory, { text: textData.description, type: 'narration', timestamp: Date.now() }]
        }));
      }
    } catch (e) {
      console.error("Travel generation failed", e);
      addEchoMessage(AgentName.System, "Navigational data corrupted. Using fallback protocols.", "text-rose-400");
    } finally {
      setIsProcessingTurn(false);
    }
  };

  const handleAction = async (actionLabel: string, risk: number = 0.5) => {
    if (isProcessingTurn) return;
    setIsProcessingTurn(true);
    setCustomActionInput(""); // Clear input if used
    globalSoundEngine.playSFX('click');

    setGameState(prev => ({
        ...prev,
        narrativeHistory: [...prev.narrativeHistory, { text: `> ${actionLabel}`, type: 'action', timestamp: Date.now() }]
    }));

    const prompt = `Game Master Logic:
    Location: ${gameState.currentLocation}
    Action Taken: "${actionLabel}"
    Entropy: ${currentEntropy}
    Profile: ${activeProfile?.name || "Seeker"} (${activeProfile?.race} ${activeProfile?.class})
    Current Scene: ${gameState.currentSceneDescription}

    Determine the outcome. 
    1. Write a 1-2 sentence narrative result.
    2. Define any stat changes (integrity/sanity/flux).
    3. PROVIDE 3 NEW Available Actions for the player based on the new situation.

    Return JSON:
    {
      "resultText": "...",
      "deltaIntegrity": -5, 
      "deltaSanity": 0,
      "deltaFlux": 10,
      "newActions": [ { "id": "new_1", "label": "...", "type": "explore", "risk": 0.2 }, ... ]
    }`;

    try {
        const response = await invokeGemini(prompt, "Return valid JSON only. Do not wrap in markdown.");
        const outcome = cleanAndParseJSON<any>(response);

        if (outcome) {
            const newIntegrity = Math.max(0, Math.min(100, (gameState.vitals?.integrity || 100) + (outcome.deltaIntegrity || 0)));
            const newSanity = Math.max(0, Math.min(100, (gameState.vitals?.sanity || 100) + (outcome.deltaSanity || 0)));

            setGameState(prev => ({
                ...prev,
                vitals: { integrity: newIntegrity, sanity: newSanity },
                availableActions: (outcome.newActions && outcome.newActions.length > 0) ? outcome.newActions : DEFAULT_ACTIONS,
                narrativeHistory: [...prev.narrativeHistory, { text: outcome.resultText, type: 'narration', timestamp: Date.now() }]
            }));

            if (outcome.deltaFlux && onUpdateProfile && activeProfile) {
                onUpdateProfile({ ...activeProfile, flux: activeProfile.flux + outcome.deltaFlux });
                addEchoMessage(AgentName.RPGNexusAgent, `Flux ${outcome.deltaFlux > 0 ? '+' : ''}${outcome.deltaFlux}`, outcome.deltaFlux > 0 ? 'text-amber-300' : 'text-rose-400');
            }
            if (risk > 0.5) onUpdateSystemMetrics(0.01, -0.01); 
        } else {
             setGameState(prev => ({
                ...prev,
                availableActions: DEFAULT_ACTIONS,
                narrativeHistory: [...prev.narrativeHistory, { text: "The ether churns, obscuring the outcome. (Data corruption)", type: 'system', timestamp: Date.now() }]
            }));
        }
    } catch (e) {
        addEchoMessage(AgentName.System, "Action resolution failed. Systems rebooting...", "text-rose-400");
        setGameState(prev => ({ ...prev, availableActions: DEFAULT_ACTIONS }));
    } finally {
        setIsProcessingTurn(false);
    }
  };

  // --- NEW FEATURES ---

  const handleGenerateSceneVideo = async () => {
      if (isAnimatingScene || !gameState.currentSceneImageUrl) return;
      setIsAnimatingScene(true);
      addEchoMessage(AgentName.RPGNexusAgent, "Animating scene via Veo-3.1...", "text-fuchsia-300");

      try {
          const prompt = `Cinematic subtle motion, atmospheric video of ${gameState.currentSceneDescription}. ${currentEntropy > 0.6 ? 'Glitch art style, disturbing movement.' : 'Serene, flowing motion.'}`;
          const videoUrl = await generateVideo(prompt, gameState.currentSceneImageUrl);
          if (videoUrl) {
              setCurrentSceneVideoUrl(videoUrl);
              addEchoMessage(AgentName.RPGNexusAgent, "Scene animation compiled.", "text-emerald-300");
          } else {
              throw new Error("No video URL returned.");
          }
      } catch (e) {
          console.error(e);
          addEchoMessage(AgentName.System, "Video generation failed.", "text-rose-400");
      } finally {
          setIsAnimatingScene(false);
      }
  };

  const handleCompileStoryVideo = async () => {
      if (isCompilingStory || !gameState.sceneHistory || gameState.sceneHistory.length === 0) {
          addEchoMessage(AgentName.System, "No scene history to compile.", "text-yellow-400");
          return;
      }

      setIsCompilingStory(true);
      setCompilationProgress(0);
      addEchoMessage(AgentName.RPGNexusAgent, "Compiling narrative history into Quest Cinema...", "text-amber-300");

      try {
          if (!cinemaEngineRef.current) {
              cinemaEngineRef.current = new QuestCinemaEngine();
          }

          const slides = gameState.sceneHistory.map(scene => ({
              imageUrl: scene.imageUrl,
              text: scene.description
          }));

          const blob = await cinemaEngineRef.current.compileVideo(
              slides,
              (progress) => setCompilationProgress(Math.round(progress * 100)),
              async (text) => await generateSpeech(text) 
          );

          if (blob) {
              const url = URL.createObjectURL(blob);
              const a = document.createElement('a');
              a.href = url;
              a.download = `Nexus_Story_${Date.now()}.webm`; // Or mp4 based on engine support
              document.body.appendChild(a);
              a.click();
              document.body.removeChild(a);
              addEchoMessage(AgentName.RPGNexusAgent, "Story Compilation Complete. Downloading...", "text-emerald-300");

              if (onArtifactCreated) {
                  onArtifactCreated({
                      id: `cinema-${Date.now()}`,
                      name: "Quest Cinema Log",
                      type: ArtifactType.VisualMemory,
                      rarity: ArtifactRarity.Rare,
                      description: "A compiled video log of your recent journey.",
                      imageUrl: gameState.currentSceneImageUrl || "", // Thumbnail
                      timestamp: Date.now()
                  });
              }
          }
      } catch (e) {
          console.error(e);
          addEchoMessage(AgentName.System, "Story compilation failed.", "text-rose-400");
      } finally {
          setIsCompilingStory(false);
          setCompilationProgress(0);
      }
  };

  const handleDownloadStory = () => {
      const storyText = gameState.narrativeHistory.map(n => `[${new Date(n.timestamp).toLocaleTimeString()}] ${n.type.toUpperCase()}: ${n.text}`).join('\n\n');
      const blob = new Blob([storyText], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `Nexus_Log_${Date.now()}.txt`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      addEchoMessage(AgentName.RPGNexusAgent, "Narrative log exported.", "text-cyan-300");
  };

  const handleReimagineScene = async () => {
      if (isProcessingTurn || !gameState.currentSceneDescription) return;
      setIsProcessingTurn(true);
      addEchoMessage(AgentName.RPGNexusAgent, "Re-imagining reality matrix...", "text-purple-300");

      try {
          const imagePrompt = `Sci-fi fantasy concept art, ${gameState.currentLocation}, ${gameState.currentSceneDescription}, cinematic lighting, atmospheric, ${activeProfile?.visualFilter || 'cyberpunk'} style, ${currentEntropy > 0.6 ? 'glitch, chaos, fractal' : 'clean, ethereal, serene'}.`;

          const url = await generateImage(imagePrompt);
          if (url) {
             setGameState(prev => ({ 
                  ...prev, 
                  currentSceneImageUrl: url,
                  sceneHistory: [...(prev.sceneHistory || []), {
                      imageUrl: url,
                      location: prev.currentLocation,
                      description: prev.currentSceneDescription || "Reimagined scene",
                      timestamp: Date.now()
                  }]
              }));
              setCurrentSceneVideoUrl(null); // Clear video if scene changes
              addEchoMessage(AgentName.RPGNexusAgent, "Visuals re-synthesized.", "text-emerald-300");
          }
      } catch (e) {
          addEchoMessage(AgentName.System, "Reimagine failed.", "text-rose-400");
      } finally {
          setIsProcessingTurn(false);
      }
  };


  // -- Renders --

  const renderInitialization = () => (
    <div className="flex flex-col items-center justify-center h-full p-6 animate-fade-in-up bg-slate-900/50">
      <div className="text-5xl text-indigo-500 mb-6 animate-pulse"><i className="ri-radar-line"></i></div>
      <h3 className="text-2xl font-cinzel text-indigo-300 mb-3">Campaign Initialization</h3>
      <p className="text-base text-slate-400 mb-8 text-center max-w-lg leading-relaxed">
        The Nexus Engine requires an insertion vector. Scan the local entropy field to materialize potential timelines.
      </p>

      {scanResults ? (
         <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl">
            {Object.entries(scanResults).map(([name, dataRaw]) => {
                const data = dataRaw as RPGScanResultLocation;
                return (
                    <button 
                        key={name}
                        onClick={() => handleTravel(name, data)}
                        className="flex flex-col p-6 bg-slate-800/80 border-2 border-slate-600 rounded-xl hover:bg-slate-700 hover:border-cyan-500 hover:shadow-2xl hover:shadow-cyan-500/20 transition-all group text-left transform hover:-translate-y-1"
                    >
                        <div className="flex items-center justify-between mb-4 w-full">
                            <i className={`${data.icon || 'ri-map-pin-line'} text-3xl ${data.color || 'text-slate-200'}`}></i>
                            <span className="text-xs uppercase font-bold tracking-wider bg-slate-900 px-3 py-1 rounded text-slate-400 group-hover:text-white transition-colors">{data.risk} Risk</span>
                        </div>
                        <h4 className="font-cinzel font-bold text-xl text-slate-200 group-hover:text-cyan-300 mb-2">{name}</h4>
                        <p className="text-sm text-slate-400 font-cormorant leading-relaxed">{data.description}</p>
                    </button>
                );
            })}
         </div>
      ) : (
        <Button onClick={handleScanSector} disabled={isScanning} className="px-10 py-4 text-base tracking-widest bg-indigo-600 hover:bg-indigo-500 shadow-xl shadow-indigo-500/20 font-bold">
            {isScanning ? <><i className="ri-loader-4-line animate-spin mr-3"></i>SCANNING SECTOR...</> : <><i className="ri-search-eye-line mr-3"></i>SCAN FOR ANOMALIES</>}
        </Button>
      )}
    </div>
  );

  const renderGameInterface = () => (
    <div className="flex flex-col h-full bg-slate-900/80">
        {/* Top Info Bar */}
        <div className="flex justify-between items-center bg-slate-950 p-3 border-b border-indigo-500/30 text-sm shadow-md z-10 shrink-0">
            <div className="flex items-center gap-6">
                <span className="text-indigo-300 font-bold text-lg font-cinzel"><i className="ri-map-pin-user-fill mr-2"></i>{gameState.currentLocation}</span>
                <span className="text-slate-400 font-mono text-xs">Turn: {gameState.narrativeHistory.filter(n => n.type==='action').length}</span>
            </div>
            <div className="flex items-center gap-6">
                <div className="flex items-center gap-2" title="Integrity">
                    <i className="ri-heart-pulse-fill text-rose-500"></i>
                    <div className="w-24 h-2 bg-slate-800 rounded-full overflow-hidden">
                        <div className={`h-full ${gameState.vitals!.integrity < 30 ? 'bg-rose-500 animate-pulse' : 'bg-emerald-500'}`} style={{width: `${gameState.vitals?.integrity}%`}}></div>
                    </div>
                    <span className="font-mono text-slate-300">{gameState.vitals?.integrity}%</span>
                </div>
                <div className="flex items-center gap-2" title="Sanity">
                    <i className="ri-brain-fill text-purple-400"></i>
                    <div className="w-24 h-2 bg-slate-800 rounded-full overflow-hidden">
                         <div className="h-full bg-purple-500" style={{width: `${gameState.vitals?.sanity}%`}}></div>
                    </div>
                    <span className="font-mono text-slate-300">{gameState.vitals?.sanity}%</span>
                </div>
            </div>
        </div>

        <div className="flex-grow flex flex-col lg:flex-row min-h-0 overflow-hidden">
            {/* Left: Visual & Controls */}
            <div className="w-full lg:w-1/2 p-5 flex flex-col gap-5 border-r border-slate-700/50 overflow-y-auto custom-scrollbar bg-slate-900/40">

                {/* Scene Display */}
                <div className="w-full bg-black rounded-xl border-2 border-slate-600 overflow-hidden relative shadow-2xl shrink-0 group" style={{ minHeight: '320px' }}>
                    {currentSceneVideoUrl ? (
                         <video src={currentSceneVideoUrl} autoPlay loop muted className="w-full h-full object-cover" />
                    ) : gameState.currentSceneImageUrl ? (
                        <img src={gameState.currentSceneImageUrl} alt="Scene" className="w-full h-full object-cover animate-fade-in-up" />
                    ) : (
                        <div className="w-full h-full flex flex-col items-center justify-center text-slate-600 bg-slate-900">
                            <i className="ri-image-line text-5xl mb-3 opacity-50"></i>
                            <span className="text-sm font-mono opacity-70 animate-pulse">Visualizing Neural Link...</span>
                        </div>
                    )}

                    {/* Scene Overlay Info */}
                    <div className="absolute bottom-0 inset-x-0 bg-gradient-to-t from-black via-black/80 to-transparent p-4 pt-12 pointer-events-none">
                        <p className="text-sm md:text-base text-slate-100 font-cormorant italic leading-relaxed drop-shadow-md">
                            {gameState.currentSceneDescription}
                        </p>
                    </div>

                    {/* Scene Controls */}
                    <div className="absolute top-2 right-2 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button
                            onClick={handleReimagineScene}
                            disabled={isProcessingTurn}
                            className="bg-black/50 hover:bg-purple-600/80 text-white p-2 rounded-full backdrop-blur-md transition-all border border-white/20"
                            title="Reimagine Scene (Regenerate Image)"
                        >
                            <i className="ri-refresh-line"></i>
                        </button>
                        <button 
                            onClick={handleGenerateSceneVideo}
                            disabled={isAnimatingScene || !!currentSceneVideoUrl}
                            className="bg-black/50 hover:bg-fuchsia-600/80 text-white p-2 rounded-full backdrop-blur-md transition-all border border-white/20"
                            title="Animate Scene (Video)"
                        >
                            {isAnimatingScene ? <i className="ri-loader-4-line animate-spin"></i> : <i className="ri-movie-line"></i>}
                        </button>
                    </div>
                </div>

                {/* Control Deck */}
                <div className="space-y-4">
                     {/* Custom Action Input */}
                    <div className="flex gap-2">
                        <input 
                            type="text" 
                            value={customActionInput}
                            onChange={(e) => setCustomActionInput(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleAction(customActionInput)}
                            placeholder="Attempt a custom action..."
                            className="flex-grow bg-slate-800 border border-slate-600 rounded-lg px-4 py-2 text-sm text-slate-100 focus:outline-none focus:border-indigo-500 transition-colors"
                            disabled={isProcessingTurn}
                        />
                        <button 
                            onClick={() => handleAction(customActionInput)}
                            disabled={isProcessingTurn || !customActionInput.trim()}
                            className="bg-indigo-600 hover:bg-indigo-500 text-white px-4 rounded-lg transition-colors disabled:opacity-50"
                        >
                            <i className="ri-send-plane-fill"></i>
                        </button>
                    </div>

                    {/* Preset Actions */}
                    <div className="grid gap-3">
                        {gameState.availableActions?.map((action, idx) => {
                            const riskInfo = getRiskLabel(action.risk);
                            const riskBorderClass = getRiskColor(action.risk);
                            return (
                                <button
                                    key={idx}
                                    onClick={() => handleAction(action.label, action.risk)}
                                    disabled={isProcessingTurn}
                                    className={`w-full text-left p-4 rounded-lg bg-slate-800 border-l-4 ${riskBorderClass} shadow-md transition-all group disabled:opacity-50 disabled:cursor-not-allowed hover:translate-x-1`}
                                >
                                    <div className="flex justify-between items-center mb-1">
                                        <span className="text-base font-bold text-slate-100 group-hover:text-white">{action.label}</span>
                                        <span className={`text-[10px] font-bold uppercase tracking-wider ${riskInfo.color}`}>
                                            {riskInfo.text}
                                        </span>
                                    </div>
                                    <div className="text-xs text-slate-500 uppercase tracking-wide flex items-center">
                                         <i className="ri-arrow-right-s-line mr-1 opacity-0 group-hover:opacity-100 transition-opacity"></i>
                                         {action.type}
                                    </div>
                                </button>
                            );
                        })}
                    </div>
                </div>
            </div>

            {/* Right: Narrative & Meta Controls */}
            <div className="w-full lg:w-1/2 flex flex-col min-h-0 bg-slate-950 border-t lg:border-t-0 lg:border-l border-slate-800">
                {/* Narrative Log */}
                <div className="flex-grow overflow-y-auto custom-scrollbar p-6 space-y-4 font-cormorant text-base md:text-lg leading-relaxed text-slate-300">
                    {gameState.narrativeHistory.length === 0 && <div className="text-slate-600 italic text-center mt-10">System Log Initialized...</div>}
                    {gameState.narrativeHistory.map((entry, i) => (
                        <div key={i} className={`p-4 rounded-lg border-l-4 shadow-sm animate-fade-in-up ${entry.type === 'action' ? 'border-indigo-500 bg-indigo-900/10 text-indigo-100' : 'border-slate-700 bg-slate-900/40 text-slate-300'}`}>
                            {entry.type === 'action' && <i className="ri-user-voice-fill mr-2 text-indigo-400"></i>}
                            {entry.text}
                        </div>
                    ))}
                    {isProcessingTurn && (
                        <div className="flex items-center gap-3 text-indigo-400 p-4 animate-pulse bg-indigo-900/10 rounded-lg border border-indigo-500/30">
                            <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce"></div>
                            <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce delay-75"></div>
                            <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce delay-150"></div>
                            <span className="text-sm font-mono">Calculating probabilistic outcome...</span>
                        </div>
                    )}
                    <div ref={chatEndRef} />
                </div>

                {/* Story Controls Footer */}
                <div className="p-4 bg-slate-900 border-t border-slate-800 shrink-0 flex gap-2 overflow-x-auto">
                    <Button 
                        onClick={handleCompileStoryVideo} 
                        disabled={isCompilingStory || !gameState.sceneHistory?.length}
                        className="text-xs bg-amber-700 hover:bg-amber-600 flex items-center whitespace-nowrap"
                    >
                         {isCompilingStory ? `Compiling (${compilationProgress}%)...` : <><i className="ri-movie-2-line mr-2"></i>Compile Story Video</>}
                    </Button>
                    <Button 
                        onClick={handleDownloadStory} 
                        className="text-xs bg-cyan-700 hover:bg-cyan-600 flex items-center whitespace-nowrap"
                    >
                        <i className="ri-file-text-line mr-2"></i>Download Log
                    </Button>
                    <Button 
                        onClick={() => handleScanSector()} 
                        className="text-xs bg-indigo-700 hover:bg-indigo-600 flex items-center whitespace-nowrap ml-auto"
                    >
                        <i className="ri-radar-line mr-2"></i>Rescan Sector
                    </Button>
                </div>
            </div>
        </div>
    </div>
  );

  return (
    <div className="rpg-nexus-panel bg-slate-950 backdrop-blur-xl border border-indigo-600/50 rounded-xl shadow-2xl flex flex-col overflow-hidden transition-all duration-500 font-sans" style={{ width: width || '100%', height: height || '600px' }}>
      {/* Universal Header */}
      <div className="p-4 border-b border-indigo-800/50 bg-slate-900 flex justify-between items-center shrink-0 shadow-md z-20">
        <h3 className="text-xl font-cinzel font-bold text-indigo-300 flex items-center">
            <span className="bg-indigo-900/30 p-1.5 rounded-lg mr-3 border border-indigo-500/30"><i className="ri-gamepad-line text-indigo-400"></i></span>
            Nexus Engine
        </h3>
        {scanResults && (
             <button onClick={() => setScanResults(null)} className="text-xs font-bold text-slate-400 hover:text-white bg-slate-800 hover:bg-slate-700 px-3 py-1.5 rounded-lg transition-colors border border-slate-700">
                 <i className="ri-arrow-go-back-line mr-1"></i>Back to Game
             </button>
        )}
      </div>

      {/* Content Switcher */}
      <div className="flex-grow overflow-hidden relative">
          {(!scanResults && gameState.currentLocation === 'The Void Edge' && gameState.narrativeHistory.length <= 1) 
            ? renderInitialization() 
            : (scanResults ? renderInitialization() : renderGameInterface())
          }
      </div>
    </div>
  );
};

export default RPGNexusPanel;

import React, { useState, useEffect, useRef } from 'react';
import type { RPGNexusPanelProps, RPGGameState, RPGGameLocation, RPGDynamicAction, RPGSceneData } from '../../types';
import { AgentName, ArtifactType, ArtifactRarity } from '../../types';
import { Button } from '../ui/Button';
import { useGemini } from '../../context/GeminiIntegrationContext';
import { globalSoundEngine } from '../../lib/SoundEngine';
import { QuestCinemaEngine } from '../../lib/video/QuestCinemaEngine';

// --- Helper: Robust JSON Parsing ---
const cleanAndParseJSON = <T,>(text: string | null): T | null => {
  if (!text) return null;
  try {
    let cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    let data = JSON.parse(cleanText);
    const keys = Object.keys(data);
    if (keys.length === 1) {
      const rootKey = keys[0];
      if (['locations', 'rpg_locations', 'points_of_interest', 'data', 'result', 'outcome'].includes(rootKey.toLowerCase()) || 
          (typeof data[rootKey] === 'object' && !Array.isArray(data[rootKey]) && !data[rootKey].description && !data[rootKey].resultText)) {
          data = data[rootKey];
      }
    }
    return data as T;
  } catch (e) {
    console.error("RPGNexus: JSON Parsing Failed", e);
    return null;
  }
};

interface RPGScanResultLocation {
  description: string;
  color?: string;
  risk?: string;
  icon?: string;
}

const FALLBACK_LOCATIONS: Record<string, RPGScanResultLocation> = {
  "The Void Edge": { description: "A precipice where reality dissolves into static.", color: "text-slate-400", risk: "Extreme", icon: "ri-mist-line" },
  "Crystal Spire": { description: "A tower of singing glass reaching into the Aethel.", color: "text-cyan-300", risk: "Low", icon: "ri-building-2-line" },
  "Axiom Forge": { description: "Industrial complex where truths are hammered into shape.", color: "text-amber-400", risk: "Medium", icon: "ri-hammer-line" }
};

const DEFAULT_ACTIONS: RPGDynamicAction[] = [
    { id: 'def_explore', label: 'Survey the Area', type: 'explore', risk: 0.1, isDynamic: false },
    { id: 'def_scan', label: 'Scan for Anomalies', type: 'ritual', risk: 0.2, isDynamic: false },
    { id: 'def_rest', label: 'Recalibrate Systems', type: 'talk', risk: 0, isDynamic: false }
];

const RPGNexusPanel: React.FC<RPGNexusPanelProps> = ({
  width,
  height,
  addEchoMessage,
  activeProfile,
  onUpdateProfile,
  currentEntropy,
  onArtifactCreated,
  savedState,
  onSaveState,
  onUpdateSystemMetrics
}) => {
  const { invokeGemini, generateImage, generateVideo, generateSpeech, isGenerating } = useGemini();
  const chatEndRef = useRef<HTMLDivElement>(null);

  // -- State --
  const [gameState, setGameState] = useState<RPGGameState>(savedState || {
    currentLocation: 'The Void Edge',
    narrativeHistory: [{ text: "System Initialized. Awaiting Insertion Coordinates...", type: 'system', timestamp: Date.now() }],
    activeQuests: [],
    lastActionTimestamp: Date.now(),
    vitals: { integrity: 100, sanity: 100 },
    availableActions: DEFAULT_ACTIONS,
    achievements: [],
    combatState: { isActive: false, enemyName: '', enemyHp: 0, enemyMaxHp: 0, turn: 0, logs: [] },
    knownLocations: [],
    currentSceneDescription: "The initialization void. Static fills the air.",
    currentSceneImageUrl: null,
    sceneHistory: [] // New: Track scenes for video compilation
  });

  const [scanResults, setScanResults] = useState<Record<string, RPGScanResultLocation> | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [isProcessingTurn, setIsProcessingTurn] = useState(false);
  const [customActionInput, setCustomActionInput] = useState("");

  // -- Video & Cinema State --
  const [isAnimatingScene, setIsAnimatingScene] = useState(false);
  const [currentSceneVideoUrl, setCurrentSceneVideoUrl] = useState<string | null>(null);
  const [isCompilingStory, setIsCompilingStory] = useState(false);
  const [compilationProgress, setCompilationProgress] = useState(0);

  // -- Refs --
  const cinemaEngineRef = useRef<QuestCinemaEngine | null>(null);

  useEffect(() => {
    return () => {
        if (cinemaEngineRef.current) cinemaEngineRef.current.dispose();
    }
  }, []);

  // -- Persistence --
  useEffect(() => {
    if (onSaveState) onSaveState(gameState);
  }, [gameState, onSaveState]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [gameState.narrativeHistory]);

  const getRiskColor = (risk: number) => {
      if (risk >= 0.7) return 'border-rose-500 hover:bg-rose-900/30 text-rose-200';
      if (risk >= 0.4) return 'border-amber-500 hover:bg-amber-900/30 text-amber-200';
      return 'border-emerald-500 hover:bg-emerald-900/30 text-emerald-200';
  };

  // --- CORE ENGINE ---

  const handleScanSector = async () => {
    if (isScanning || isGenerating) return;
    setIsScanning(true);
    globalSoundEngine.playSFX('click');
    addEchoMessage(AgentName.RPGNexusAgent, "Scanning sector for stability variances...", "text-indigo-300");

    const prompt = `Generate 3 unique, evocative RPG locations for a sci-fi/fantasy setting with entropy level ${currentEntropy.toFixed(2)}.
    Output strictly as JSON. Keys are location names.
    Values must be objects with:
    - "description": string (1 sentence)
    - "color": string (Tailwind text class, e.g. "text-red-400")
    - "risk": string ("Low", "Medium", "High", "Extreme")
    - "icon": string (RemixIcon class, e.g. "ri-skull-line")`;

    try {
      const response = await invokeGemini(prompt, "You are a JSON generator. Do not include markdown formatting.");
      const locations = cleanAndParseJSON<Record<string, RPGScanResultLocation>>(response);
      setScanResults(locations || FALLBACK_LOCATIONS);
    } catch (err) {
      setScanResults(FALLBACK_LOCATIONS);
    } finally {
      setIsScanning(false);
    }
  };

  const handleTravel = async (locationName: string, locationData: RPGScanResultLocation) => {
    setScanResults(null); 
    setIsProcessingTurn(true);
    setCurrentSceneVideoUrl(null); // Reset video on travel
    addEchoMessage(AgentName.RPGNexusAgent, `Vectoring to ${locationName}...`, "text-cyan-300");
    globalSoundEngine.playSFX('pulse');

    setGameState(prev => ({
      ...prev,
      currentLocation: locationName as RPGGameLocation,
      narrativeHistory: [...prev.narrativeHistory, { text: `Arrived at ${locationName}.`, type: 'action', timestamp: Date.now() }]
    }));

    try {
      const textPrompt = `You are the Game Master. The player has just arrived at "${locationName}" (${locationData.description}).
      Current Entropy: ${currentEntropy}.
      1. Write a vivid, 2-sentence sensory description of the scene.
      2. Provide 3 distinct actions the player can take (Explore, Talk, Analyze, Ritual, etc.).
      3. Create a short quest title related to this location.

      Return JSON:
      {
        "description": "...",
        "actions": [ { "id": "act_1", "label": "...", "type": "explore", "risk": 0.2 }, ... ],
        "quest": { "title": "...", "description": "...", "rewards": { "xp": 100, "flux": 50 } }
      }`;

      const textResponseRaw = await invokeGemini(textPrompt, "Return valid JSON only.");
      const textData = cleanAndParseJSON<any>(textResponseRaw);

      if (textData) {
        // Image Gen
        const imagePrompt = `Sci-fi fantasy concept art, ${locationName}, ${textData.description}, cinematic lighting, atmospheric, ${currentEntropy > 0.6 ? 'glitch, chaos, fractal' : 'clean, ethereal, serene'}.`;
        generateImage(imagePrompt).then(url => {
          if (url) {
            setGameState(prev => {
                const newHistoryEntry: RPGSceneData = {
                    imageUrl: url,
                    location: locationName as RPGGameLocation,
                    description: textData.description,
                    timestamp: Date.now()
                };
                return { 
                    ...prev, 
                    currentSceneImageUrl: url,
                    sceneHistory: [...(prev.sceneHistory || []), newHistoryEntry] 
                };
            });
          }
        });

        setGameState(prev => ({
          ...prev,
          currentSceneDescription: textData.description,
          availableActions: textData.actions || DEFAULT_ACTIONS,
          activeQuests: prev.activeQuests.length < 3 ? [...prev.activeQuests, { ...textData.quest, id: `quest-${Date.now()}`, status: 'active' }] : prev.activeQuests,
          narrativeHistory: [...prev.narrativeHistory, { text: textData.description, type: 'narration', timestamp: Date.now() }]
        }));
      }
    } catch (e) {
      console.error("Travel generation failed", e);
      addEchoMessage(AgentName.System, "Navigational data corrupted. Using fallback protocols.", "text-rose-400");
    } finally {
      setIsProcessingTurn(false);
    }
  };

  const handleAction = async (actionLabel: string, risk: number = 0.5) => {
    if (isProcessingTurn) return;
    setIsProcessingTurn(true);
    setCustomActionInput(""); // Clear input if used
    globalSoundEngine.playSFX('click');

    setGameState(prev => ({
        ...prev,
        narrativeHistory: [...prev.narrativeHistory, { text: `> ${actionLabel}`, type: 'action', timestamp: Date.now() }]
    }));

    const prompt = `Game Master Logic:
    Location: ${gameState.currentLocation}
    Action Taken: "${actionLabel}"
    Entropy: ${currentEntropy}
    Profile: ${activeProfile?.name || "Seeker"} (${activeProfile?.race} ${activeProfile?.class})
    Current Scene: ${gameState.currentSceneDescription}

    Determine the outcome. 
    1. Write a 1-2 sentence narrative result.
    2. Define any stat changes (integrity/sanity/flux).
    3. PROVIDE 3 NEW Available Actions for the player based on the new situation.

    Return JSON:
    {
      "resultText": "...",
      "deltaIntegrity": -5, 
      "deltaSanity": 0,
      "deltaFlux": 10,
      "newActions": [ { "id": "new_1", "label": "...", "type": "explore", "risk": 0.2 }, ... ]
    }`;

    try {
        const response = await invokeGemini(prompt, "Return valid JSON only. Do not wrap in markdown.");
        const outcome = cleanAndParseJSON<any>(response);

        if (outcome) {
            const newIntegrity = Math.max(0, Math.min(100, (gameState.vitals?.integrity || 100) + (outcome.deltaIntegrity || 0)));
            const newSanity = Math.max(0, Math.min(100, (gameState.vitals?.sanity || 100) + (outcome.deltaSanity || 0)));

            setGameState(prev => ({
                ...prev,
                vitals: { integrity: newIntegrity, sanity: newSanity },
                availableActions: (outcome.newActions && outcome.newActions.length > 0) ? outcome.newActions : DEFAULT_ACTIONS,
                narrativeHistory: [...prev.narrativeHistory, { text: outcome.resultText, type: 'narration', timestamp: Date.now() }]
            }));

            if (outcome.deltaFlux && onUpdateProfile && activeProfile) {
                onUpdateProfile({ ...activeProfile, flux: activeProfile.flux + outcome.deltaFlux });
                addEchoMessage(AgentName.RPGNexusAgent, `Flux ${outcome.deltaFlux > 0 ? '+' : ''}${outcome.deltaFlux}`, outcome.deltaFlux > 0 ? 'text-amber-300' : 'text-rose-400');
            }
            if (risk > 0.5) onUpdateSystemMetrics(0.01, -0.01); 
        } else {
             setGameState(prev => ({
                ...prev,
                availableActions: DEFAULT_ACTIONS,
                narrativeHistory: [...prev.narrativeHistory, { text: "The ether churns, obscuring the outcome. (Data corruption)", type: 'system', timestamp: Date.now() }]
            }));
        }
    } catch (e) {
        addEchoMessage(AgentName.System, "Action resolution failed. Systems rebooting...", "text-rose-400");
        setGameState(prev => ({ ...prev, availableActions: DEFAULT_ACTIONS }));
    } finally {
        setIsProcessingTurn(false);
    }
  };

  // --- NEW FEATURES ---

  const handleGenerateSceneVideo = async () => {
      if (isAnimatingScene || !gameState.currentSceneImageUrl) return;
      setIsAnimatingScene(true);
      addEchoMessage(AgentName.RPGNexusAgent, "Animating scene via Veo-3.1...", "text-fuchsia-300");

      try {
          const prompt = `Cinematic subtle motion, atmospheric video of ${gameState.currentSceneDescription}. ${currentEntropy > 0.6 ? 'Glitch art style, disturbing movement.' : 'Serene, flowing motion.'}`;
          const videoUrl = await generateVideo(prompt, gameState.currentSceneImageUrl);
          if (videoUrl) {
              setCurrentSceneVideoUrl(videoUrl);
              addEchoMessage(AgentName.RPGNexusAgent, "Scene animation compiled.", "text-emerald-300");
          } else {
              throw new Error("No video URL returned.");
          }
      } catch (e) {
          console.error(e);
          addEchoMessage(AgentName.System, "Video generation failed.", "text-rose-400");
      } finally {
          setIsAnimatingScene(false);
      }
  };

  const handleCompileStoryVideo = async () => {
      if (isCompilingStory || !gameState.sceneHistory || gameState.sceneHistory.length === 0) {
          addEchoMessage(AgentName.System, "No scene history to compile.", "text-yellow-400");
          return;
      }

      setIsCompilingStory(true);
      setCompilationProgress(0);
      addEchoMessage(AgentName.RPGNexusAgent, "Compiling narrative history into Quest Cinema...", "text-amber-300");

      try {
          if (!cinemaEngineRef.current) {
              cinemaEngineRef.current = new QuestCinemaEngine();
          }

          const slides = gameState.sceneHistory.map(scene => ({
              imageUrl: scene.imageUrl,
              text: scene.description
          }));

          const blob = await cinemaEngineRef.current.compileVideo(
              slides,
              (progress) => setCompilationProgress(Math.round(progress * 100)),
              async (text) => await generateSpeech(text) 
          );

          if (blob) {
              const url = URL.createObjectURL(blob);
              const a = document.createElement('a');
              a.href = url;
              a.download = `Nexus_Story_${Date.now()}.webm`; // Or mp4 based on engine support
              document.body.appendChild(a);
              a.click();
              document.body.removeChild(a);
              addEchoMessage(AgentName.RPGNexusAgent, "Story Compilation Complete. Downloading...", "text-emerald-300");

              if (onArtifactCreated) {
                  onArtifactCreated({
                      id: `cinema-${Date.now()}`,
                      name: "Quest Cinema Log",
                      type: ArtifactType.VisualMemory,
                      rarity: ArtifactRarity.Rare,
                      description: "A compiled video log of your recent journey.",
                      imageUrl: gameState.currentSceneImageUrl || "", // Thumbnail
                      timestamp: Date.now()
                  });
              }
          }
      } catch (e) {
          console.error(e);
          addEchoMessage(AgentName.System, "Story compilation failed.", "text-rose-400");
      } finally {
          setIsCompilingStory(false);
          setCompilationProgress(0);
      }
  };

  const handleDownloadStory = () => {
      const storyText = gameState.narrativeHistory.map(n => `[${new Date(n.timestamp).toLocaleTimeString()}] ${n.type.toUpperCase()}: ${n.text}`).join('\n\n');
      const blob = new Blob([storyText], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `Nexus_Log_${Date.now()}.txt`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      addEchoMessage(AgentName.RPGNexusAgent, "Narrative log exported.", "text-cyan-300");
  };

  const handleReimagineScene = async () => {
      if (isProcessingTurn || !gameState.currentSceneDescription) return;
      setIsProcessingTurn(true);
      addEchoMessage(AgentName.RPGNexusAgent, "Re-imagining reality matrix...", "text-purple-300");

      try {
          const imagePrompt = `Sci-fi fantasy concept art, ${gameState.currentLocation}, ${gameState.currentSceneDescription}, cinematic lighting, atmospheric, ${activeProfile?.visualFilter || 'cyberpunk'} style, ${currentEntropy > 0.6 ? 'glitch, chaos, fractal' : 'clean, ethereal, serene'}.`;

          const url = await generateImage(imagePrompt);
          if (url) {
             setGameState(prev => ({ 
                  ...prev, 
                  currentSceneImageUrl: url,
                  sceneHistory: [...(prev.sceneHistory || []), {
                      imageUrl: url,
                      location: prev.currentLocation,
                      description: prev.currentSceneDescription || "Reimagined scene",
                      timestamp: Date.now()
                  }]
              }));
              setCurrentSceneVideoUrl(null); // Clear video if scene changes
              addEchoMessage(AgentName.RPGNexusAgent, "Visuals re-synthesized.", "text-emerald-300");
          }
      } catch (e) {
          addEchoMessage(AgentName.System, "Reimagine failed.", "text-rose-400");
      } finally {
          setIsProcessingTurn(false);
      }
  };


  // -- Renders --

  const renderInitialization = () => (
    <div className="flex flex-col items-center justify-center h-full p-6 animate-fade-in-up bg-slate-900/50">
      <div className="text-5xl text-indigo-500 mb-6 animate-pulse"><i className="ri-radar-line"></i></div>
      <h3 className="text-2xl font-cinzel text-indigo-300 mb-3">Campaign Initialization</h3>
      <p className="text-base text-slate-400 mb-8 text-center max-w-lg leading-relaxed">
        The Nexus Engine requires an insertion vector. Scan the local entropy field to materialize potential timelines.
      </p>

      {scanResults ? (
         <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl">
            {Object.entries(scanResults).map(([name, dataRaw]) => {
                const data = dataRaw as RPGScanResultLocation;
                return (
                    <button 
                        key={name}
                        onClick={() => handleTravel(name, data)}
                        className="flex flex-col p-6 bg-slate-800/80 border-2 border-slate-600 rounded-xl hover:bg-slate-700 hover:border-cyan-500 hover:shadow-2xl hover:shadow-cyan-500/20 transition-all group text-left transform hover:-translate-y-1"
                    >
                        <div className="flex items-center justify-between mb-4 w-full">
                            <i className={`${data.icon || 'ri-map-pin-line'} text-3xl ${data.color || 'text-slate-200'}`}></i>
                            <span className="text-xs uppercase font-bold tracking-wider bg-slate-900 px-3 py-1 rounded text-slate-400 group-hover:text-white transition-colors">{data.risk} Risk</span>
                        </div>
                        <h4 className="font-cinzel font-bold text-xl text-slate-200 group-hover:text-cyan-300 mb-2">{name}</h4>
                        <p className="text-sm text-slate-400 font-cormorant leading-relaxed">{data.description}</p>
                    </button>
                );
            })}
         </div>
      ) : (
        <Button onClick={handleScanSector} disabled={isScanning} className="px-10 py-4 text-base tracking-widest bg-indigo-600 hover:bg-indigo-500 shadow-xl shadow-indigo-500/20 font-bold">
            {isScanning ? <><i className="ri-loader-4-line animate-spin mr-3"></i>SCANNING SECTOR...</> : <><i className="ri-search-eye-line mr-3"></i>SCAN FOR ANOMALIES</>}
        </Button>
      )}
    </div>
  );

  const renderGameInterface = () => (
    <div className="relative h-full w-full overflow-hidden bg-slate-950 font-sans">
        {/* BACKGROUND LAYER */}
        <div className="absolute inset-0 z-0">
            {currentSceneVideoUrl ? (
                <video src={currentSceneVideoUrl} autoPlay loop muted className="w-full h-full object-cover" />
            ) : gameState.currentSceneImageUrl ? (
                <img src={gameState.currentSceneImageUrl} alt="Scene" className="w-full h-full object-cover transition-opacity duration-1000 ease-in-out" />
            ) : (
                 <div className="w-full h-full bg-slate-900 flex items-center justify-center">
                    <div className="text-slate-700 animate-pulse text-6xl"><i className="ri-image-line"></i></div>
                 </div>
            )}
            {/* VIGNETTE & GRADIENT OVERLAY */}
            <div className="absolute inset-0 bg-gradient-to-b from-slate-950/80 via-transparent to-slate-950/90 pointer-events-none"></div>
            <div className="absolute inset-0 bg-black/20 pointer-events-none"></div> 
        </div>

        {/* CONTENT LAYER */}
        <div className="relative z-10 flex flex-col h-full p-4 pointer-events-none"> {/* content container */}

            {/* TOP BAR: Stats & Location */}
            <div className="flex justify-between items-start pointer-events-auto">
                 <div className="bg-slate-950/60 backdrop-blur-md border border-slate-700/50 rounded-lg p-3 shadow-lg max-w-md">
                    <h3 className="text-indigo-300 font-bold text-lg font-cinzel flex items-center gap-2">
                        <i className="ri-map-pin-user-fill"></i> {gameState.currentLocation}
                    </h3>
                    <div className="flex items-center gap-4 mt-2 text-xs font-mono text-slate-300">
                         <div className="flex items-center gap-1" title="Integrity"><i className="ri-heart-pulse-fill text-rose-500"></i> {gameState.vitals?.integrity}%</div>
                         <div className="flex items-center gap-1" title="Sanity"><i className="ri-brain-fill text-purple-400"></i> {gameState.vitals?.sanity}%</div>
                         <div className="flex items-center gap-1" title="Flux"><i className="ri-copper-coin-line text-amber-400"></i> {activeProfile?.flux || 0}</div>
                    </div>
                 </div>

                 {/* VISUAL CONTROLS (Top Right) */}
                 <div className="flex gap-2">
                    <button 
                        onClick={handleReimagineScene}
                        disabled={isProcessingTurn}
                        className="bg-slate-950/60 hover:bg-purple-900/60 backdrop-blur-md text-white p-2 rounded-lg border border-slate-600/50 transition-all hover:scale-105"
                        title="Reimagine Scene (Regenerate Image)"
                    >
                        <i className={`ri-refresh-line ${isProcessingTurn ? 'animate-spin' : ''}`}></i>
                    </button>
                    <button 
                        onClick={handleGenerateSceneVideo}
                        disabled={isAnimatingScene || !!currentSceneVideoUrl}
                        className="bg-slate-950/60 hover:bg-fuchsia-900/60 backdrop-blur-md text-white p-2 rounded-lg border border-slate-600/50 transition-all hover:scale-105"
                        title="Animate Scene (Veo Video)"
                    >
                        {isAnimatingScene ? <i className="ri-loader-4-line animate-spin"></i> : <i className="ri-movie-line"></i>}
                    </button>
                 </div>
            </div>

            {/* MIDDLE AREA */}
            <div className="flex-grow flex flex-col justify-end lg:flex-row lg:items-end lg:justify-between gap-4 min-h-0 mt-4">

                {/* ACTIONS DECK (Bottom Left) */}
                <div className="w-full lg:w-1/3 pointer-events-auto space-y-2">
                    {/* Custom Input */}
                    <div className="flex gap-2 mb-2 bg-slate-950/70 p-1.5 rounded-lg border border-slate-700/50 backdrop-blur-sm">
                        <input 
                            type="text" 
                            value={customActionInput}
                            onChange={(e) => setCustomActionInput(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleAction(customActionInput)}
                            placeholder="What do you do?"
                            className="flex-grow bg-transparent border-none text-sm text-slate-100 placeholder-slate-500 focus:ring-0"
                            disabled={isProcessingTurn}
                        />
                        <button 
                            onClick={() => handleAction(customActionInput)}
                            disabled={isProcessingTurn || !customActionInput.trim()}
                            className="text-indigo-400 hover:text-indigo-300 px-2"
                        >
                            <i className="ri-send-plane-fill"></i>
                        </button>
                    </div>

                    {/* Action Buttons */}
                    <div className="flex flex-col gap-2 max-h-48 overflow-y-auto custom-scrollbar-thin pr-1">
                        {gameState.availableActions?.map((action, idx) => {
                             // getRiskColor returns border classes primarily. We might want bg classes for glass buttons.
                             // Let's customize button style here for the overlay.
                             let btnBg = "bg-slate-900/60 hover:bg-slate-800/80";
                             let borderColor = "border-slate-600";
                             if(action.risk > 0.6) { borderColor = "border-rose-500/50"; btnBg = "bg-rose-950/40 hover:bg-rose-900/60"; }
                             else if(action.risk > 0.3) { borderColor = "border-amber-500/50"; btnBg = "bg-amber-950/40 hover:bg-amber-900/60"; }
                             else { borderColor = "border-emerald-500/50"; btnBg = "bg-emerald-950/40 hover:bg-emerald-900/60"; }

                             return (
                                <button
                                    key={idx}
                                    onClick={() => handleAction(action.label, action.risk)}
                                    disabled={isProcessingTurn}
                                    className={`w-full text-left p-3 rounded-lg border ${borderColor} ${btnBg} backdrop-blur-sm transition-all group flex justify-between items-center`}
                                >
                                    <span className="text-sm font-semibold text-slate-100 group-hover:text-white shadow-black drop-shadow-sm">{action.label}</span>
                                    <span className="text-[10px] uppercase opacity-70 font-mono">{action.type}</span>
                                </button>
                            );
                        })}
                    </div>
                </div>

                {/* NARRATIVE LOG (Bottom Right/Center) */}
                <div className="w-full lg:w-1/2 pointer-events-auto flex flex-col gap-2 max-h-[40vh]">
                     <div className="bg-slate-950/70 backdrop-blur-md border border-slate-700/50 rounded-lg p-4 overflow-y-auto custom-scrollbar flex-grow shadow-2xl">
                        {gameState.narrativeHistory.slice(-10).map((entry, i) => ( // Show last 10 entries contextually
                            <div key={i} className={`mb-3 last:mb-0 text-sm leading-relaxed ${entry.type === 'action' ? 'text-indigo-300 font-bold' : 'text-slate-300 font-cormorant'}`}>
                                {entry.type === 'action' && <span className="mr-2 opacity-50">></span>}
                                {entry.text}
                            </div>
                        ))}
                        <div ref={chatEndRef} />
                        {isProcessingTurn && (
                            <div className="text-xs text-indigo-400 animate-pulse mt-2 flex items-center gap-2">
                                <i className="ri-quill-pen-line"></i> The Game Master weaves the fate...
                            </div>
                        )}
                     </div>

                     {/* Meta Controls */}
                     <div className="flex gap-2 justify-end">
                        <Button onClick={handleCompileStoryVideo} disabled={isCompilingStory || !gameState.sceneHistory?.length} className="text-[10px] py-1 bg-amber-700/80 hover:bg-amber-600/80 backdrop-blur-sm">
                            {isCompilingStory ? `Compiling ${compilationProgress}%` : <><i className="ri-movie-2-line mr-1"></i> Story Movie</>}
                        </Button>
                        <Button onClick={handleDownloadStory} className="text-[10px] py-1 bg-cyan-700/80 hover:bg-cyan-600/80 backdrop-blur-sm">
                            <i className="ri-file-text-line mr-1"></i> Log
                        </Button>
                        <Button onClick={() => handleScanSector()} className="text-[10px] py-1 bg-indigo-700/80 hover:bg-indigo-600/80 backdrop-blur-sm">
                             <i className="ri-radar-line mr-1"></i> Rescan
                        </Button>
                     </div>
                </div>
            </div>
        </div>
    </div>
  );

  return (
    <div className="rpg-nexus-panel bg-slate-950 backdrop-blur-xl border border-indigo-600/50 rounded-xl shadow-2xl flex flex-col overflow-hidden transition-all duration-500 font-sans" style={{ width: width || '100%', height: height || '600px' }}>
      {/* Universal Header */}
      <div className="p-4 border-b border-indigo-800/50 bg-slate-900 flex justify-between items-center shrink-0 shadow-md z-20">
        <h3 className="text-xl font-cinzel font-bold text-indigo-300 flex items-center">
            <span className="bg-indigo-900/30 p-1.5 rounded-lg mr-3 border border-indigo-500/30"><i className="ri-gamepad-line text-indigo-400"></i></span>
            Nexus Engine
        </h3>
        {scanResults && (
             <button onClick={() => setScanResults(null)} className="text-xs font-bold text-slate-400 hover:text-white bg-slate-800 hover:bg-slate-700 px-3 py-1.5 rounded-lg transition-colors border border-slate-700">
                 <i className="ri-arrow-go-back-line mr-1"></i>Back to Game
             </button>
        )}
      </div>

      {/* Content Switcher */}
      <div className="flex-grow overflow-hidden relative">
          {(!scanResults && gameState.currentLocation === 'The Void Edge' && gameState.narrativeHistory.length <= 1) 
            ? renderInitialization() 
            : (scanResults ? renderInitialization() : renderGameInterface())
          }
      </div>
    </div>
  );
};

export default RPGNexusPanel;

import React, { useState, useEffect, useRef } from 'react';
import type { RPGNexusPanelProps, RPGGameState, RPGGameLocation, RPGDynamicAction, RPGSceneData } from '../../types';
import { AgentName, ArtifactType, ArtifactRarity } from '../../types';
import { Button } from '../ui/Button';
import { useGemini } from '../../context/GeminiIntegrationContext';
import { globalSoundEngine } from '../../lib/SoundEngine';
import { QuestCinemaEngine } from '../../lib/video/QuestCinemaEngine';

// --- Helper: Robust JSON Parsing ---
const cleanAndParseJSON = <T,>(text: string | null): T | null => {
  if (!text) return null;
  try {
    let cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    let data = JSON.parse(cleanText);
    const keys = Object.keys(data);
    if (keys.length === 1) {
      const rootKey = keys[0];
      if (['locations', 'rpg_locations', 'points_of_interest', 'data', 'result', 'outcome'].includes(rootKey.toLowerCase()) || 
          (typeof data[rootKey] === 'object' && !Array.isArray(data[rootKey]) && !data[rootKey].description && !data[rootKey].resultText)) {
          data = data[rootKey];
      }
    }
    return data as T;
  } catch (e) {
    console.error("RPGNexus: JSON Parsing Failed", e);
    return null;
  }
};

interface RPGScanResultLocation {
  description: string;
  color?: string;
  risk?: string;
  icon?: string;
}

const FALLBACK_LOCATIONS: Record<string, RPGScanResultLocation> = {
  "The Void Edge": { description: "A precipice where reality dissolves into static.", color: "text-slate-400", risk: "Extreme", icon: "ri-mist-line" },
  "Crystal Spire": { description: "A tower of singing glass reaching into the Aethel.", color: "text-cyan-300", risk: "Low", icon: "ri-building-2-line" },
  "Axiom Forge": { description: "Industrial complex where truths are hammered into shape.", color: "text-amber-400", risk: "Medium", icon: "ri-hammer-line" }
};

const DEFAULT_ACTIONS: RPGDynamicAction[] = [
    { id: 'def_explore', label: 'Survey the Area', type: 'explore', risk: 0.1, isDynamic: false },
    { id: 'def_scan', label: 'Scan for Anomalies', type: 'ritual', risk: 0.2, isDynamic: false },
    { id: 'def_rest', label: 'Recalibrate Systems', type: 'talk', risk: 0, isDynamic: false }
];

const RPGNexusPanel: React.FC<RPGNexusPanelProps> = ({
  width,
  height,
  addEchoMessage,
  activeProfile,
  onUpdateProfile,
  currentEntropy,
  onArtifactCreated,
  savedState,
  onSaveState,
  onUpdateSystemMetrics
}) => {
  const { invokeGemini, generateImage, generateVideo, generateSpeech, isGenerating } = useGemini();
  const chatEndRef = useRef<HTMLDivElement>(null);

  // -- State --
  const [gameState, setGameState] = useState<RPGGameState>(savedState || {
    currentLocation: 'The Void Edge',
    narrativeHistory: [{ text: "System Initialized. Awaiting Insertion Coordinates...", type: 'system', timestamp: Date.now() }],
    activeQuests: [],
    lastActionTimestamp: Date.now(),
    vitals: { integrity: 100, sanity: 100 },
    availableActions: DEFAULT_ACTIONS,
    achievements: [],
    combatState: { isActive: false, enemyName: '', enemyHp: 0, enemyMaxHp: 0, turn: 0, logs: [] },
    knownLocations: [],
    currentSceneDescription: "The initialization void. Static fills the air.",
    currentSceneImageUrl: null,
    sceneHistory: [] // New: Track scenes for video compilation
  });

  const [scanResults, setScanResults] = useState<Record<string, RPGScanResultLocation> | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [isProcessingTurn, setIsProcessingTurn] = useState(false);
  const [customActionInput, setCustomActionInput] = useState("");

  // -- Video & Cinema State --
  const [isAnimatingScene, setIsAnimatingScene] = useState(false);
  const [currentSceneVideoUrl, setCurrentSceneVideoUrl] = useState<string | null>(null);
  const [isCompilingStory, setIsCompilingStory] = useState(false);
  const [compilationProgress, setCompilationProgress] = useState(0);

  // -- Refs --
  const cinemaEngineRef = useRef<QuestCinemaEngine | null>(null);

  useEffect(() => {
    return () => {
        if (cinemaEngineRef.current) cinemaEngineRef.current.dispose();
    }
  }, []);

  // -- Persistence --
  useEffect(() => {
    if (onSaveState) onSaveState(gameState);
  }, [gameState, onSaveState]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [gameState.narrativeHistory]);

  const getRiskColor = (risk: number) => {
      if (risk >= 0.7) return 'border-rose-500 hover:bg-rose-900/30 text-rose-200';
      if (risk >= 0.4) return 'border-amber-500 hover:bg-amber-900/30 text-amber-200';
      return 'border-emerald-500 hover:bg-emerald-900/30 text-emerald-200';
  };

  const getRiskLabel = (risk: number) => {
      if (risk >= 0.7) return { text: 'HIGH RISK', color: 'text-rose-400' };
      if (risk >= 0.4) return { text: 'MED RISK', color: 'text-amber-400' };
      return { text: 'LOW RISK', color: 'text-emerald-400' };
  };

  // --- CORE ENGINE ---

  const handleScanSector = async () => {
    if (isScanning || isGenerating) return;
    setIsScanning(true);
    globalSoundEngine.playSFX('click');
    addEchoMessage(AgentName.RPGNexusAgent, "Scanning sector for stability variances...", "text-indigo-300");

    const prompt = `Generate 3 unique, evocative RPG locations for a sci-fi/fantasy setting with entropy level ${currentEntropy.toFixed(2)}.
    Output strictly as JSON. Keys are location names.
    Values must be objects with:
    - "description": string (1 sentence)
    - "color": string (Tailwind text class, e.g. "text-red-400")
    - "risk": string ("Low", "Medium", "High", "Extreme")
    - "icon": string (RemixIcon class, e.g. "ri-skull-line")`;

    try {
      const response = await invokeGemini(prompt, "You are a JSON generator. Do not include markdown formatting.");
      const locations = cleanAndParseJSON<Record<string, RPGScanResultLocation>>(response);
      setScanResults(locations || FALLBACK_LOCATIONS);
    } catch (err) {
      setScanResults(FALLBACK_LOCATIONS);
    } finally {
      setIsScanning(false);
    }
  };

  const handleTravel = async (locationName: string, locationData: RPGScanResultLocation) => {
    setScanResults(null); 
    setIsProcessingTurn(true);
    setCurrentSceneVideoUrl(null); // Reset video on travel
    addEchoMessage(AgentName.RPGNexusAgent, `Vectoring to ${locationName}...`, "text-cyan-300");
    globalSoundEngine.playSFX('pulse');

    setGameState(prev => ({
      ...prev,
      currentLocation: locationName as RPGGameLocation,
      narrativeHistory: [...prev.narrativeHistory, { text: `Arrived at ${locationName}.`, type: 'action', timestamp: Date.now() }]
    }));

    try {
      const textPrompt = `You are the Game Master. The player has just arrived at "${locationName}" (${locationData.description}).
      Current Entropy: ${currentEntropy}.
      1. Write a vivid, 2-sentence sensory description of the scene.
      2. Provide 3 distinct actions the player can take (Explore, Talk, Analyze, Ritual, etc.).
      3. Create a short quest title related to this location.

      Return JSON:
      {
        "description": "...",
        "actions": [ { "id": "act_1", "label": "...", "type": "explore", "risk": 0.2 }, ... ],
        "quest": { "title": "...", "description": "...", "rewards": { "xp": 100, "flux": 50 } }
      }`;

      const textResponseRaw = await invokeGemini(textPrompt, "Return valid JSON only.");
      const textData = cleanAndParseJSON<any>(textResponseRaw);

      if (textData) {
        // Image Gen
        const imagePrompt = `Sci-fi fantasy concept art, ${locationName}, ${textData.description}, cinematic lighting, atmospheric, ${currentEntropy > 0.6 ? 'glitch, chaos, fractal' : 'clean, ethereal, serene'}.`;
        generateImage(imagePrompt).then(url => {
          if (url) {
            setGameState(prev => {
                const newHistoryEntry: RPGSceneData = {
                    imageUrl: url,
                    location: locationName as RPGGameLocation,
                    description: textData.description,
                    timestamp: Date.now()
                };
                return { 
                    ...prev, 
                    currentSceneImageUrl: url,
                    sceneHistory: [...(prev.sceneHistory || []), newHistoryEntry] 
                };
            });
          }
        });

        setGameState(prev => ({
          ...prev,
          currentSceneDescription: textData.description,
          availableActions: textData.actions || DEFAULT_ACTIONS,
          activeQuests: prev.activeQuests.length < 3 ? [...prev.activeQuests, { ...textData.quest, id: `quest-${Date.now()}`, status: 'active' }] : prev.activeQuests,
          narrativeHistory: [...prev.narrativeHistory, { text: textData.description, type: 'narration', timestamp: Date.now() }]
        }));
      }
    } catch (e) {
      console.error("Travel generation failed", e);
      addEchoMessage(AgentName.System, "Navigational data corrupted. Using fallback protocols.", "text-rose-400");
    } finally {
      setIsProcessingTurn(false);
    }
  };

  const handleAction = async (actionLabel: string, risk: number = 0.5) => {
    if (isProcessingTurn) return;
    setIsProcessingTurn(true);
    setCustomActionInput(""); // Clear input if used
    globalSoundEngine.playSFX('click');

    setGameState(prev => ({
        ...prev,
        narrativeHistory: [...prev.narrativeHistory, { text: `> ${actionLabel}`, type: 'action', timestamp: Date.now() }]
    }));

    const prompt = `Game Master Logic:
    Location: ${gameState.currentLocation}
    Action Taken: "${actionLabel}"
    Entropy: ${currentEntropy}
    Profile: ${activeProfile?.name || "Seeker"} (${activeProfile?.race} ${activeProfile?.class})
    Current Scene: ${gameState.currentSceneDescription}

    Determine the outcome. 
    1. Write a 1-2 sentence narrative result.
    2. Define any stat changes (integrity/sanity/flux).
    3. PROVIDE 3 NEW Available Actions for the player based on the new situation.

    Return JSON:
    {
      "resultText": "...",
      "deltaIntegrity": -5, 
      "deltaSanity": 0,
      "deltaFlux": 10,
      "newActions": [ { "id": "new_1", "label": "...", "type": "explore", "risk": 0.2 }, ... ]
    }`;

    try {
        const response = await invokeGemini(prompt, "Return valid JSON only. Do not wrap in markdown.");
        const outcome = cleanAndParseJSON<any>(response);

        if (outcome) {
            const newIntegrity = Math.max(0, Math.min(100, (gameState.vitals?.integrity || 100) + (outcome.deltaIntegrity || 0)));
            const newSanity = Math.max(0, Math.min(100, (gameState.vitals?.sanity || 100) + (outcome.deltaSanity || 0)));

            setGameState(prev => ({
                ...prev,
                vitals: { integrity: newIntegrity, sanity: newSanity },
                availableActions: (outcome.newActions && outcome.newActions.length > 0) ? outcome.newActions : DEFAULT_ACTIONS,
                narrativeHistory: [...prev.narrativeHistory, { text: outcome.resultText, type: 'narration', timestamp: Date.now() }]
            }));

            if (outcome.deltaFlux && onUpdateProfile && activeProfile) {
                onUpdateProfile({ ...activeProfile, flux: activeProfile.flux + outcome.deltaFlux });
                addEchoMessage(AgentName.RPGNexusAgent, `Flux ${outcome.deltaFlux > 0 ? '+' : ''}${outcome.deltaFlux}`, outcome.deltaFlux > 0 ? 'text-amber-300' : 'text-rose-400');
            }
            if (risk > 0.5) onUpdateSystemMetrics(0.01, -0.01); 
        } else {
             setGameState(prev => ({
                ...prev,
                availableActions: DEFAULT_ACTIONS,
                narrativeHistory: [...prev.narrativeHistory, { text: "The ether churns, obscuring the outcome. (Data corruption)", type: 'system', timestamp: Date.now() }]
            }));
        }
    } catch (e) {
        addEchoMessage(AgentName.System, "Action resolution failed. Systems rebooting...", "text-rose-400");
        setGameState(prev => ({ ...prev, availableActions: DEFAULT_ACTIONS }));
    } finally {
        setIsProcessingTurn(false);
    }
  };

  // --- NEW FEATURES ---

  const handleGenerateSceneVideo = async () => {
      if (isAnimatingScene || !gameState.currentSceneImageUrl) return;
      setIsAnimatingScene(true);
      addEchoMessage(AgentName.RPGNexusAgent, "Animating scene via Veo-3.1...", "text-fuchsia-300");

      try {
          const prompt = `Cinematic subtle motion, atmospheric video of ${gameState.currentSceneDescription}. ${currentEntropy > 0.6 ? 'Glitch art style, disturbing movement.' : 'Serene, flowing motion.'}`;
          const videoUrl = await generateVideo(prompt, gameState.currentSceneImageUrl);
          if (videoUrl) {
              setCurrentSceneVideoUrl(videoUrl);
              addEchoMessage(AgentName.RPGNexusAgent, "Scene animation compiled.", "text-emerald-300");
          } else {
              throw new Error("No video URL returned.");
          }
      } catch (e) {
          console.error(e);
          addEchoMessage(AgentName.System, "Video generation failed.", "text-rose-400");
      } finally {
          setIsAnimatingScene(false);
      }
  };

  const handleCompileStoryVideo = async () => {
      if (isCompilingStory || !gameState.sceneHistory || gameState.sceneHistory.length === 0) {
          addEchoMessage(AgentName.System, "No scene history to compile.", "text-yellow-400");
          return;
      }

      setIsCompilingStory(true);
      setCompilationProgress(0);
      addEchoMessage(AgentName.RPGNexusAgent, "Compiling narrative history into Quest Cinema...", "text-amber-300");

      try {
          if (!cinemaEngineRef.current) {
              cinemaEngineRef.current = new QuestCinemaEngine();
          }

          const slides = gameState.sceneHistory.map(scene => ({
              imageUrl: scene.imageUrl,
              text: scene.description
          }));

          const blob = await cinemaEngineRef.current.compileVideo(
              slides,
              (progress) => setCompilationProgress(Math.round(progress * 100)),
              async (text) => await generateSpeech(text) 
          );

          if (blob) {
              const url = URL.createObjectURL(blob);
              const a = document.createElement('a');
              a.href = url;
              a.download = `Nexus_Story_${Date.now()}.webm`; // Or mp4 based on engine support
              document.body.appendChild(a);
              a.click();
              document.body.removeChild(a);
              addEchoMessage(AgentName.RPGNexusAgent, "Story Compilation Complete. Downloading...", "text-emerald-300");

              if (onArtifactCreated) {
                  onArtifactCreated({
                      id: `cinema-${Date.now()}`,
                      name: "Quest Cinema Log",
                      type: ArtifactType.VisualMemory,
                      rarity: ArtifactRarity.Rare,
                      description: "A compiled video log of your recent journey.",
                      imageUrl: gameState.currentSceneImageUrl || "", // Thumbnail
                      timestamp: Date.now()
                  });
              }
          }
      } catch (e) {
          console.error(e);
          addEchoMessage(AgentName.System, "Story compilation failed.", "text-rose-400");
      } finally {
          setIsCompilingStory(false);
          setCompilationProgress(0);
      }
  };

  const handleDownloadStory = () => {
      const storyText = gameState.narrativeHistory.map(n => `[${new Date(n.timestamp).toLocaleTimeString()}] ${n.type.toUpperCase()}: ${n.text}`).join('\n\n');
      const blob = new Blob([storyText], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `Nexus_Log_${Date.now()}.txt`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      addEchoMessage(AgentName.RPGNexusAgent, "Narrative log exported.", "text-cyan-300");
  };

  const handleReimagineScene = async () => {
      if (isProcessingTurn || !gameState.currentSceneDescription) return;
      setIsProcessingTurn(true);
      addEchoMessage(AgentName.RPGNexusAgent, "Re-imagining reality matrix...", "text-purple-300");

      try {
          const imagePrompt = `Sci-fi fantasy concept art, ${gameState.currentLocation}, ${gameState.currentSceneDescription}, cinematic lighting, atmospheric, ${activeProfile?.visualFilter || 'cyberpunk'} style, ${currentEntropy > 0.6 ? 'glitch, chaos, fractal' : 'clean, ethereal, serene'}.`;

          const url = await generateImage(imagePrompt);
          if (url) {
             setGameState(prev => ({ 
                  ...prev, 
                  currentSceneImageUrl: url,
                  sceneHistory: [...(prev.sceneHistory || []), {
                      imageUrl: url,
                      location: prev.currentLocation,
                      description: prev.currentSceneDescription || "Reimagined scene",
                      timestamp: Date.now()
                  }]
              }));
              setCurrentSceneVideoUrl(null); // Clear video if scene changes
              addEchoMessage(AgentName.RPGNexusAgent, "Visuals re-synthesized.", "text-emerald-300");
          }
      } catch (e) {
          addEchoMessage(AgentName.System, "Reimagine failed.", "text-rose-400");
      } finally {
          setIsProcessingTurn(false);
      }
  };


  // -- Renders --

  const renderInitialization = () => (
    <div className="flex flex-col items-center justify-center h-full p-6 animate-fade-in-up bg-slate-900/50">
      <div className="text-5xl text-indigo-500 mb-6 animate-pulse"><i className="ri-radar-line"></i></div>
      <h3 className="text-2xl font-cinzel text-indigo-300 mb-3">Campaign Initialization</h3>
      <p className="text-base text-slate-400 mb-8 text-center max-w-lg leading-relaxed">
        The Nexus Engine requires an insertion vector. Scan the local entropy field to materialize potential timelines.
      </p>

      {scanResults ? (
         <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl">
            {Object.entries(scanResults).map(([name, dataRaw]) => {
                const data = dataRaw as RPGScanResultLocation;
                return (
                    <button 
                        key={name}
                        onClick={() => handleTravel(name, data)}
                        className="flex flex-col p-6 bg-slate-800/80 border-2 border-slate-600 rounded-xl hover:bg-slate-700 hover:border-cyan-500 hover:shadow-2xl hover:shadow-cyan-500/20 transition-all group text-left transform hover:-translate-y-1"
                    >
                        <div className="flex items-center justify-between mb-4 w-full">
                            <i className={`${data.icon || 'ri-map-pin-line'} text-3xl ${data.color || 'text-slate-200'}`}></i>
                            <span className="text-xs uppercase font-bold tracking-wider bg-slate-900 px-3 py-1 rounded text-slate-400 group-hover:text-white transition-colors">{data.risk} Risk</span>
                        </div>
                        <h4 className="font-cinzel font-bold text-xl text-slate-200 group-hover:text-cyan-300 mb-2">{name}</h4>
                        <p className="text-sm text-slate-400 font-cormorant leading-relaxed">{data.description}</p>
                    </button>
                );
            })}
         </div>
      ) : (
        <Button onClick={handleScanSector} disabled={isScanning} className="px-10 py-4 text-base tracking-widest bg-indigo-600 hover:bg-indigo-500 shadow-xl shadow-indigo-500/20 font-bold">
            {isScanning ? <><i className="ri-loader-4-line animate-spin mr-3"></i>SCANNING SECTOR...</> : <><i className="ri-search-eye-line mr-3"></i>SCAN FOR ANOMALIES</>}
        </Button>
      )}
    </div>
  );

  const renderGameInterface = () => (
    <div className="relative h-full w-full overflow-hidden bg-slate-950 font-sans">
        {/* BACKGROUND LAYER */}
        <div className="absolute inset-0 z-0">
            {currentSceneVideoUrl ? (
                <video src={currentSceneVideoUrl} autoPlay loop muted className="w-full h-full object-cover" />
            ) : gameState.currentSceneImageUrl ? (
                <img src={gameState.currentSceneImageUrl} alt="Scene" className="w-full h-full object-cover transition-opacity duration-1000 ease-in-out" />
            ) : (
                 <div className="w-full h-full bg-slate-900 flex items-center justify-center">
                    <div className="text-slate-700 animate-pulse text-6xl"><i className="ri-image-line"></i></div>
                 </div>
            )}
            {/* VIGNETTE & GRADIENT OVERLAY */}
            <div className="absolute inset-0 bg-gradient-to-b from-slate-950/80 via-transparent to-slate-950/90 pointer-events-none"></div>
            <div className="absolute inset-0 bg-black/20 pointer-events-none"></div> 
        </div>

        {/* CONTENT LAYER */}
        <div className="relative z-10 flex flex-col h-full p-4 pointer-events-none"> {/* content container */}

            {/* TOP BAR: Stats & Location */}
            <div className="flex justify-between items-start pointer-events-auto">
                 <div className="bg-slate-950/60 backdrop-blur-md border border-slate-700/50 rounded-lg p-3 shadow-lg max-w-md">
                    <h3 className="text-indigo-300 font-bold text-lg font-cinzel flex items-center gap-2">
                        <i className="ri-map-pin-user-fill"></i> {gameState.currentLocation}
                    </h3>
                    <div className="flex items-center gap-4 mt-2 text-xs font-mono text-slate-300">
                         <div className="flex items-center gap-1" title="Integrity"><i className="ri-heart-pulse-fill text-rose-500"></i> {gameState.vitals?.integrity}%</div>
                         <div className="flex items-center gap-1" title="Sanity"><i className="ri-brain-fill text-purple-400"></i> {gameState.vitals?.sanity}%</div>
                         <div className="flex items-center gap-1" title="Flux"><i className="ri-copper-coin-line text-amber-400"></i> {activeProfile?.flux || 0}</div>
                    </div>
                 </div>

                 {/* VISUAL CONTROLS (Top Right) */}
                 <div className="flex gap-2">
                    <button 
                        onClick={handleReimagineScene}
                        disabled={isProcessingTurn}
                        className="bg-slate-950/60 hover:bg-purple-900/60 backdrop-blur-md text-white p-2 rounded-lg border border-slate-600/50 transition-all hover:scale-105"
                        title="Reimagine Scene (Regenerate Image)"
                    >
                        <i className={`ri-refresh-line ${isProcessingTurn ? 'animate-spin' : ''}`}></i>
                    </button>
                    <button 
                        onClick={handleGenerateSceneVideo}
                        disabled={isAnimatingScene || !!currentSceneVideoUrl}
                        className="bg-slate-950/60 hover:bg-fuchsia-900/60 backdrop-blur-md text-white p-2 rounded-lg border border-slate-600/50 transition-all hover:scale-105"
                        title="Animate Scene (Veo Video)"
                    >
                        {isAnimatingScene ? <i className="ri-loader-4-line animate-spin"></i> : <i className="ri-movie-line"></i>}
                    </button>
                 </div>
            </div>

            {/* MIDDLE AREA */}
            <div className="flex-grow flex flex-col justify-end lg:flex-row lg:items-end lg:justify-between gap-4 min-h-0 mt-4">

                {/* ACTIONS DECK (Bottom Left) */}
                <div className="w-full lg:w-1/3 pointer-events-auto space-y-2">
                    {/* Custom Input */}
                    <div className="flex gap-2 mb-2 bg-slate-950/70 p-1.5 rounded-lg border border-slate-700/50 backdrop-blur-sm">
                        <input 
                            type="text" 
                            value={customActionInput}
                            onChange={(e) => setCustomActionInput(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleAction(customActionInput)}
                            placeholder="What do you do?"
                            className="flex-grow bg-transparent border-none text-sm text-slate-100 placeholder-slate-500 focus:ring-0"
                            disabled={isProcessingTurn}
                        />
                        <button 
                            onClick={() => handleAction(customActionInput)}
                            disabled={isProcessingTurn || !customActionInput.trim()}
                            className="text-indigo-400 hover:text-indigo-300 px-2"
                        >
                            <i className="ri-send-plane-fill"></i>
                        </button>
                    </div>

                    {/* Action Buttons */}
                    <div className="flex flex-col gap-2 max-h-48 overflow-y-auto custom-scrollbar-thin pr-1">
                        {gameState.availableActions?.map((action, idx) => {
                             // Determine styling based on risk
                             const riskInfo = getRiskLabel(action.risk);
                             const riskBorderClass = getRiskColor(action.risk);
                             // Adjust styling for glassmorphism
                             let btnBg = "bg-slate-900/60 hover:bg-slate-800/80";
                             let borderColor = "border-slate-600";
                             if(action.risk > 0.6) { borderColor = "border-rose-500/50"; btnBg = "bg-rose-950/40 hover:bg-rose-900/60"; }
                             else if(action.risk > 0.3) { borderColor = "border-amber-500/50"; btnBg = "bg-amber-950/40 hover:bg-amber-900/60"; }
                             else { borderColor = "border-emerald-500/50"; btnBg = "bg-emerald-950/40 hover:bg-emerald-900/60"; }

                             return (
                                <button
                                    key={idx}
                                    onClick={() => handleAction(action.label, action.risk)}
                                    disabled={isProcessingTurn}
                                    className={`w-full text-left p-3 rounded-lg border ${borderColor} ${btnBg} backdrop-blur-sm transition-all group flex justify-between items-center`}
                                >
                                    <span className="text-sm font-semibold text-slate-100 group-hover:text-white shadow-black drop-shadow-sm">{action.label}</span>
                                    <span className={`text-[10px] uppercase opacity-70 font-mono`}>{action.type}</span>
                                </button>
                            );
                        })}
                    </div>
                </div>

                {/* NARRATIVE LOG (Bottom Right) */}
                <div className="w-full lg:w-1/2 pointer-events-auto flex flex-col gap-2 max-h-[40vh]">
                     <div className="bg-slate-950/70 backdrop-blur-md border border-slate-700/50 rounded-lg p-4 overflow-y-auto custom-scrollbar flex-grow shadow-2xl">
                        {gameState.narrativeHistory.slice(-10).map((entry, i) => ( // Show last 10 entries contextually
                            <div key={i} className={`mb-3 last:mb-0 text-sm leading-relaxed ${entry.type === 'action' ? 'text-indigo-300 font-bold' : 'text-slate-300 font-cormorant'}`}>
                                {entry.type === 'action' && <span className="mr-2 opacity-50">></span>}
                                {entry.text}
                            </div>
                        ))}
                        <div ref={chatEndRef} />
                        {isProcessingTurn && (
                            <div className="text-xs text-indigo-400 animate-pulse mt-2 flex items-center gap-2">
                                <i className="ri-quill-pen-line"></i> The Game Master weaves the fate...
                            </div>
                        )}
                     </div>

                     {/* Meta Controls */}
                     <div className="flex gap-2 justify-end">
                        <Button onClick={handleCompileStoryVideo} disabled={isCompilingStory || !gameState.sceneHistory?.length} className="text-[10px] py-1 bg-amber-700/80 hover:bg-amber-600/80 backdrop-blur-sm">
                            {isCompilingStory ? `Compiling ${compilationProgress}%` : <><i className="ri-movie-2-line mr-1"></i> Story Movie</>}
                        </Button>
                        <Button onClick={handleDownloadStory} className="text-[10px] py-1 bg-cyan-700/80 hover:bg-cyan-600/80 backdrop-blur-sm">
                            <i className="ri-file-text-line mr-1"></i> Log
                        </Button>
                        <Button onClick={() => handleScanSector()} className="text-[10px] py-1 bg-indigo-700/80 hover:bg-indigo-600/80 backdrop-blur-sm">
                             <i className="ri-radar-line mr-1"></i> Rescan
                        </Button>
                     </div>
                </div>
            </div>
        </div>
    </div>
  );

  return (
    <div className="rpg-nexus-panel bg-slate-950 backdrop-blur-xl border border-indigo-600/50 rounded-xl shadow-2xl flex flex-col overflow-hidden transition-all duration-500 font-sans" style={{ width: width || '100%', height: height || '600px' }}>
      {/* Universal Header */}
      <div className="p-4 border-b border-indigo-800/50 bg-slate-900 flex justify-between items-center shrink-0 shadow-md z-20">
        <h3 className="text-xl font-cinzel font-bold text-indigo-300 flex items-center">
            <span className="bg-indigo-900/30 p-1.5 rounded-lg mr-3 border border-indigo-500/30"><i className="ri-gamepad-line text-indigo-400"></i></span>
            Nexus Engine
        </h3>
        {scanResults && (
             <button onClick={() => setScanResults(null)} className="text-xs font-bold text-slate-400 hover:text-white bg-slate-800 hover:bg-slate-700 px-3 py-1.5 rounded-lg transition-colors border border-slate-700">
                 <i className="ri-arrow-go-back-line mr-1"></i>Back to Game
             </button>
        )}
      </div>

      {/* Content Switcher */}
      <div className="flex-grow overflow-hidden relative">
          {(!scanResults && gameState.currentLocation === 'The Void Edge' && gameState.narrativeHistory.length <= 1) 
            ? renderInitialization() 
            : (scanResults ? renderInitialization() : renderGameInterface())
          }
      </div>
    </div>
  );
};

export default RPGNexusPanel;

import React, { useState, useEffect, useRef } from 'react';
import type { RPGNexusPanelProps, RPGGameState, RPGGameLocation, RPGDynamicAction, RPGSceneData } from '../../types';
import { AgentName, ArtifactType, ArtifactRarity } from '../../types';
import { Button } from '../ui/Button';
import { useGemini } from '../../context/GeminiIntegrationContext';
import { globalSoundEngine } from '../../lib/SoundEngine';
import { QuestCinemaEngine } from '../../lib/video/QuestCinemaEngine';

// --- Helper: Robust JSON Parsing ---
const cleanAndParseJSON = <T,>(text: string | null): T | null => {
  if (!text) return null;
  try {
    let cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    let data = JSON.parse(cleanText);
    const keys = Object.keys(data);
    if (keys.length === 1) {
      const rootKey = keys[0];
      if (['locations', 'rpg_locations', 'points_of_interest', 'data', 'result', 'outcome'].includes(rootKey.toLowerCase()) || 
          (typeof data[rootKey] === 'object' && !Array.isArray(data[rootKey]) && !data[rootKey].description && !data[rootKey].resultText)) {
          data = data[rootKey];
      }
    }
    return data as T;
  } catch (e) {
    console.error("RPGNexus: JSON Parsing Failed", e);
    return null;
  }
};

interface RPGScanResultLocation {
  description: string;
  color?: string;
  risk?: string;
  icon?: string;
}

const FALLBACK_LOCATIONS: Record<string, RPGScanResultLocation> = {
  "The Void Edge": { description: "A precipice where reality dissolves into static.", color: "text-slate-400", risk: "Extreme", icon: "ri-mist-line" },
  "Crystal Spire": { description: "A tower of singing glass reaching into the Aethel.", color: "text-cyan-300", risk: "Low", icon: "ri-building-2-line" },
  "Axiom Forge": { description: "Industrial complex where truths are hammered into shape.", color: "text-amber-400", risk: "Medium", icon: "ri-hammer-line" }
};

const DEFAULT_ACTIONS: RPGDynamicAction[] = [
    { id: 'def_explore', label: 'Survey the Area', type: 'explore', risk: 0.1, isDynamic: false },
    { id: 'def_scan', label: 'Scan for Anomalies', type: 'ritual', risk: 0.2, isDynamic: false },
    { id: 'def_rest', label: 'Recalibrate Systems', type: 'talk', risk: 0, isDynamic: false }
];

const RPGNexusPanel: React.FC<RPGNexusPanelProps> = ({
  width,
  height,
  addEchoMessage,
  activeProfile,
  onUpdateProfile,
  currentEntropy,
  onArtifactCreated,
  savedState,
  onSaveState,
  onUpdateSystemMetrics
}) => {
  const { invokeGemini, generateImage, generateVideo, generateSpeech, isGenerating } = useGemini();
  const chatEndRef = useRef<HTMLDivElement>(null);

  // -- State --
  const [gameState, setGameState] = useState<RPGGameState>(savedState || {
    currentLocation: 'The Void Edge',
    narrativeHistory: [{ text: "System Initialized. Awaiting Insertion Coordinates...", type: 'system', timestamp: Date.now() }],
    activeQuests: [],
    lastActionTimestamp: Date.now(),
    vitals: { integrity: 100, sanity: 100 },
    availableActions: DEFAULT_ACTIONS,
    achievements: [],
    combatState: { isActive: false, enemyName: '', enemyHp: 0, enemyMaxHp: 0, turn: 0, logs: [] },
    knownLocations: [],
    currentSceneDescription: "The initialization void. Static fills the air.",
    currentSceneImageUrl: null,
    sceneHistory: [] // New: Track scenes for video compilation
  });

  const [scanResults, setScanResults] = useState<Record<string, RPGScanResultLocation> | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [isProcessingTurn, setIsProcessingTurn] = useState(false);
  const [customActionInput, setCustomActionInput] = useState("");

  // -- Video & Cinema State --
  const [isAnimatingScene, setIsAnimatingScene] = useState(false);
  const [currentSceneVideoUrl, setCurrentSceneVideoUrl] = useState<string | null>(null);
  const [isCompilingStory, setIsCompilingStory] = useState(false);
  const [compilationProgress, setCompilationProgress] = useState(0);

  // -- Audio / Narrator State --
  const [isNarratorEnabled, setIsNarratorEnabled] = useState(false);
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);
  const [currentlyPlayingText, setCurrentlyPlayingText] = useState<string | null>(null);

  // -- Refs --
  const cinemaEngineRef = useRef<QuestCinemaEngine | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    return () => {
        if (cinemaEngineRef.current) cinemaEngineRef.current.dispose();
        if (audioContextRef.current) audioContextRef.current.close();
    }
  }, []);

  // -- Persistence --
  useEffect(() => {
    if (onSaveState) onSaveState(gameState);
  }, [gameState, onSaveState]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [gameState.narrativeHistory]);

  const getRiskColor = (risk: number) => {
      if (risk >= 0.7) return 'border-rose-500 hover:bg-rose-900/30 text-rose-200';
      if (risk >= 0.4) return 'border-amber-500 hover:bg-amber-900/30 text-amber-200';
      return 'border-emerald-500 hover:bg-emerald-900/30 text-emerald-200';
  };

  const getRiskLabel = (risk: number) => {
      if (risk >= 0.7) return { text: 'HIGH RISK', color: 'text-rose-400' };
      if (risk >= 0.4) return { text: 'MED RISK', color: 'text-amber-400' };
      return { text: 'LOW RISK', color: 'text-emerald-400' };
  };

  // --- AUDIO HELPER ---
  const playNarrativeAudio = async (text: string) => {
    if (!text) return;
    setIsPlayingAudio(true);
    setCurrentlyPlayingText(text);

    try {
        if (!audioContextRef.current) {
            audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
        }
        if (audioContextRef.current.state === 'suspended') {
            await audioContextRef.current.resume();
        }

        const audioData = await generateSpeech(text);
        if (audioData) {
            const buffer = await audioContextRef.current.decodeAudioData(audioData);
            const source = audioContextRef.current.createBufferSource();
            source.buffer = buffer;
            source.connect(audioContextRef.current.destination);
            source.onended = () => {
                setIsPlayingAudio(false);
                setCurrentlyPlayingText(null);
            };
            source.start(0);
        } else {
             // Fallback to browser TTS if API fails/quota
             const utterance = new SpeechSynthesisUtterance(text);
             utterance.onend = () => {
                 setIsPlayingAudio(false);
                 setCurrentlyPlayingText(null);
             };
             window.speechSynthesis.speak(utterance);
        }
    } catch (e) {
        console.error("Audio playback error", e);
        setIsPlayingAudio(false);
        setCurrentlyPlayingText(null);
    }
  };

  // --- CORE ENGINE ---

  const handleScanSector = async () => {
    if (isScanning || isGenerating) return;
    setIsScanning(true);
    globalSoundEngine.playSFX('click');
    addEchoMessage(AgentName.RPGNexusAgent, "Scanning sector for stability variances...", "text-indigo-300");

    const prompt = `Generate 3 unique, evocative RPG locations for a sci-fi/fantasy setting with entropy level ${currentEntropy.toFixed(2)}.
    Output strictly as JSON. Keys are location names.
    Values must be objects with:
    - "description": string (1 sentence)
    - "color": string (Tailwind text class, e.g. "text-red-400")
    - "risk": string ("Low", "Medium", "High", "Extreme")
    - "icon": string (RemixIcon class, e.g. "ri-skull-line")`;

    try {
      const response = await invokeGemini(prompt, "You are a JSON generator. Do not include markdown formatting.");
      const locations = cleanAndParseJSON<Record<string, RPGScanResultLocation>>(response);
      setScanResults(locations || FALLBACK_LOCATIONS);

      if (isNarratorEnabled) playNarrativeAudio("Sector scan complete. Anomalies detected.");
    } catch (err) {
      setScanResults(FALLBACK_LOCATIONS);
    } finally {
      setIsScanning(false);
    }
  };

  const handleTravel = async (locationName: string, locationData: RPGScanResultLocation) => {
    setScanResults(null); 
    setIsProcessingTurn(true);
    setCurrentSceneVideoUrl(null); // Reset video on travel
    addEchoMessage(AgentName.RPGNexusAgent, `Vectoring to ${locationName}...`, "text-cyan-300");
    globalSoundEngine.playSFX('pulse');

    setGameState(prev => ({
      ...prev,
      currentLocation: locationName as RPGGameLocation,
      narrativeHistory: [...prev.narrativeHistory, { text: `Arrived at ${locationName}.`, type: 'action', timestamp: Date.now() }]
    }));

    try {
      const textPrompt = `You are the Game Master. The player has just arrived at "${locationName}" (${locationData.description}).
      Current Entropy: ${currentEntropy}.
      1. Write a vivid, 2-sentence sensory description of the scene.
      2. Provide 3 distinct actions the player can take (Explore, Talk, Analyze, Ritual, etc.).
      3. Create a short quest title related to this location.

      Return JSON:
      {
        "description": "...",
        "actions": [ { "id": "act_1", "label": "...", "type": "explore", "risk": 0.2 }, ... ],
        "quest": { "title": "...", "description": "...", "rewards": { "xp": 100, "flux": 50 } }
      }`;

      const textResponseRaw = await invokeGemini(textPrompt, "Return valid JSON only.");
      const textData = cleanAndParseJSON<any>(textResponseRaw);

      if (textData) {
        // Image Gen
        const imagePrompt = `Sci-fi fantasy concept art, ${locationName}, ${textData.description}, cinematic lighting, atmospheric, ${currentEntropy > 0.6 ? 'glitch, chaos, fractal' : 'clean, ethereal, serene'}.`;
        generateImage(imagePrompt).then(url => {
          if (url) {
            setGameState(prev => {
                const newHistoryEntry: RPGSceneData = {
                    imageUrl: url,
                    location: locationName as RPGGameLocation,
                    description: textData.description,
                    timestamp: Date.now()
                };
                return { 
                    ...prev, 
                    currentSceneImageUrl: url,
                    sceneHistory: [...(prev.sceneHistory || []), newHistoryEntry] 
                };
            });
          }
        });

        setGameState(prev => ({
          ...prev,
          currentSceneDescription: textData.description,
          availableActions: textData.actions || DEFAULT_ACTIONS,
          activeQuests: prev.activeQuests.length < 3 ? [...prev.activeQuests, { ...textData.quest, id: `quest-${Date.now()}`, status: 'active' }] : prev.activeQuests,
          narrativeHistory: [...prev.narrativeHistory, { text: textData.description, type: 'narration', timestamp: Date.now() }]
        }));

        if (isNarratorEnabled) playNarrativeAudio(textData.description);
      }
    } catch (e) {
      console.error("Travel generation failed", e);
      addEchoMessage(AgentName.System, "Navigational data corrupted. Using fallback protocols.", "text-rose-400");
    } finally {
      setIsProcessingTurn(false);
    }
  };

  const handleAction = async (actionLabel: string, risk: number = 0.5) => {
    if (isProcessingTurn) return;
    setIsProcessingTurn(true);
    setCustomActionInput(""); // Clear input if used
    globalSoundEngine.playSFX('click');

    setGameState(prev => ({
        ...prev,
        narrativeHistory: [...prev.narrativeHistory, { text: `> ${actionLabel}`, type: 'action', timestamp: Date.now() }]
    }));

    const prompt = `Game Master Logic:
    Location: ${gameState.currentLocation}
    Action Taken: "${actionLabel}"
    Entropy: ${currentEntropy}
    Profile: ${activeProfile?.name || "Seeker"} (${activeProfile?.race} ${activeProfile?.class})
    Current Scene: ${gameState.currentSceneDescription}

    Determine the outcome. 
    1. Write a 1-2 sentence narrative result.
    2. Define any stat changes (integrity/sanity/flux).
    3. PROVIDE 3 NEW Available Actions for the player based on the new situation.

    Return JSON:
    {
      "resultText": "...",
      "deltaIntegrity": -5, 
      "deltaSanity": 0,
      "deltaFlux": 10,
      "newActions": [ { "id": "new_1", "label": "...", "type": "explore", "risk": 0.2 }, ... ]
    }`;

    try {
        const response = await invokeGemini(prompt, "Return valid JSON only. Do not wrap in markdown.");
        const outcome = cleanAndParseJSON<any>(response);

        if (outcome) {
            const newIntegrity = Math.max(0, Math.min(100, (gameState.vitals?.integrity || 100) + (outcome.deltaIntegrity || 0)));
            const newSanity = Math.max(0, Math.min(100, (gameState.vitals?.sanity || 100) + (outcome.deltaSanity || 0)));

            setGameState(prev => ({
                ...prev,
                vitals: { integrity: newIntegrity, sanity: newSanity },
                availableActions: (outcome.newActions && outcome.newActions.length > 0) ? outcome.newActions : DEFAULT_ACTIONS,
                narrativeHistory: [...prev.narrativeHistory, { text: outcome.resultText, type: 'narration', timestamp: Date.now() }]
            }));

            if (outcome.deltaFlux && onUpdateProfile && activeProfile) {
                onUpdateProfile({ ...activeProfile, flux: activeProfile.flux + outcome.deltaFlux });
                addEchoMessage(AgentName.RPGNexusAgent, `Flux ${outcome.deltaFlux > 0 ? '+' : ''}${outcome.deltaFlux}`, outcome.deltaFlux > 0 ? 'text-amber-300' : 'text-rose-400');
            }
            if (risk > 0.5) onUpdateSystemMetrics(0.01, -0.01); 

            if (isNarratorEnabled) playNarrativeAudio(outcome.resultText);

        } else {
             setGameState(prev => ({
                ...prev,
                availableActions: DEFAULT_ACTIONS,
                narrativeHistory: [...prev.narrativeHistory, { text: "The ether churns, obscuring the outcome. (Data corruption)", type: 'system', timestamp: Date.now() }]
            }));
        }
    } catch (e) {
        addEchoMessage(AgentName.System, "Action resolution failed. Systems rebooting...", "text-rose-400");
        setGameState(prev => ({ ...prev, availableActions: DEFAULT_ACTIONS }));
    } finally {
        setIsProcessingTurn(false);
    }
  };

  // --- NEW FEATURES ---

  const handleGenerateSceneVideo = async () => {
      if (isAnimatingScene || !gameState.currentSceneImageUrl) return;
      setIsAnimatingScene(true);
      addEchoMessage(AgentName.RPGNexusAgent, "Animating scene via Veo-3.1...", "text-fuchsia-300");

      try {
          const prompt = `Cinematic subtle motion, atmospheric video of ${gameState.currentSceneDescription}. ${currentEntropy > 0.6 ? 'Glitch art style, disturbing movement.' : 'Serene, flowing motion.'}`;
          const videoUrl = await generateVideo(prompt, gameState.currentSceneImageUrl);
          if (videoUrl) {
              setCurrentSceneVideoUrl(videoUrl);
              addEchoMessage(AgentName.RPGNexusAgent, "Scene animation compiled.", "text-emerald-300");
          } else {
              throw new Error("No video URL returned.");
          }
      } catch (e) {
          console.error(e);
          addEchoMessage(AgentName.System, "Video generation failed.", "text-rose-400");
      } finally {
          setIsAnimatingScene(false);
      }
  };

  const handleCompileStoryVideo = async () => {
      if (isCompilingStory || !gameState.sceneHistory || gameState.sceneHistory.length === 0) {
          addEchoMessage(AgentName.System, "No scene history to compile.", "text-yellow-400");
          return;
      }

      setIsCompilingStory(true);
      setCompilationProgress(0);
      addEchoMessage(AgentName.RPGNexusAgent, "Compiling narrative history into Quest Cinema...", "text-amber-300");

      try {
          if (!cinemaEngineRef.current) {
              cinemaEngineRef.current = new QuestCinemaEngine();
          }

          const slides = gameState.sceneHistory.map(scene => ({
              imageUrl: scene.imageUrl,
              text: scene.description
          }));

          const blob = await cinemaEngineRef.current.compileVideo(
              slides,
              (progress) => setCompilationProgress(Math.round(progress * 100)),
              async (text) => await generateSpeech(text) 
          );

          if (blob) {
              const url = URL.createObjectURL(blob);
              const a = document.createElement('a');
              a.href = url;
              a.download = `Nexus_Story_${Date.now()}.webm`; // Or mp4 based on engine support
              document.body.appendChild(a);
              a.click();
              document.body.removeChild(a);
              addEchoMessage(AgentName.RPGNexusAgent, "Story Compilation Complete. Downloading...", "text-emerald-300");

              if (onArtifactCreated) {
                  onArtifactCreated({
                      id: `cinema-${Date.now()}`,
                      name: "Quest Cinema Log",
                      type: ArtifactType.VisualMemory,
                      rarity: ArtifactRarity.Rare,
                      description: "A compiled video log of your recent journey.",
                      imageUrl: gameState.currentSceneImageUrl || "", // Thumbnail
                      timestamp: Date.now()
                  });
              }
          }
      } catch (e) {
          console.error(e);
          addEchoMessage(AgentName.System, "Story compilation failed.", "text-rose-400");
      } finally {
          setIsCompilingStory(false);
          setCompilationProgress(0);
      }
  };

  const handleDownloadStory = () => {
      const storyText = gameState.narrativeHistory.map(n => `[${new Date(n.timestamp).toLocaleTimeString()}] ${n.type.toUpperCase()}: ${n.text}`).join('\n\n');
      const blob = new Blob([storyText], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `Nexus_Log_${Date.now()}.txt`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      addEchoMessage(AgentName.RPGNexusAgent, "Narrative log exported.", "text-cyan-300");
  };

  const handleReimagineScene = async () => {
      if (isProcessingTurn || !gameState.currentSceneDescription) return;
      setIsProcessingTurn(true);
      addEchoMessage(AgentName.RPGNexusAgent, "Re-imagining reality matrix...", "text-purple-300");

      try {
          const imagePrompt = `Sci-fi fantasy concept art, ${gameState.currentLocation}, ${gameState.currentSceneDescription}, cinematic lighting, atmospheric, ${activeProfile?.visualFilter || 'cyberpunk'} style, ${currentEntropy > 0.6 ? 'glitch, chaos, fractal' : 'clean, ethereal, serene'}.`;

          const url = await generateImage(imagePrompt);
          if (url) {
             setGameState(prev => ({ 
                  ...prev, 
                  currentSceneImageUrl: url,
                  sceneHistory: [...(prev.sceneHistory || []), {
                      imageUrl: url,
                      location: prev.currentLocation,
                      description: prev.currentSceneDescription || "Reimagined scene",
                      timestamp: Date.now()
                  }]
              }));
              setCurrentSceneVideoUrl(null); // Clear video if scene changes
              addEchoMessage(AgentName.RPGNexusAgent, "Visuals re-synthesized.", "text-emerald-300");
          }
      } catch (e) {
          addEchoMessage(AgentName.System, "Reimagine failed.", "text-rose-400");
      } finally {
          setIsProcessingTurn(false);
      }
  };


  // -- Renders --

  const renderInitialization = () => (
    <div className="flex flex-col items-center justify-center h-full p-6 animate-fade-in-up bg-slate-900/50">
      <div className="text-5xl text-indigo-500 mb-6 animate-pulse"><i className="ri-radar-line"></i></div>
      <h3 className="text-2xl font-cinzel text-indigo-300 mb-3">Campaign Initialization</h3>
      <p className="text-base text-slate-400 mb-8 text-center max-w-lg leading-relaxed">
        The Nexus Engine requires an insertion vector. Scan the local entropy field to materialize potential timelines.
      </p>

      {scanResults ? (
         <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl">
            {Object.entries(scanResults).map(([name, dataRaw]) => {
                const data = dataRaw as RPGScanResultLocation;
                return (
                    <button 
                        key={name}
                        onClick={() => handleTravel(name, data)}
                        className="flex flex-col p-6 bg-slate-800/80 border-2 border-slate-600 rounded-xl hover:bg-slate-700 hover:border-cyan-500 hover:shadow-2xl hover:shadow-cyan-500/20 transition-all group text-left transform hover:-translate-y-1"
                    >
                        <div className="flex items-center justify-between mb-4 w-full">
                            <i className={`${data.icon || 'ri-map-pin-line'} text-3xl ${data.color || 'text-slate-200'}`}></i>
                            <span className="text-xs uppercase font-bold tracking-wider bg-slate-900 px-3 py-1 rounded text-slate-400 group-hover:text-white transition-colors">{data.risk} Risk</span>
                        </div>
                        <h4 className="font-cinzel font-bold text-xl text-slate-200 group-hover:text-cyan-300 mb-2">{name}</h4>
                        <p className="text-sm text-slate-400 font-cormorant leading-relaxed">{data.description}</p>
                    </button>
                );
            })}
         </div>
      ) : (
        <Button onClick={handleScanSector} disabled={isScanning} className="px-10 py-4 text-base tracking-widest bg-indigo-600 hover:bg-indigo-500 shadow-xl shadow-indigo-500/20 font-bold">
            {isScanning ? <><i className="ri-loader-4-line animate-spin mr-3"></i>SCANNING SECTOR...</> : <><i className="ri-search-eye-line mr-3"></i>SCAN FOR ANOMALIES</>}
        </Button>
      )}
    </div>
  );

  const renderGameInterface = () => (
    <div className="relative h-full w-full overflow-hidden bg-slate-950 font-sans">
        {/* BACKGROUND LAYER */}
        <div className="absolute inset-0 z-0">
            {currentSceneVideoUrl ? (
                <video src={currentSceneVideoUrl} autoPlay loop muted className="w-full h-full object-cover" />
            ) : gameState.currentSceneImageUrl ? (
                <img src={gameState.currentSceneImageUrl} alt="Scene" className="w-full h-full object-cover transition-opacity duration-1000 ease-in-out" />
            ) : (
                 <div className="w-full h-full bg-slate-900 flex items-center justify-center">
                    <div className="text-slate-700 animate-pulse text-6xl"><i className="ri-image-line"></i></div>
                 </div>
            )}
            {/* VIGNETTE & GRADIENT OVERLAY */}
            <div className="absolute inset-0 bg-gradient-to-b from-slate-950/80 via-transparent to-slate-950/90 pointer-events-none"></div>
            <div className="absolute inset-0 bg-black/20 pointer-events-none"></div> 
        </div>

        {/* CONTENT LAYER */}
        <div className="relative z-10 flex flex-col h-full p-4 pointer-events-none"> {/* content container */}

            {/* TOP BAR: Stats & Location */}
            <div className="flex justify-between items-start pointer-events-auto">
                 <div className="bg-slate-950/60 backdrop-blur-md border border-slate-700/50 rounded-lg p-3 shadow-lg max-w-md">
                    <h3 className="text-indigo-300 font-bold text-lg font-cinzel flex items-center gap-2">
                        <i className="ri-map-pin-user-fill"></i> {gameState.currentLocation}
                    </h3>
                    <div className="flex items-center gap-4 mt-2 text-xs font-mono text-slate-300">
                         <div className="flex items-center gap-1" title="Integrity"><i className="ri-heart-pulse-fill text-rose-500"></i> {gameState.vitals?.integrity}%</div>
                         <div className="flex items-center gap-1" title="Sanity"><i className="ri-brain-fill text-purple-400"></i> {gameState.vitals?.sanity}%</div>
                         <div className="flex items-center gap-1" title="Flux"><i className="ri-copper-coin-line text-amber-400"></i> {activeProfile?.flux || 0}</div>
                    </div>
                 </div>

                 {/* VISUAL & AUDIO CONTROLS (Top Right) */}
                 <div className="flex gap-2">
                    <button
                        onClick={() => setIsNarratorEnabled(!isNarratorEnabled)}
                        className={`bg-slate-950/60 backdrop-blur-md p-2 rounded-lg border transition-all hover:scale-105 ${isNarratorEnabled ? 'border-emerald-500 text-emerald-400' : 'border-slate-600/50 text-slate-400 hover:text-white'}`}
                        title={isNarratorEnabled ? "Disable Narrator" : "Enable Narrator Mode (Reads new events)"}
                        aria-pressed={isNarratorEnabled}
                        aria-label="Toggle Narrator"
                    >
                        <i className={`ri-volume-${isNarratorEnabled ? 'up' : 'mute'}-line`}></i>
                    </button>
                    <button 
                        onClick={handleReimagineScene}
                        disabled={isProcessingTurn}
                        className="bg-slate-950/60 hover:bg-purple-900/60 backdrop-blur-md text-white p-2 rounded-lg border border-slate-600/50 transition-all hover:scale-105"
                        title="Reimagine Scene (Regenerate Image)"
                    >
                        <i className={`ri-refresh-line ${isProcessingTurn ? 'animate-spin' : ''}`}></i>
                    </button>
                    <button 
                        onClick={handleGenerateSceneVideo}
                        disabled={isAnimatingScene || !!currentSceneVideoUrl}
                        className="bg-slate-950/60 hover:bg-fuchsia-900/60 backdrop-blur-md text-white p-2 rounded-lg border border-slate-600/50 transition-all hover:scale-105"
                        title="Animate Scene (Veo Video)"
                    >
                        {isAnimatingScene ? <i className="ri-loader-4-line animate-spin"></i> : <i className="ri-movie-line"></i>}
                    </button>
                 </div>
            </div>

            {/* MIDDLE AREA */}
            <div className="flex-grow flex flex-col justify-end lg:flex-row lg:items-end lg:justify-between gap-4 min-h-0 mt-4">

                {/* ACTIONS DECK (Bottom Left) */}
                <div className="w-full lg:w-1/3 pointer-events-auto space-y-2">
                    {/* Custom Input */}
                    <div className="flex gap-2 mb-2 bg-slate-950/70 p-1.5 rounded-lg border border-slate-700/50 backdrop-blur-sm">
                        <input 
                            type="text" 
                            value={customActionInput}
                            onChange={(e) => setCustomActionInput(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleAction(customActionInput)}
                            placeholder="What do you do?"
                            className="flex-grow bg-transparent border-none text-sm text-slate-100 placeholder-slate-500 focus:ring-0"
                            disabled={isProcessingTurn}
                        />
                        <button 
                            onClick={() => handleAction(customActionInput)}
                            disabled={isProcessingTurn || !customActionInput.trim()}
                            className="text-indigo-400 hover:text-indigo-300 px-2"
                        >
                            <i className="ri-send-plane-fill"></i>
                        </button>
                    </div>

                    {/* Action Buttons */}
                    <div className="flex flex-col gap-2 max-h-48 overflow-y-auto custom-scrollbar-thin pr-1">
                        {gameState.availableActions?.map((action, idx) => {
                             // Determine styling based on risk
                             const riskInfo = getRiskLabel(action.risk);
                             const riskBorderClass = getRiskColor(action.risk);
                             // Adjust styling for glassmorphism
                             let btnBg = "bg-slate-900/60 hover:bg-slate-800/80";
                             let borderColor = "border-slate-600";
                             if(action.risk > 0.6) { borderColor = "border-rose-500/50"; btnBg = "bg-rose-950/40 hover:bg-rose-900/60"; }
                             else if(action.risk > 0.3) { borderColor = "border-amber-500/50"; btnBg = "bg-amber-950/40 hover:bg-amber-900/60"; }
                             else { borderColor = "border-emerald-500/50"; btnBg = "bg-emerald-950/40 hover:bg-emerald-900/60"; }

                             return (
                                <button
                                    key={idx}
                                    onClick={() => handleAction(action.label, action.risk)}
                                    disabled={isProcessingTurn}
                                    className={`w-full text-left p-3 rounded-lg border ${borderColor} ${btnBg} backdrop-blur-sm transition-all group flex justify-between items-center`}
                                >
                                    <span className="text-sm font-semibold text-slate-100 group-hover:text-white shadow-black drop-shadow-sm">{action.label}</span>
                                    <span className={`text-[10px] uppercase opacity-70 font-mono`}>{action.type}</span>
                                </button>
                            );
                        })}
                    </div>
                </div>

                {/* NARRATIVE LOG (Bottom Right) */}
                <div className="w-full lg:w-1/2 pointer-events-auto flex flex-col gap-2 max-h-[40vh]">
                     <div className="bg-slate-950/70 backdrop-blur-md border border-slate-700/50 rounded-lg p-4 overflow-y-auto custom-scrollbar flex-grow shadow-2xl relative">
                        {gameState.narrativeHistory.slice(-10).map((entry, i) => ( // Show last 10 entries contextually
                            <div key={i} className={`mb-3 last:mb-0 text-sm leading-relaxed relative pr-8 group/entry ${entry.type === 'action' ? 'text-indigo-300 font-bold' : 'text-slate-300 font-cormorant'}`}>
                                {entry.type === 'action' && <span className="mr-2 opacity-50">></span>}
                                {entry.text}
                                <button 
                                    onClick={() => playNarrativeAudio(entry.text)}
                                    className={`absolute top-0 right-0 text-slate-500 hover:text-emerald-400 p-1 opacity-0 group-hover/entry:opacity-100 transition-opacity ${isPlayingAudio && currentlyPlayingText === entry.text ? 'text-emerald-400 opacity-100 animate-pulse' : ''}`}
                                    title="Play Audio"
                                    aria-label="Play narrative audio"
                                >
                                    <i className={`ri-${isPlayingAudio && currentlyPlayingText === entry.text ? 'volume-up' : 'play-circle'}-line`}></i>
                                </button>
                            </div>
                        ))}
                        <div ref={chatEndRef} />
                        {isProcessingTurn && (
                            <div className="text-xs text-indigo-400 animate-pulse mt-2 flex items-center gap-2">
                                <i className="ri-quill-pen-line"></i> The Game Master weaves the fate...
                            </div>
                        )}
                        {/* Audio Status Indicator */}
                        {isPlayingAudio && (
                             <div className="absolute bottom-2 right-4 bg-black/60 backdrop-blur px-2 py-1 rounded-full text-[10px] text-emerald-400 flex items-center gap-2 border border-emerald-500/30">
                                 <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-ping"></span>
                                 Speaking...
                             </div>
                        )}
                     </div>

                     {/* Meta Controls */}
                     <div className="flex gap-2 justify-end">
                        <Button onClick={handleCompileStoryVideo} disabled={isCompilingStory || !gameState.sceneHistory?.length} className="text-[10px] py-1 bg-amber-700/80 hover:bg-amber-600/80 backdrop-blur-sm">
                            {isCompilingStory ? `Compiling ${compilationProgress}%` : <><i className="ri-movie-2-line mr-1"></i> Story Movie</>}
                        </Button>
                        <Button onClick={handleDownloadStory} className="text-[10px] py-1 bg-cyan-700/80 hover:bg-cyan-600/80 backdrop-blur-sm">
                            <i className="ri-file-text-line mr-1"></i> Log
                        </Button>
                        <Button onClick={() => handleScanSector()} className="text-[10px] py-1 bg-indigo-700/80 hover:bg-indigo-600/80 backdrop-blur-sm">
                             <i className="ri-radar-line mr-1"></i> Rescan
                        </Button>
                     </div>
                </div>
            </div>
        </div>
    </div>
  );

  return (
    <div className="rpg-nexus-panel bg-slate-950 backdrop-blur-xl border border-indigo-600/50 rounded-xl shadow-2xl flex flex-col overflow-hidden transition-all duration-500 font-sans" style={{ width: width || '100%', height: height || '600px' }}>
      {/* Universal Header */}
      <div className="p-4 border-b border-indigo-800/50 bg-slate-900 flex justify-between items-center shrink-0 shadow-md z-20">
        <h3 className="text-xl font-cinzel font-bold text-indigo-300 flex items-center">
            <span className="bg-indigo-900/30 p-1.5 rounded-lg mr-3 border border-indigo-500/30"><i className="ri-gamepad-line text-indigo-400"></i></span>
            Nexus Engine
        </h3>
        {scanResults && (
             <button onClick={() => setScanResults(null)} className="text-xs font-bold text-slate-400 hover:text-white bg-slate-800 hover:bg-slate-700 px-3 py-1.5 rounded-lg transition-colors border border-slate-700">
                 <i className="ri-arrow-go-back-line mr-1"></i>Back to Game
             </button>
        )}
      </div>

      {/* Content Switcher */}
      <div className="flex-grow overflow-hidden relative">
          {(!scanResults && gameState.currentLocation === 'The Void Edge' && gameState.narrativeHistory.length <= 1) 
            ? renderInitialization() 
            : (scanResults ? renderInitialization() : renderGameInterface())
          }
      </div>
    </div>
  );
};

export default RPGNexusPanel;

import React, { useState, useEffect, useRef } from 'react';
import type { RPGNexusPanelProps, RPGGameState, RPGGameLocation, RPGDynamicAction, RPGSceneData } from '../../types';
import { AgentName, ArtifactType, ArtifactRarity } from '../../types';
import { Button } from '../ui/Button';
import { useGemini } from '../../context/GeminiIntegrationContext';
import { globalSoundEngine } from '../../lib/SoundEngine';
import { QuestCinemaEngine } from '../../lib/video/QuestCinemaEngine';

// --- Helper: Robust JSON Parsing ---
const cleanAndParseJSON = <T,>(text: string | null): T | null => {
  if (!text) return null;
  try {
    let cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    let data = JSON.parse(cleanText);
    const keys = Object.keys(data);
    if (keys.length === 1) {
      const rootKey = keys[0];
      if (['locations', 'rpg_locations', 'points_of_interest', 'data', 'result', 'outcome'].includes(rootKey.toLowerCase()) || 
          (typeof data[rootKey] === 'object' && !Array.isArray(data[rootKey]) && !data[rootKey].description && !data[rootKey].resultText)) {
          data = data[rootKey];
      }
    }
    return data as T;
  } catch (e) {
    console.error("RPGNexus: JSON Parsing Failed", e);
    return null;
  }
};

interface RPGScanResultLocation {
  description: string;
  color?: string;
  risk?: string;
  icon?: string;
}

const FALLBACK_LOCATIONS: Record<string, RPGScanResultLocation> = {
  "The Void Edge": { description: "A precipice where reality dissolves into static.", color: "text-slate-400", risk: "Extreme", icon: "ri-mist-line" },
  "Crystal Spire": { description: "A tower of singing glass reaching into the Aethel.", color: "text-cyan-300", risk: "Low", icon: "ri-building-2-line" },
  "Axiom Forge": { description: "Industrial complex where truths are hammered into shape.", color: "text-amber-400", risk: "Medium", icon: "ri-hammer-line" }
};

const DEFAULT_ACTIONS: RPGDynamicAction[] = [
    { id: 'def_explore', label: 'Survey the Area', type: 'explore', risk: 0.1, isDynamic: false },
    { id: 'def_scan', label: 'Scan for Anomalies', type: 'ritual', risk: 0.2, isDynamic: false },
    { id: 'def_rest', label: 'Recalibrate Systems', type: 'talk', risk: 0, isDynamic: false }
];

const RPGNexusPanel: React.FC<RPGNexusPanelProps> = ({
  width,
  height,
  addEchoMessage,
  activeProfile,
  onUpdateProfile,
  currentEntropy,
  onArtifactCreated,
  savedState,
  onSaveState,
  onUpdateSystemMetrics
}) => {
  const { invokeGemini, generateImage, generateVideo, generateSpeech, isGenerating } = useGemini();
  const chatEndRef = useRef<HTMLDivElement>(null);

  // -- State --
  const [gameState, setGameState] = useState<RPGGameState>(savedState || {
    currentLocation: 'The Void Edge',
    narrativeHistory: [{ text: "System Initialized. Awaiting Insertion Coordinates...", type: 'system', timestamp: Date.now() }],
    activeQuests: [],
    lastActionTimestamp: Date.now(),
    vitals: { integrity: 100, sanity: 100 },
    availableActions: DEFAULT_ACTIONS,
    achievements: [],
    combatState: { isActive: false, enemyName: '', enemyHp: 0, enemyMaxHp: 0, turn: 0, logs: [] },
    knownLocations: [],
    currentSceneDescription: "The initialization void. Static fills the air.",
    currentSceneImageUrl: null,
    sceneHistory: [] // New: Track scenes for video compilation
  });

  const [scanResults, setScanResults] = useState<Record<string, RPGScanResultLocation> | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [isProcessingTurn, setIsProcessingTurn] = useState(false);
  const [customActionInput, setCustomActionInput] = useState("");

  // -- Video & Cinema State --
  const [isAnimatingScene, setIsAnimatingScene] = useState(false);
  const [currentSceneVideoUrl, setCurrentSceneVideoUrl] = useState<string | null>(null);
  const [isCompilingStory, setIsCompilingStory] = useState(false);
  const [compilationProgress, setCompilationProgress] = useState(0);

  // -- Audio / Narrator State --
  const [isNarratorEnabled, setIsNarratorEnabled] = useState(false);
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);
  const [currentlyPlayingText, setCurrentlyPlayingText] = useState<string | null>(null);

  // -- Refs --
  const cinemaEngineRef = useRef<QuestCinemaEngine | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    return () => {
        if (cinemaEngineRef.current) cinemaEngineRef.current.dispose();
        if (audioContextRef.current) audioContextRef.current.close();
    }
  }, []);

  // -- Persistence --
  useEffect(() => {
    if (onSaveState) onSaveState(gameState);
  }, [gameState, onSaveState]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [gameState.narrativeHistory]);

  const getRiskColor = (risk: number) => {
      if (risk >= 0.7) return 'border-rose-500 hover:bg-rose-900/30 text-rose-200';
      if (risk >= 0.4) return 'border-amber-500 hover:bg-amber-900/30 text-amber-200';
      return 'border-emerald-500 hover:bg-emerald-900/30 text-emerald-200';
  };

  const getRiskLabel = (risk: number) => {
      if (risk >= 0.7) return { text: 'HIGH RISK', color: 'text-rose-400' };
      if (risk >= 0.4) return { text: 'MED RISK', color: 'text-amber-400' };
      return { text: 'LOW RISK', color: 'text-emerald-400' };
  };

  // --- AUDIO HELPER ---
  const playNarrativeAudio = async (text: string) => {
    if (!text) return;
    setIsPlayingAudio(true);
    setCurrentlyPlayingText(text);

    try {
        if (!audioContextRef.current) {
            audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
        }
        if (audioContextRef.current.state === 'suspended') {
            await audioContextRef.current.resume();
        }

        const audioData = await generateSpeech(text);
        if (audioData) {
            const buffer = await audioContextRef.current.decodeAudioData(audioData);
            const source = audioContextRef.current.createBufferSource();
            source.buffer = buffer;
            source.connect(audioContextRef.current.destination);
            source.onended = () => {
                setIsPlayingAudio(false);
                setCurrentlyPlayingText(null);
            };
            source.start(0);
        } else {
             // Fallback to browser TTS if API fails/quota
             const utterance = new SpeechSynthesisUtterance(text);
             utterance.onend = () => {
                 setIsPlayingAudio(false);
                 setCurrentlyPlayingText(null);
             };
             window.speechSynthesis.speak(utterance);
        }
    } catch (e) {
        console.error("Audio playback error", e);
        setIsPlayingAudio(false);
        setCurrentlyPlayingText(null);
    }
  };

  // --- CORE ENGINE ---

  const handleScanSector = async () => {
    if (isScanning || isGenerating) return;
    setIsScanning(true);
    globalSoundEngine.playSFX('click');
    addEchoMessage(AgentName.RPGNexusAgent, "Scanning sector for stability variances...", "text-indigo-300");

    const prompt = `Generate 3 unique, evocative RPG locations for a sci-fi/fantasy setting with entropy level ${currentEntropy.toFixed(2)}.
    Output strictly as JSON. Keys are location names.
    Values must be objects with:
    - "description": string (1 sentence)
    - "color": string (Tailwind text class, e.g. "text-red-400")
    - "risk": string ("Low", "Medium", "High", "Extreme")
    - "icon": string (RemixIcon class, e.g. "ri-skull-line")`;

    try {
      const response = await invokeGemini(prompt, "You are a JSON generator. Do not include markdown formatting.");
      const locations = cleanAndParseJSON<Record<string, RPGScanResultLocation>>(response);
      setScanResults(locations || FALLBACK_LOCATIONS);

      if (isNarratorEnabled) playNarrativeAudio("Sector scan complete. Anomalies detected.");
    } catch (err) {
      setScanResults(FALLBACK_LOCATIONS);
    } finally {
      setIsScanning(false);
    }
  };

  const handleTravel = async (locationName: string, locationData: RPGScanResultLocation) => {
    setScanResults(null); 
    setIsProcessingTurn(true);
    setCurrentSceneVideoUrl(null); // Reset video on travel
    addEchoMessage(AgentName.RPGNexusAgent, `Vectoring to ${locationName}...`, "text-cyan-300");
    globalSoundEngine.playSFX('pulse');

    setGameState(prev => ({
      ...prev,
      currentLocation: locationName as RPGGameLocation,
      narrativeHistory: [...prev.narrativeHistory, { text: `Arrived at ${locationName}.`, type: 'action', timestamp: Date.now() }]
    }));

    try {
      const textPrompt = `You are the Game Master. The player has just arrived at "${locationName}" (${locationData.description}).
      Current Entropy: ${currentEntropy}.
      1. Write a vivid, 2-sentence sensory description of the scene.
      2. Provide 3 distinct actions the player can take (Explore, Talk, Analyze, Ritual, etc.).
      3. Create a short quest title related to this location.

      Return JSON:
      {
        "description": "...",
        "actions": [ { "id": "act_1", "label": "...", "type": "explore", "risk": 0.2 }, ... ],
        "quest": { "title": "...", "description": "...", "rewards": { "xp": 100, "flux": 50 } }
      }`;

      const textResponseRaw = await invokeGemini(textPrompt, "Return valid JSON only.");
      const textData = cleanAndParseJSON<any>(textResponseRaw);

      if (textData) {
        // Image Gen
        const imagePrompt = `Sci-fi fantasy concept art, ${locationName}, ${textData.description}, cinematic lighting, atmospheric, ${currentEntropy > 0.6 ? 'glitch, chaos, fractal' : 'clean, ethereal, serene'}.`;
        generateImage(imagePrompt).then(url => {
          if (url) {
            setGameState(prev => {
                const newHistoryEntry: RPGSceneData = {
                    imageUrl: url,
                    location: locationName as RPGGameLocation,
                    description: textData.description,
                    timestamp: Date.now()
                };
                return { 
                    ...prev, 
                    currentSceneImageUrl: url,
                    sceneHistory: [...(prev.sceneHistory || []), newHistoryEntry] 
                };
            });
          }
        });

        setGameState(prev => ({
          ...prev,
          currentSceneDescription: textData.description,
          availableActions: textData.actions || DEFAULT_ACTIONS,
          activeQuests: prev.activeQuests.length < 3 ? [...prev.activeQuests, { ...textData.quest, id: `quest-${Date.now()}`, status: 'active' }] : prev.activeQuests,
          narrativeHistory: [...prev.narrativeHistory, { text: textData.description, type: 'narration', timestamp: Date.now() }]
        }));

        if (isNarratorEnabled) playNarrativeAudio(textData.description);
      }
    } catch (e) {
      console.error("Travel generation failed", e);
      addEchoMessage(AgentName.System, "Navigational data corrupted. Using fallback protocols.", "text-rose-400");
    } finally {
      setIsProcessingTurn(false);
    }
  };

  const handleAction = async (actionLabel: string, risk: number = 0.5) => {
    if (isProcessingTurn) return;
    setIsProcessingTurn(true);
    setCustomActionInput(""); // Clear input if used
    globalSoundEngine.playSFX('click');

    setGameState(prev => ({
        ...prev,
        narrativeHistory: [...prev.narrativeHistory, { text: `> ${actionLabel}`, type: 'action', timestamp: Date.now() }]
    }));

    const prompt = `Game Master Logic:
    Location: ${gameState.currentLocation}
    Action Taken: "${actionLabel}"
    Entropy: ${currentEntropy}
    Profile: ${activeProfile?.name || "Seeker"} (${activeProfile?.race} ${activeProfile?.class})
    Current Scene: ${gameState.currentSceneDescription}

    Determine the outcome. 
    1. Write a 1-2 sentence narrative result.
    2. Define any stat changes (integrity/sanity/flux).
    3. PROVIDE 3 NEW Available Actions for the player based on the new situation.

    Return JSON:
    {
      "resultText": "...",
      "deltaIntegrity": -5, 
      "deltaSanity": 0,
      "deltaFlux": 10,
      "newActions": [ { "id": "new_1", "label": "...", "type": "explore", "risk": 0.2 }, ... ]
    }`;

    try {
        const response = await invokeGemini(prompt, "Return valid JSON only. Do not wrap in markdown.");
        const outcome = cleanAndParseJSON<any>(response);

        if (outcome) {
            const newIntegrity = Math.max(0, Math.min(100, (gameState.vitals?.integrity || 100) + (outcome.deltaIntegrity || 0)));
            const newSanity = Math.max(0, Math.min(100, (gameState.vitals?.sanity || 100) + (outcome.deltaSanity || 0)));

            setGameState(prev => ({
                ...prev,
                vitals: { integrity: newIntegrity, sanity: newSanity },
                availableActions: (outcome.newActions && outcome.newActions.length > 0) ? outcome.newActions : DEFAULT_ACTIONS,
                narrativeHistory: [...prev.narrativeHistory, { text: outcome.resultText, type: 'narration', timestamp: Date.now() }]
            }));

            if (outcome.deltaFlux && onUpdateProfile && activeProfile) {
                onUpdateProfile({ ...activeProfile, flux: activeProfile.flux + outcome.deltaFlux });
                addEchoMessage(AgentName.RPGNexusAgent, `Flux ${outcome.deltaFlux > 0 ? '+' : ''}${outcome.deltaFlux}`, outcome.deltaFlux > 0 ? 'text-amber-300' : 'text-rose-400');
            }
            if (risk > 0.5) onUpdateSystemMetrics(0.01, -0.01); 

            if (isNarratorEnabled) playNarrativeAudio(outcome.resultText);

        } else {
             setGameState(prev => ({
                ...prev,
                availableActions: DEFAULT_ACTIONS,
                narrativeHistory: [...prev.narrativeHistory, { text: "The ether churns, obscuring the outcome. (Data corruption)", type: 'system', timestamp: Date.now() }]
            }));
        }
    } catch (e) {
        addEchoMessage(AgentName.System, "Action resolution failed. Systems rebooting...", "text-rose-400");
        setGameState(prev => ({ ...prev, availableActions: DEFAULT_ACTIONS }));
    } finally {
        setIsProcessingTurn(false);
    }
  };

  // --- NEW FEATURES ---

  const handleGenerateSceneVideo = async () => {
      if (isAnimatingScene || !gameState.currentSceneImageUrl) return;
      setIsAnimatingScene(true);
      addEchoMessage(AgentName.RPGNexusAgent, "Animating scene via Veo-3.1...", "text-fuchsia-300");

      try {
          const prompt = `Cinematic subtle motion, atmospheric video of ${gameState.currentSceneDescription}. ${currentEntropy > 0.6 ? 'Glitch art style, disturbing movement.' : 'Serene, flowing motion.'}`;
          const videoUrl = await generateVideo(prompt, gameState.currentSceneImageUrl);
          if (videoUrl) {
              setCurrentSceneVideoUrl(videoUrl);
              addEchoMessage(AgentName.RPGNexusAgent, "Scene animation compiled.", "text-emerald-300");
          } else {
              throw new Error("No video URL returned.");
          }
      } catch (e) {
          console.error(e);
          addEchoMessage(AgentName.System, "Video generation failed.", "text-rose-400");
      } finally {
          setIsAnimatingScene(false);
      }
  };

  const handleCompileStoryVideo = async () => {
      if (isCompilingStory || !gameState.sceneHistory || gameState.sceneHistory.length === 0) {
          addEchoMessage(AgentName.System, "No scene history to compile.", "text-yellow-400");
          return;
      }

      setIsCompilingStory(true);
      setCompilationProgress(0);
      addEchoMessage(AgentName.RPGNexusAgent, "Compiling narrative history into Quest Cinema...", "text-amber-300");

      try {
          if (!cinemaEngineRef.current) {
              cinemaEngineRef.current = new QuestCinemaEngine();
          }

          const slides = gameState.sceneHistory.map(scene => ({
              imageUrl: scene.imageUrl,
              text: scene.description
          }));

          const blob = await cinemaEngineRef.current.compileVideo(
              slides,
              (progress) => setCompilationProgress(Math.round(progress * 100)),
              async (text) => await generateSpeech(text) 
          );

          if (blob) {
              const url = URL.createObjectURL(blob);
              const a = document.createElement('a');
              a.href = url;
              a.download = `Nexus_Story_${Date.now()}.webm`; // Or mp4 based on engine support
              document.body.appendChild(a);
              a.click();
              document.body.removeChild(a);
              addEchoMessage(AgentName.RPGNexusAgent, "Story Compilation Complete. Downloading...", "text-emerald-300");

              if (onArtifactCreated) {
                  onArtifactCreated({
                      id: `cinema-${Date.now()}`,
                      name: "Quest Cinema Log",
                      type: ArtifactType.VisualMemory,
                      rarity: ArtifactRarity.Rare,
                      description: "A compiled video log of your recent journey.",
                      imageUrl: gameState.currentSceneImageUrl || "", // Thumbnail
                      timestamp: Date.now()
                  });
              }
          }
      } catch (e) {
          console.error(e);
          addEchoMessage(AgentName.System, "Story compilation failed.", "text-rose-400");
      } finally {
          setIsCompilingStory(false);
          setCompilationProgress(0);
      }
  };

  const handleDownloadStory = () => {
      const storyText = gameState.narrativeHistory.map(n => `[${new Date(n.timestamp).toLocaleTimeString()}] ${n.type.toUpperCase()}: ${n.text}`).join('\n\n');
      const blob = new Blob([storyText], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `Nexus_Log_${Date.now()}.txt`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      addEchoMessage(AgentName.RPGNexusAgent, "Narrative log exported.", "text-cyan-300");
  };

  const handleReimagineScene = async () => {
      if (isProcessingTurn || !gameState.currentSceneDescription) return;
      setIsProcessingTurn(true);
      addEchoMessage(AgentName.RPGNexusAgent, "Re-imagining reality matrix...", "text-purple-300");

      try {
          const imagePrompt = `Sci-fi fantasy concept art, ${gameState.currentLocation}, ${gameState.currentSceneDescription}, cinematic lighting, atmospheric, ${activeProfile?.visualFilter || 'cyberpunk'} style, ${currentEntropy > 0.6 ? 'glitch, chaos, fractal' : 'clean, ethereal, serene'}.`;

          const url = await generateImage(imagePrompt);
          if (url) {
             setGameState(prev => ({ 
                  ...prev, 
                  currentSceneImageUrl: url,
                  sceneHistory: [...(prev.sceneHistory || []), {
                      imageUrl: url,
                      location: prev.currentLocation,
                      description: prev.currentSceneDescription || "Reimagined scene",
                      timestamp: Date.now()
                  }]
              }));
              setCurrentSceneVideoUrl(null); // Clear video if scene changes
              addEchoMessage(AgentName.RPGNexusAgent, "Visuals re-synthesized.", "text-emerald-300");
          }
      } catch (e) {
          addEchoMessage(AgentName.System, "Reimagine failed.", "text-rose-400");
      } finally {
          setIsProcessingTurn(false);
      }
  };


  // -- Renders --

  const renderInitialization = () => (
    <div className="flex flex-col items-center justify-center h-full p-6 animate-fade-in-up bg-slate-900/50 text-center">
      <div className="text-5xl text-indigo-500 mb-6 animate-pulse"><i className="ri-radar-line"></i></div>
      <h3 className="text-2xl font-cinzel text-indigo-300 mb-3">Campaign Initialization</h3>
      <p className="text-base text-slate-400 mb-8 max-w-lg leading-relaxed">
        The Nexus Engine requires an insertion vector. Scan the local entropy field to materialize potential timelines.
      </p>

      {scanResults ? (
         <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl">
            {Object.entries(scanResults).map(([name, dataRaw]) => {
                const data = dataRaw as RPGScanResultLocation;
                return (
                    <button 
                        key={name}
                        onClick={() => handleTravel(name, data)}
                        className="flex flex-col p-6 bg-slate-800/80 border-2 border-slate-600 rounded-xl hover:bg-slate-700 hover:border-cyan-500 hover:shadow-2xl hover:shadow-cyan-500/20 transition-all group text-left transform hover:-translate-y-1"
                    >
                        <div className="flex items-center justify-between mb-4 w-full">
                            <i className={`${data.icon || 'ri-map-pin-line'} text-3xl ${data.color || 'text-slate-200'}`}></i>
                            <span className="text-xs uppercase font-bold tracking-wider bg-slate-900 px-3 py-1 rounded text-slate-400 group-hover:text-white transition-colors">{data.risk} Risk</span>
                        </div>
                        <h4 className="font-cinzel font-bold text-xl text-slate-200 group-hover:text-cyan-300 mb-2">{name}</h4>
                        <p className="text-sm text-slate-400 font-cormorant leading-relaxed">{data.description}</p>
                    </button>
                );
            })}
         </div>
      ) : (
        <Button onClick={handleScanSector} disabled={isScanning} className="px-10 py-4 text-base tracking-widest bg-indigo-600 hover:bg-indigo-500 shadow-xl shadow-indigo-500/20 font-bold">
            {isScanning ? <><i className="ri-loader-4-line animate-spin mr-3"></i>SCANNING SECTOR...</> : <><i className="ri-search-eye-line mr-3"></i>SCAN FOR ANOMALIES</>}
        </Button>
      )}
    </div>
  );

  const renderGameInterface = () => (
    <div className="relative h-full w-full overflow-hidden bg-slate-950 font-sans flex flex-col">
        {/* BACKGROUND LAYER */}
        <div className="absolute inset-0 z-0">
            {currentSceneVideoUrl ? (
                <video src={currentSceneVideoUrl} autoPlay loop muted className="w-full h-full object-cover" />
            ) : gameState.currentSceneImageUrl ? (
                <img src={gameState.currentSceneImageUrl} alt="Scene" className="w-full h-full object-cover transition-opacity duration-1000 ease-in-out" />
            ) : (
                 <div className="w-full h-full bg-slate-900 flex items-center justify-center">
                    <div className="text-slate-700 animate-pulse text-6xl"><i className="ri-image-line"></i></div>
                 </div>
            )}
            {/* VIGNETTE & GRADIENT OVERLAY */}
            <div className="absolute inset-0 bg-gradient-to-b from-slate-950/90 via-slate-950/20 to-slate-950/90 pointer-events-none"></div>
            <div className="absolute inset-0 bg-black/30 pointer-events-none"></div> 
        </div>

        {/* CONTENT LAYER */}
        <div className="relative z-10 flex flex-col h-full p-2 md:p-4 pointer-events-none overflow-hidden"> 

            {/* TOP BAR: Stats & Controls */}
            <div className="flex flex-wrap justify-between items-start gap-2 mb-2 pointer-events-auto shrink-0">
                 <div className="bg-slate-950/70 backdrop-blur-md border border-slate-700/50 rounded-lg p-3 shadow-lg flex-grow max-w-full md:max-w-md">
                    <h3 className="text-indigo-300 font-bold text-lg font-cinzel flex items-center gap-2 truncate">
                        <i className="ri-map-pin-user-fill"></i> {gameState.currentLocation}
                    </h3>
                    <div className="flex flex-wrap items-center gap-4 mt-2 text-xs font-mono text-slate-300">
                         <div className="flex items-center gap-1" title="Integrity"><i className="ri-heart-pulse-fill text-rose-500"></i> {gameState.vitals?.integrity}%</div>
                         <div className="flex items-center gap-1" title="Sanity"><i className="ri-brain-fill text-purple-400"></i> {gameState.vitals?.sanity}%</div>
                         <div className="flex items-center gap-1" title="Flux"><i className="ri-copper-coin-line text-amber-400"></i> {activeProfile?.flux || 0}</div>
                    </div>
                 </div>

                 {/* VISUAL & AUDIO CONTROLS */}
                 <div className="flex gap-2 shrink-0">
                    <button
                        onClick={() => setIsNarratorEnabled(!isNarratorEnabled)}
                        className={`bg-slate-950/70 backdrop-blur-md p-3 rounded-lg border transition-all ${isNarratorEnabled ? 'border-emerald-500 text-emerald-400' : 'border-slate-600/50 text-slate-400 hover:text-white'}`}
                        title={isNarratorEnabled ? "Disable Narrator" : "Enable Narrator Mode"}
                    >
                        <i className={`ri-volume-${isNarratorEnabled ? 'up' : 'mute'}-line text-lg`}></i>
                    </button>
                    <button 
                        onClick={handleReimagineScene}
                        disabled={isProcessingTurn}
                        className="bg-slate-950/70 hover:bg-purple-900/60 backdrop-blur-md text-white p-3 rounded-lg border border-slate-600/50 transition-all"
                        title="Reimagine Scene"
                    >
                        <i className={`ri-refresh-line text-lg ${isProcessingTurn ? 'animate-spin' : ''}`}></i>
                    </button>
                    <button 
                        onClick={handleGenerateSceneVideo}
                        disabled={isAnimatingScene || !!currentSceneVideoUrl}
                        className="bg-slate-950/70 hover:bg-fuchsia-900/60 backdrop-blur-md text-white p-3 rounded-lg border border-slate-600/50 transition-all"
                        title="Animate Scene"
                    >
                        {isAnimatingScene ? <i className="ri-loader-4-line animate-spin text-lg"></i> : <i className="ri-movie-line text-lg"></i>}
                    </button>
                 </div>
            </div>

            {/* MIDDLE AREA - Responsive Grid/Flex */}
            <div className="flex-grow flex flex-col lg:flex-row gap-4 min-h-0 overflow-hidden">

                {/* ACTIONS DECK (Desktop: Left, Mobile: Bottom Order 2) */}
                <div className="lg:w-1/3 order-2 lg:order-1 flex flex-col gap-2 pointer-events-auto min-h-0 shrink-0">
                     {/* Custom Input */}
                    <div className="flex gap-2 mb-1 bg-slate-950/80 p-2 rounded-lg border border-slate-700/50 backdrop-blur-sm shrink-0">
                        <input 
                            type="text" 
                            value={customActionInput}
                            onChange={(e) => setCustomActionInput(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleAction(customActionInput)}
                            placeholder="What do you do?"
                            className="flex-grow bg-transparent border-none text-sm md:text-base text-slate-100 placeholder-slate-500 focus:ring-0 min-w-0"
                            disabled={isProcessingTurn}
                        />
                        <button 
                            onClick={() => handleAction(customActionInput)}
                            disabled={isProcessingTurn || !customActionInput.trim()}
                            className="text-indigo-400 hover:text-indigo-300 px-2"
                        >
                            <i className="ri-send-plane-fill text-xl"></i>
                        </button>
                    </div>

                    {/* Action Buttons List */}
                    <div className="flex flex-col gap-2 overflow-y-auto custom-scrollbar-thin pr-1 pb-1 flex-grow lg:flex-grow-0 lg:max-h-full max-h-[150px] md:max-h-[200px]">
                        {gameState.availableActions?.map((action, idx) => {
                             const riskBorderClass = getRiskColor(action.risk);
                             let btnBg = "bg-slate-900/80 hover:bg-slate-800/90";
                             let borderColor = "border-slate-600";
                             if(action.risk > 0.6) { borderColor = "border-rose-500/50"; btnBg = "bg-rose-950/70 hover:bg-rose-900/80"; }
                             else if(action.risk > 0.3) { borderColor = "border-amber-500/50"; btnBg = "bg-amber-950/70 hover:bg-amber-900/80"; }
                             else { borderColor = "border-emerald-500/50"; btnBg = "bg-emerald-950/70 hover:bg-emerald-900/80"; }

                             return (
                                <button
                                    key={idx}
                                    onClick={() => handleAction(action.label, action.risk)}
                                    disabled={isProcessingTurn}
                                    className={`w-full text-left p-3 md:p-4 rounded-lg border ${borderColor} ${btnBg} backdrop-blur-sm transition-all group flex justify-between items-center shrink-0 shadow-lg`}
                                >
                                    <span className="text-sm md:text-base font-semibold text-slate-100 group-hover:text-white shadow-black drop-shadow-md">{action.label}</span>
                                    <span className={`text-[10px] uppercase opacity-70 font-mono bg-black/30 px-2 py-0.5 rounded`}>{action.type}</span>
                                </button>
                            );
                        })}
                    </div>
                </div>

                {/* NARRATIVE LOG (Desktop: Right, Mobile: Top Order 1) */}
                <div className="lg:w-2/3 order-1 lg:order-2 pointer-events-auto flex flex-col min-h-0 h-full">
                     <div className="bg-slate-950/80 backdrop-blur-md border border-slate-700/50 rounded-lg p-4 overflow-y-auto custom-scrollbar flex-grow shadow-2xl relative">
                        {gameState.narrativeHistory.slice(-10).map((entry, i) => ( 
                            <div key={i} className={`mb-3 last:mb-0 text-sm md:text-base leading-relaxed relative pr-8 group/entry ${entry.type === 'action' ? 'text-indigo-300 font-bold' : 'text-slate-300 font-cormorant'}`}>
                                {entry.type === 'action' && <span className="mr-2 opacity-50">></span>}
                                {entry.text}
                                <button 
                                    onClick={() => playNarrativeAudio(entry.text)}
                                    className={`absolute top-0 right-0 text-slate-500 hover:text-emerald-400 p-1 opacity-0 group-hover/entry:opacity-100 transition-opacity ${isPlayingAudio && currentlyPlayingText === entry.text ? 'text-emerald-400 opacity-100 animate-pulse' : ''}`}
                                    title="Play Audio"
                                    aria-label="Play narrative audio"
                                >
                                    <i className={`ri-${isPlayingAudio && currentlyPlayingText === entry.text ? 'volume-up' : 'play-circle'}-line text-lg`}></i>
                                </button>
                            </div>
                        ))}
                        <div ref={chatEndRef} />

                        {isProcessingTurn && (
                            <div className="flex items-center gap-2 text-indigo-400 animate-pulse mt-4 p-2 bg-indigo-900/20 rounded border border-indigo-500/30">
                                <i className="ri-quill-pen-line"></i> 
                                <span className="text-xs font-mono">The Game Master weaves the fate...</span>
                            </div>
                        )}

                        {/* Audio Status */}
                        {isPlayingAudio && (
                             <div className="sticky bottom-0 right-0 ml-auto w-fit mt-2 bg-black/80 backdrop-blur px-3 py-1 rounded-full text-[10px] text-emerald-400 flex items-center gap-2 border border-emerald-500/30 shadow-lg z-10">
                                 <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-ping"></span>
                                 Speaking...
                             </div>
                        )}
                     </div>

                     {/* Meta Controls (Footer of Log) */}
                     <div className="flex flex-wrap gap-2 justify-end mt-2 shrink-0">
                        <Button onClick={handleCompileStoryVideo} disabled={isCompilingStory || !gameState.sceneHistory?.length} className="text-[10px] py-2 bg-amber-700/80 hover:bg-amber-600/80 backdrop-blur-sm border border-amber-600/50">
                            {isCompilingStory ? `Compiling ${compilationProgress}%` : <><i className="ri-movie-2-line mr-1"></i> Story Movie</>}
                        </Button>
                        <Button onClick={handleDownloadStory} className="text-[10px] py-2 bg-cyan-700/80 hover:bg-cyan-600/80 backdrop-blur-sm border border-cyan-600/50">
                            <i className="ri-file-text-line mr-1"></i> Log
                        </Button>
                        <Button onClick={() => handleScanSector()} className="text-[10px] py-2 bg-indigo-700/80 hover:bg-indigo-600/80 backdrop-blur-sm border border-indigo-600/50">
                             <i className="ri-radar-line mr-1"></i> Rescan
                        </Button>
                     </div>
                </div>
            </div>
        </div>
    </div>
  );

  return (
    <div className="rpg-nexus-panel bg-slate-950 backdrop-blur-xl border border-indigo-600/50 rounded-xl shadow-2xl flex flex-col overflow-hidden transition-all duration-500 font-sans" style={{ width: width || '100%', height: height || '600px' }}>
      {/* Universal Header */}
      <div className="p-4 border-b border-indigo-800/50 bg-slate-900 flex justify-between items-center shrink-0 shadow-md z-20">
        <h3 className="text-xl font-cinzel font-bold text-indigo-300 flex items-center">
            <span className="bg-indigo-900/30 p-1.5 rounded-lg mr-3 border border-indigo-500/30"><i className="ri-gamepad-line text-indigo-400"></i></span>
            Nexus Engine
        </h3>
        {scanResults && (
             <button onClick={() => setScanResults(null)} className="text-xs font-bold text-slate-400 hover:text-white bg-slate-800 hover:bg-slate-700 px-3 py-1.5 rounded-lg transition-colors border border-slate-700">
                 <i className="ri-arrow-go-back-line mr-1"></i>Back to Game
             </button>
        )}
      </div>

      {/* Content Switcher */}
      <div className="flex-grow overflow-hidden relative">
          {(!scanResults && gameState.currentLocation === 'The Void Edge' && gameState.narrativeHistory.length <= 1) 
            ? renderInitialization() 
            : (scanResults ? renderInitialization() : renderGameInterface())
          }
      </div>
    </div>
  );
};

export default RPGNexusPanel;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import type { SeekerProfileWeaverPanelProps, SeekerProfile, MarketItem } from '../../types';
import { 
