  SeekerAvatarType, 
  SeekerClass, 
  SeekerGender, 
  SeekerEnergyAlignment, 
  SeekerAuraColor, 
  SeekerVisualFilter,
  ArtifactRarity,
  AgentRace 
} from '../../types';
import { 
  SEEKER_CLASSES, 
  ALL_GENDERS_LIST, 
  ALL_ALIGNMENTS_LIST, 
  SEEKER_AURA_OPTIONS, 
  SEEKER_VISUAL_FILTERS, 
  TRAIT_LISTS,
  AVATAR_RACES
} from '../../constants';
import { Button } from '../ui/Button';
import { useGemini } from '../../context/GeminiIntegrationContext';
import html2canvas from 'html2canvas';

// --- Random Name Generator ---
const NAME_PREFIXES = ["Xyl", "Chron", "Vor", "Zyn", "Kael", "Thal", "Om", "Lyra", "Vex", "Ser", "Dra", "Myr", "Pyr", "Cyp", "Nek", "Sol", "Zen", "Rin", "Kys", "Tor", "Ael", "Fen", "Grim"];
const NAME_SUFFIXES = ["os", "ia", "ex", "on", "is", "us", "ar", "or", "a", "yn", "ix", "um", "ra", "th", "en", "ir", "ae", "io", "ak", "ul"];

const generateRandomName = () => {
    const prefix = NAME_PREFIXES[Math.floor(Math.random() * NAME_PREFIXES.length)];
    const suffix = NAME_SUFFIXES[Math.floor(Math.random() * NAME_SUFFIXES.length)];
    return prefix + suffix;
};

// Helper function to get icon for card type
const getCardTypeIcon = (type: string): string => {
    switch (type) {
        case 'Creature': return 'ri-aliens-line';
        case 'NPC': return 'ri-user-star-line';
        case 'Boss': return 'ri-skull-2-line';
        case 'Location': return 'ri-map-pin-range-line';
        case 'Weapon': return 'ri-sword-line';
        case 'Companion': return 'ri-bear-smile-line';
        case 'Environment': return 'ri-landscape-line';
        case 'Relic': return 'ri-vip-diamond-line';
        case 'Consumable': return 'ri-flask-line';
        case 'Vehicle': return 'ri-rocket-line';
        case 'Augmentation': return 'ri-cpu-line';
        case 'Skin': return 'ri-t-shirt-line';
        case 'Mount': return 'ri-riding-line';
        case 'Dwelling': return 'ri-home-heart-line';
        case 'Skill': return 'ri-book-open-line';
        case 'Material': return 'ri-stack-line';
        case 'Service': return 'ri-service-line';
        case 'Collectible': return 'ri-trophy-line';
        case 'Fashion': return 'ri-shirt-line';
        case 'Food': return 'ri-restaurant-line';
        case 'Pet': return 'ri-bear-smile-line'; // Reuse
        case 'Music': return 'ri-music-line';
        case 'Tool': return 'ri-hammer-line';
        case 'Planet': return 'ri-earth-line';
        case 'Secret': return 'ri-eye-off-line';
        case 'Element': return 'ri-fire-line';
        case 'Cursed': return 'ri-skull-line';
        case 'Festival': return 'ri-flag-line';
        default: return 'ri-apps-2-line';
    }
}

// TCG Card Component
const TCGCard: React.FC<{ 
    name: string, 
    type: string, 
    rarity: ArtifactRarity, 
    imageUrl?: string, 
    description?: string, 
    stats?: { atk: number, def: number, res: number },
    auraColor?: string,
    id?: string,
    isZoomed?: boolean
}> = ({ name, type, rarity, imageUrl, description, stats, auraColor, id, isZoomed = false }) => {
    const rarityColors = {
        [ArtifactRarity.Common]: 'border-slate-500 bg-slate-900',
        [ArtifactRarity.Uncommon]: 'border-emerald-500 bg-emerald-950',
        [ArtifactRarity.Rare]: 'border-blue-500 bg-blue-950',
        [ArtifactRarity.Legendary]: 'border-amber-500 bg-amber-950',
        [ArtifactRarity.Mythic]: 'border-fuchsia-500 bg-fuchsia-950',
        [ArtifactRarity.Anomalous]: 'border-rose-600 bg-rose-950',
    };

    const borderColor = rarityColors[rarity] || rarityColors[ArtifactRarity.Common];
    const auraHex = auraColor ? SEEKER_AURA_OPTIONS.find(a=>a.id === auraColor)?.hex : 'transparent';

    return (
        <div 
            id={id} 
            className={`relative rounded-xl border-[8px] ${borderColor} flex flex-col overflow-hidden shadow-2xl transition-transform duration-300 ${isZoomed ? 'scale-105' : ''}`}
            style={{ 
                aspectRatio: '2.5/3.5',
                boxShadow: auraColor ? `0 0 30px ${auraHex}60` : 'none'
            }}
        >
            {/* Holographic Overlay */}
            <div className="absolute inset-0 pointer-events-none z-20 bg-gradient-to-tr from-transparent via-white/10 to-transparent opacity-30 mix-blend-overlay" />

            {/* Header - Semi Transparent Glass (High Transparency) */}
            <div className="bg-black/10 backdrop-blur-sm p-4 flex justify-between items-center border-b border-white/10 z-10 relative">
                <span className="font-cinzel font-bold text-white text-lg md:text-xl truncate drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)]">{name}</span>
                <div className="flex gap-1">
                    <div className="w-4 h-4 rounded-full bg-current opacity-90 shadow-[0_0_8px_currentColor]" style={{color: auraHex}}></div>
                </div>
            </div>

            {/* Image Area */}
            <div className="absolute inset-0 z-0 bg-black">
                 {/* Image covers full card background for immersive feel, layout overlays it */}
                {imageUrl ? (
                    <img src={imageUrl} alt={name} className="w-full h-full object-cover" />
                ) : (
                    <div className="w-full h-full flex items-center justify-center text-slate-600">
                        <i className={`${getCardTypeIcon(type)} text-8xl opacity-30`}></i>
                    </div>
                )}
                 {/* Inner Frame */}
                 <div className="absolute inset-3 border border-white/20 rounded-lg opacity-40 pointer-events-none"></div>
            </div>

            {/* Spacer to push content down */}
            <div className="flex-1 z-10"></div>

            {/* Info Bar - Glass */}
            <div className="bg-slate-900/30 backdrop-blur-md p-2 flex justify-between items-center border-t border-b border-white/10 z-10 relative">
                <span className="text-[10px] uppercase tracking-wider text-slate-100 font-bold drop-shadow-md">{type}</span>
                <span className={`text-[9px] uppercase font-bold px-2 py-0.5 rounded shadow-sm ${rarity === 'Legendary' ? 'text-amber-100 bg-amber-900/60 border border-amber-500/30' : 'text-slate-200 bg-slate-800/60'}`}>{rarity}</span>
            </div>

            {/* Text Box - High Transparency Glass */}
            <div className="h-[28%] bg-slate-950/40 backdrop-blur-md p-4 text-sm text-slate-100 font-cormorant italic leading-snug overflow-hidden relative z-10 border-t border-white/5 text-shadow-sm">
                {description || "No data available."}
            </div>

            {/* Footer Stats */}
            {stats && (
                <div className="bg-black/60 backdrop-blur-md p-2 flex justify-around items-center border-t border-white/10 z-10 relative text-sm font-mono font-bold tracking-wider">
                    <div className="flex items-center text-red-400 drop-shadow-md"><i className="ri-sword-fill mr-1.5"></i>{stats.atk}</div>
                    <div className="flex items-center text-blue-400 drop-shadow-md"><i className="ri-shield-fill mr-1.5"></i>{stats.def}</div>
                    <div className="flex items-center text-purple-400 drop-shadow-md"><i className="ri-flashlight-fill mr-1.5"></i>{stats.res}</div>
                </div>
            )}
        </div>
    );
};

const SeekerProfileWeaverPanel: React.FC<SeekerProfileWeaverPanelProps> = ({
  addEchoMessage,
  onProfileCreated,
  existingProfile,
  onUpdateProfile,
  width,
  height
}) => {
  const [name, setName] = useState(existingProfile?.name || '');
  const [race, setRace] = useState<SeekerAvatarType>(existingProfile?.race || SeekerAvatarType.Human);
  const [seekerClass, setSeekerClass] = useState<SeekerClass>(existingProfile?.class || SeekerClass.Gatewalker);
  const [gender, setGender] = useState<SeekerGender>(existingProfile?.gender || SeekerGender.NonBinary);
  const [alignment, setAlignment] = useState<SeekerEnergyAlignment>(existingProfile?.energyAlignment || SeekerEnergyAlignment.Harmonic);
  const [aura, setAura] = useState<SeekerAuraColor>(existingProfile?.auraColor || SeekerAuraColor.Azure);
  const [visualFilter, setVisualFilter] = useState<SeekerVisualFilter>(existingProfile?.visualFilter || SeekerVisualFilter.Cyberpunk);

  const [avatarUrl, setAvatarUrl] = useState<string | undefined>(existingProfile?.avatarImageUrl);
  const [isGeneratingAvatar, setIsGeneratingAvatar] = useState(false);
  const [isWeavingBio, setIsWeavingBio] = useState(false); // New state for bio generation

  const [activeTab, setActiveTab] = useState<'profile' | 'grimoire'>('profile');

  const { generateImage, invokeGemini } = useGemini();

  // Update local state if existingProfile changes externally
  useEffect(() => {
    if (existingProfile) {
      setName(existingProfile.name);
      setRace(existingProfile.race);
      if (existingProfile.class) setSeekerClass(existingProfile.class);
      setGender(existingProfile.gender);
      setAlignment(existingProfile.energyAlignment);
      if (existingProfile.auraColor) setAura(existingProfile.auraColor);
      if (existingProfile.visualFilter) setVisualFilter(existingProfile.visualFilter);
      if (existingProfile.avatarImageUrl) setAvatarUrl(existingProfile.avatarImageUrl);
    }
  }, [existingProfile]);

  const handleRandomizeProfile = () => {
      setName(generateRandomName());
      setRace(AVATAR_RACES[Math.floor(Math.random() * AVATAR_RACES.length)].id as SeekerAvatarType);
      setSeekerClass(SEEKER_CLASSES[Math.floor(Math.random() * SEEKER_CLASSES.length)].id as SeekerClass);
      setGender(ALL_GENDERS_LIST[Math.floor(Math.random() * ALL_GENDERS_LIST.length)]);
      setAlignment(ALL_ALIGNMENTS_LIST[Math.floor(Math.random() * ALL_ALIGNMENTS_LIST.length)]);
      setAura(SEEKER_AURA_OPTIONS[Math.floor(Math.random() * SEEKER_AURA_OPTIONS.length)].id as SeekerAuraColor);
      setVisualFilter(SEEKER_VISUAL_FILTERS[Math.floor(Math.random() * SEEKER_VISUAL_FILTERS.length)].id as SeekerVisualFilter);
      addEchoMessage(AgentName.System, "Randomized Identity Parameters.", "text-cyan-300");
  };

  const handleGenerateAvatar = async () => {
      if (isGeneratingAvatar || !name || !race || !seekerClass) {
          if(!name) addEchoMessage(AgentName.System, "Name required for avatar generation.", "text-yellow-400");
          return;
      }

      setIsGeneratingAvatar(true);
      addEchoMessage(AgentName.SeekerProfileWeaverAgent, "Weaving visual avatar...", "text-indigo-300");

      const equipStr = existingProfile 
        ? `Wearing ${existingProfile.equippedOutfit?.name || 'standard gear'}, Wielding ${existingProfile.equippedWeapon?.name || 'basic weapon'}.`
        : '';

      const prompt = `Portrait of a ${gender} ${race} ${seekerClass}, sci-fi fantasy style, detailed, glowing ${aura} aura, ${visualFilter} aesthetic. Character name: ${name}. ${equipStr}`;

      try {
          const url = await generateImage(prompt, 'gemini-2.5-flash-image');
          if (url) {
              setAvatarUrl(url);
              addEchoMessage(AgentName.SeekerProfileWeaverAgent, "Avatar manifested.", "text-emerald-300");
          } else {
              addEchoMessage(AgentName.System, "Avatar generation failed.", "text-rose-400");
          }
      } catch (e) {
          console.error(e);
          addEchoMessage(AgentName.System, "Error generating avatar.", "text-rose-400");
      } finally {
          setIsGeneratingAvatar(false);
      }
  };

  const handleCreateOrUpdate = async () => {
    if (!name.trim()) {
        addEchoMessage(AgentName.System, "Identity requires a name.", "text-rose-400");
        return;
    }

    const selfTraits = existingProfile?.selfTraits || [
        TRAIT_LISTS.self[Math.floor(Math.random() * TRAIT_LISTS.self.length)],
        TRAIT_LISTS.self[Math.floor(Math.random() * TRAIT_LISTS.self.length)]
    ];

    const codexTraits = existingProfile?.codexTraits || [
        TRAIT_LISTS.codex[Math.floor(Math.random() * TRAIT_LISTS.codex.length)]
    ];

    // Auto-generate bio if it doesn't exist or is empty
    let bio = existingProfile?.bio || "";
    if (!bio && !isWeavingBio) {
        setIsWeavingBio(true);
        addEchoMessage(AgentName.SeekerProfileWeaverAgent, "Weaving legendary biography...", "text-fuchsia-300");
        try {
            const bioPrompt = `Write a 2-sentence epic, mystical, sci-fi fantasy backstory for a ${gender} ${race} ${seekerClass} named ${name} with ${alignment} alignment. Mention a lost artifact or cosmic event. Tone: Mysterious, Legendary.`;
            const generatedBio = await invokeGemini(bioPrompt, "You are a master storyteller for a cosmic RPG.");
            if (generatedBio) {
                bio = generatedBio;
                addEchoMessage(AgentName.SeekerProfileWeaverAgent, "Biography inscribed.", "text-emerald-300");
            }
        } catch (e) {
            console.warn("Bio generation failed", e);
        } finally {
            setIsWeavingBio(false);
        }
    }

    // Preserving all existing fields using spread, then overwriting with new form data
    const newProfile: SeekerProfile = {
        ...(existingProfile || {
            generatedAt: Date.now(),
            level: 1,
            experience: 0,
            flux: 100,
            inventory: [],
            selfTraits: [],
            codexTraits: []
        }),
        name,
        race,
        class: seekerClass,
        gender,
        energyAlignment: alignment,
        auraColor: aura,
        visualFilter,
        selfTraits: Array.from(new Set(selfTraits)),
        codexTraits: Array.from(new Set(codexTraits)),
        avatarImageUrl: avatarUrl,
        bio: bio // Add bio to profile
    };

    if (existingProfile && onUpdateProfile) {
        onUpdateProfile(newProfile);
        addEchoMessage(AgentName.SeekerProfileWeaverAgent, `Profile updated for ${name}.`, "text-emerald-300");
    } else if (onProfileCreated) {
        onProfileCreated(newProfile);
        addEchoMessage(AgentName.SeekerProfileWeaverAgent, `Identity woven: ${name} (${race} ${seekerClass}).`, "text-cyan-300");
    }
  };

  const handleDownloadCard = () => {
      const cardElement = document.getElementById('seeker-tcg-card');
      if (cardElement) {
          html2canvas(cardElement, {
              backgroundColor: null,
              scale: 2, 
              useCORS: true
          }).then(canvas => {
              const link = document.createElement('a');
              link.download = `TCG_Card_${name.replace(/\s+/g, '_')}.png`;
              link.href = canvas.toDataURL('image/png');
              link.click();
              addEchoMessage(AgentName.SeekerProfileWeaverAgent, "TCG Identity Card materialized.", "text-emerald-300");
          }).catch(err => {
              console.error("Card capture failed:", err);
              addEchoMessage(AgentName.System, "Card capture failed.", "text-rose-400");
          });
      }
  };

  const inventoryGroups = useMemo(() => {
    if (!existingProfile) return {};
    const groups: Record<string, MarketItem[]> = {};
    existingProfile.inventory.forEach(item => {
        const type = item.type; 
        if (!groups[type]) groups[type] = [];
        groups[type].push(item);
    });
    return groups;
  }, [existingProfile]);

  const seekerStats = existingProfile ? {
      atk: Math.floor(existingProfile.level * 10 + (existingProfile.flux / 100)),
      def: Math.floor(existingProfile.level * 8 + (existingProfile.inventory.length * 2)),
      res: Math.floor(existingProfile.level * 12 + 5)
  } : { atk: 10, def: 10, res: 10 };

  return (
    <div 
        className="seeker-profile-weaver-panel bg-slate-950/90 backdrop-blur-xl border border-indigo-600/50 rounded-xl shadow-2xl flex flex-col my-4 overflow-hidden" 
        style={{ width: width ? (typeof width === 'number' ? `${width}px` : width) : '100%', height: height ? (typeof height === 'number' ? `${height}px` : height) : '500px' }}
    >
      <div className="p-4 border-b border-indigo-800/50 bg-slate-900/50 flex justify-between items-center shrink-0">
        <h3 className="text-xl font-cinzel font-bold text-indigo-300 flex items-center">
            <i className="ri-user-6-line mr-2"></i>Seeker Identity Loom
        </h3>
        {existingProfile && (
            <div className="flex gap-2">
                <button 
                    onClick={() => setActiveTab('profile')}
                    className={`px-3 py-1 rounded text-xs font-bold transition-colors ${activeTab === 'profile' ? 'bg-indigo-600 text-white' : 'bg-slate-800 text-slate-400 hover:text-white'}`}
                >
                    Profile
                </button>
                 <button 
                    onClick={() => setActiveTab('grimoire')}
                    className={`px-3 py-1 rounded text-xs font-bold transition-colors ${activeTab === 'grimoire' ? 'bg-indigo-600 text-white' : 'bg-slate-800 text-slate-400 hover:text-white'}`}
                >
                    Grimoire ({existingProfile.inventory.length})
                </button>
            </div>
        )}
      </div>

      <div className="flex-grow overflow-hidden flex flex-col relative">
        {activeTab === 'profile' && (
            <div className="p-6 overflow-y-auto custom-scrollbar space-y-6">

                {/* TCG CARD DISPLAY AREA */}
                <div className="flex flex-col xl:flex-row gap-8 items-center xl:items-start">
                    {/* The Rendered Card - Made Larger */}
                    <div className="w-full max-w-sm md:w-[420px] flex-shrink-0 relative group mx-auto xl:mx-0">
                         <TCGCard 
                            id="seeker-tcg-card"
                            name={name || "Unknown Seeker"}
                            type={`${race} ${seekerClass}`}
                            rarity={ArtifactRarity.Legendary}
                            imageUrl={avatarUrl}
                            description={existingProfile?.bio || `A ${alignment} ${race} wandering the Codex. ${existingProfile?.selfTraits.join(', ') || ''}`}
                            stats={seekerStats}
                            auraColor={aura}
                            isZoomed
                         />
                         <div className="mt-4 flex gap-3 justify-center">
                            <Button onClick={handleGenerateAvatar} disabled={isGeneratingAvatar} className="text-xs py-2 px-4 bg-indigo-700 hover:bg-indigo-600 w-full shadow-lg">
                                {isGeneratingAvatar ? <i className="ri-loader-4-line animate-spin"></i> : <i className="ri-magic-line mr-2"></i>} 
                                Generate Art
                            </Button>
                             <Button onClick={handleDownloadCard} disabled={!avatarUrl} className="text-xs py-2 px-4 bg-slate-700 hover:bg-slate-600 w-full shadow-lg">
                                <i className="ri-download-line mr-2"></i> Save Card
                            </Button>
                         </div>
                    </div>

                    {/* Editor Form */}
                    <div className="flex-grow w-full space-y-5 bg-slate-900/50 p-6 rounded-xl border border-slate-700/50">
                        <div className="grid grid-cols-1 gap-5">
                             <div className="space-y-1.5">
                                <label className="text-xs text-indigo-300 font-bold uppercase tracking-wider">Designation (Name)</label>
                                <div className="flex gap-2">
                                    <input 
                                        type="text" 
                                        value={name} 
                                        onChange={e => setName(e.target.value)} 
                                        className="flex-grow bg-slate-800 border border-slate-600 rounded-lg p-3 text-slate-100 focus:border-indigo-400 focus:ring-2 focus:ring-indigo-500/50 outline-none transition-all placeholder-slate-500"
                                        placeholder="Enter Seeker Name..."
                                    />
                                    <button 
                                        onClick={handleRandomizeProfile}
                                        className="px-4 bg-slate-800 border border-slate-600 rounded-lg hover:bg-indigo-900/50 hover:border-indigo-500 text-indigo-400 hover:text-indigo-200 transition-all shadow-sm group"
                                        title="Randomize Complete Identity"
                                    >
                                        <i className="ri-dice-fill text-xl group-hover:animate-spin-slow"></i>
                                    </button>
                                </div>
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                                <div className="space-y-1.5">
                                    <label className="text-xs text-indigo-300 font-bold uppercase tracking-wider">Biomorph (Race)</label>
                                    <select 
                                        value={race} 
                                        onChange={e => setRace(e.target.value as SeekerAvatarType)}
                                        className="w-full bg-slate-800 border border-slate-600 rounded-lg p-3 text-slate-100 focus:border-indigo-400 focus:ring-2 focus:ring-indigo-500/50 outline-none transition-all"
                                    >
                                        {AVATAR_RACES.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-xs text-indigo-300 font-bold uppercase tracking-wider">Archetype (Class)</label>
                                     <select 
                                        value={seekerClass} 
                                        onChange={e => setSeekerClass(e.target.value as SeekerClass)}
                                        className="w-full bg-slate-800 border border-slate-600 rounded-lg p-3 text-slate-100 focus:border-indigo-400 focus:ring-2 focus:ring-indigo-500/50 outline-none transition-all"
                                    >
                                        {SEEKER_CLASSES.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                                    </select>
                                </div>
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                                <div className="space-y-1.5">
                                    <label className="text-xs text-indigo-300 font-bold uppercase tracking-wider">Gender</label>
                                     <select 
                                        value={gender} 
                                        onChange={e => setGender(e.target.value as SeekerGender)}
                                        className="w-full bg-slate-800 border border-slate-600 rounded-lg p-3 text-slate-100 focus:border-indigo-400 focus:ring-2 focus:ring-indigo-500/50 outline-none transition-all"
                                    >
                                        {ALL_GENDERS_LIST.map(g => <option key={g} value={g}>{g}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-xs text-indigo-300 font-bold uppercase tracking-wider">Alignment</label>
                                     <select 
                                        value={alignment} 
                                        onChange={e => setAlignment(e.target.value as SeekerEnergyAlignment)}
                                        className="w-full bg-slate-800 border border-slate-600 rounded-lg p-3 text-slate-100 focus:border-indigo-400 focus:ring-2 focus:ring-indigo-500/50 outline-none transition-all"
                                    >
                                        {ALL_ALIGNMENTS_LIST.map(a => <option key={a} value={a}>{a}</option>)}
                                    </select>
                                </div>
                            </div>

                             <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                                <div className="space-y-1.5">
                                    <label className="text-xs text-indigo-300 font-bold uppercase tracking-wider">Reality Filter</label>
                                     <select 
                                        value={visualFilter} 
                                        onChange={e => setVisualFilter(e.target.value as SeekerVisualFilter)}
                                        className="w-full bg-slate-800 border border-slate-600 rounded-lg p-3 text-slate-100 focus:border-indigo-400 focus:ring-2 focus:ring-indigo-500/50 outline-none transition-all"
                                    >
                                        {SEEKER_VISUAL_FILTERS.map(f => <option key={f.id} value={f.id}>{f.name}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-xs text-indigo-300 font-bold uppercase tracking-wider mb-1">Aura Signature</label>
                                    <div className="grid grid-cols-4 sm:grid-cols-8 gap-3 p-3 bg-slate-800 border border-slate-600 rounded-lg">
                                        {SEEKER_AURA_OPTIONS.map(option => (
                                            <button
                                                key={option.id}
                                                onClick={() => setAura(option.id)}
                                                className={`w-7 h-7 rounded-full border-2 transition-all duration-200 focus:outline-none ${
                                                    aura === option.id 
                                                    ? 'border-white scale-125 ring-2 ring-indigo-400 ring-offset-2 ring-offset-slate-900 shadow-lg' 
                                                    : 'border-transparent hover:scale-110 opacity-70 hover:opacity-100'
                                                }`}
                                                style={{ backgroundColor: option.hex, boxShadow: `0 0 10px ${option.hex}` }}
                                                title={option.name}
                                                aria-label={`Select ${option.name} aura`}
                                                aria-pressed={aura === option.id}
                                            />
                                        ))}
                                    </div>
                                    <div className="text-center text-[10px] text-indigo-200 mt-1 uppercase tracking-wide font-bold">{SEEKER_AURA_OPTIONS.find(a => a.id === aura)?.name}</div>
                                </div>
                            </div>
                        </div>

                         <Button onClick={handleCreateOrUpdate} disabled={isWeavingBio} className="w-full py-4 bg-gradient-to-r from-indigo-700 to-purple-700 hover:from-indigo-600 hover:to-purple-600 shadow-xl shadow-indigo-500/20 mt-6 font-cinzel font-bold text-base tracking-widest rounded-lg border border-indigo-500/30">
                            {isWeavingBio ? <><i className="ri-loader-4-line animate-spin mr-2"></i>Weaving Biography...</> : (existingProfile ? 'UPDATE IDENTITY MATRIX' : 'WEAVE IDENTITY MATRIX')}
                        </Button>
                    </div>
                </div>
            </div>
        )}

        {/* ... (Grimoire tab remains same) ... */}
        {activeTab === 'grimoire' && existingProfile && (
            <div className="flex-1 overflow-y-auto p-6 bg-[url('https://www.transparenttextures.com/patterns/dark-leather.png')] bg-slate-900 custom-scrollbar">
                <h2 className="text-center font-cinzel text-2xl text-amber-200 mb-6 drop-shadow-md">Grimoire of Collected Cards</h2>

                {Object.entries(inventoryGroups).map(([group, items]: [string, MarketItem[]]) => (
                    <div key={group} className="mb-8">
                        <h3 className="text-lg font-cinzel font-bold text-slate-400 border-b border-slate-700 mb-4 pb-1 flex items-center">
                            <i className={`${getCardTypeIcon(group)} mr-2 opacity-50`}></i>{group}
                        </h3>
                        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
                            {items.map((item, idx) => (
                                <div key={`${item.id}-${idx}`} className="transform hover:scale-105 transition-transform duration-200 cursor-pointer">
                                     <TCGCard 
                                        name={item.name}
                                        type={item.type}
                                        rarity={item.rarity}
                                        description={item.description}
                                     />
                                     {/* Quick Equip for Inventory View */}
                                     {['Weapon', 'Companion', 'Relic', 'Fashion'].includes(item.type) && (
                                         <button 
                                            className="w-full mt-1 bg-slate-800 hover:bg-indigo-600 text-white text-[9px] py-1 rounded border border-slate-600 hover:border-indigo-400 transition-colors"
                                            onClick={() => {
                                                const newProfile = {...existingProfile};
                                                if(item.type === 'Weapon') newProfile.equippedWeapon = item;
                                                if(item.type === 'Companion') newProfile.equippedCompanion = item;
                                                if(item.type === 'Relic') newProfile.equippedRelic = item;
                                                if(item.type === 'Fashion') newProfile.equippedOutfit = item;
                                                onUpdateProfile(newProfile);
                                                addEchoMessage(AgentName.SeekerProfileWeaverAgent, `Equipped ${item.name}`, 'text-emerald-400');
                                            }}
                                         >Equip</button>
                                     )}
                                </div>
                            ))}
                        </div>
                    </div>
                ))}
                {existingProfile.inventory.length === 0 && (
                    <div className="flex flex-col items-center justify-center h-64 text-slate-600 opacity-50">
                        <i className="ri-book-open-line text-6xl mb-4"></i>
                        <p>The Grimoire awaits your discoveries.</p>
                    </div>
                )}
            </div>
        )}
      </div>
    </div>
  );
};

export default SeekerProfileWeaverPanel;

import React, { useState, useEffect, useRef } from 'react';
import type { RPGNexusPanelProps, RPGGameState, RPGGameLocation, RPGDynamicAction, RPGSceneData } from '../../types';
import { AgentName, ArtifactType, ArtifactRarity } from '../../types';
import { Button } from '../ui/Button';
import { useGemini } from '../../context/GeminiIntegrationContext';
import { globalSoundEngine } from '../../lib/SoundEngine';
import { QuestCinemaEngine } from '../../lib/video/QuestCinemaEngine';

// --- Helper: Robust JSON Parsing ---
const cleanAndParseJSON = <T,>(text: string | null): T | null => {
  if (!text) return null;
  try {
    let cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    let data = JSON.parse(cleanText);
    const keys = Object.keys(data);
    if (keys.length === 1) {
      const rootKey = keys[0];
      if (['locations', 'rpg_locations', 'points_of_interest', 'data', 'result', 'outcome'].includes(rootKey.toLowerCase()) || 
          (typeof data[rootKey] === 'object' && !Array.isArray(data[rootKey]) && !data[rootKey].description && !data[rootKey].resultText)) {
          data = data[rootKey];
      }
    }
    return data as T;
  } catch (e) {
    console.error("RPGNexus: JSON Parsing Failed", e);
    return null;
  }
};

interface RPGScanResultLocation {
  description: string;
  color?: string;
  risk?: string;
  icon?: string;
}

const FALLBACK_LOCATIONS: Record<string, RPGScanResultLocation> = {
  "The Void Edge": { description: "A precipice where reality dissolves into static.", color: "text-slate-400", risk: "Extreme", icon: "ri-mist-line" },
  "Crystal Spire": { description: "A tower of singing glass reaching into the Aethel.", color: "text-cyan-300", risk: "Low", icon: "ri-building-2-line" },
  "Axiom Forge": { description: "Industrial complex where truths are hammered into shape.", color: "text-amber-400", risk: "Medium", icon: "ri-hammer-line" }
};

const DEFAULT_ACTIONS: RPGDynamicAction[] = [
    { id: 'def_explore', label: 'Survey the Area', type: 'explore', risk: 0.1, isDynamic: false },
    { id: 'def_scan', label: 'Scan for Anomalies', type: 'ritual', risk: 0.2, isDynamic: false },
    { id: 'def_rest', label: 'Recalibrate Systems', type: 'talk', risk: 0, isDynamic: false }
];

const RPGNexusPanel: React.FC<RPGNexusPanelProps> = ({
  width,
  height,
  addEchoMessage,
  activeProfile,
  onUpdateProfile,
  currentEntropy,
  onArtifactCreated,
  savedState,
  onSaveState,
  onUpdateSystemMetrics
}) => {
  const { invokeGemini, generateImage, generateVideo, generateSpeech, isGenerating } = useGemini();
  const chatEndRef = useRef<HTMLDivElement>(null);

  // -- State --
  const [gameState, setGameState] = useState<RPGGameState>(savedState || {
    currentLocation: 'The Void Edge',
    narrativeHistory: [{ text: "System Initialized. Awaiting Insertion Coordinates...", type: 'system', timestamp: Date.now() }],
    activeQuests: [],
    lastActionTimestamp: Date.now(),
    vitals: { integrity: 100, sanity: 100 },
    availableActions: DEFAULT_ACTIONS,
    achievements: [],
    combatState: { isActive: false, enemyName: '', enemyHp: 0, enemyMaxHp: 0, turn: 0, logs: [] },
    knownLocations: [],
    currentSceneDescription: "The initialization void. Static fills the air.",
    currentSceneImageUrl: null,
    sceneHistory: [] // New: Track scenes for video compilation
  });

  const [scanResults, setScanResults] = useState<Record<string, RPGScanResultLocation> | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [isProcessingTurn, setIsProcessingTurn] = useState(false);
  const [customActionInput, setCustomActionInput] = useState("");

  // -- Video & Cinema State --
  const [isAnimatingScene, setIsAnimatingScene] = useState(false);
  const [currentSceneVideoUrl, setCurrentSceneVideoUrl] = useState<string | null>(null);
  const [isCompilingStory, setIsCompilingStory] = useState(false);
  const [compilationProgress, setCompilationProgress] = useState(0);

  // -- Audio / Narrator State --
  const [isNarratorEnabled, setIsNarratorEnabled] = useState(false);
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);
  const [currentlyPlayingText, setCurrentlyPlayingText] = useState<string | null>(null);

  // -- Refs --
  const cinemaEngineRef = useRef<QuestCinemaEngine | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    return () => {
        if (cinemaEngineRef.current) cinemaEngineRef.current.dispose();
        if (audioContextRef.current) audioContextRef.current.close();
    }
  }, []);

  // -- Persistence --
  useEffect(() => {
    if (onSaveState) onSaveState(gameState);
  }, [gameState, onSaveState]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [gameState.narrativeHistory]);

  const getRiskColor = (risk: number) => {
      if (risk >= 0.7) return 'border-rose-500 hover:bg-rose-900/30 text-rose-200';
      if (risk >= 0.4) return 'border-amber-500 hover:bg-amber-900/30 text-amber-200';
      return 'border-emerald-500 hover:bg-emerald-900/30 text-emerald-200';
  };

  const getRiskLabel = (risk: number) => {
      if (risk >= 0.7) return { text: 'HIGH RISK', color: 'text-rose-400' };
      if (risk >= 0.4) return { text: 'MED RISK', color: 'text-amber-400' };
      return { text: 'LOW RISK', color: 'text-emerald-400' };
  };

  // --- AUDIO HELPER ---
  const playNarrativeAudio = async (text: string) => {
    if (!text) return;
    setIsPlayingAudio(true);
    setCurrentlyPlayingText(text);

    try {
        if (!audioContextRef.current) {
            audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
        }
        if (audioContextRef.current.state === 'suspended') {
            await audioContextRef.current.resume();
        }

        const audioData = await generateSpeech(text);
        if (audioData) {
            const buffer = await audioContextRef.current.decodeAudioData(audioData);
            const source = audioContextRef.current.createBufferSource();
            source.buffer = buffer;
            source.connect(audioContextRef.current.destination);
            source.onended = () => {
                setIsPlayingAudio(false);
                setCurrentlyPlayingText(null);
            };
            source.start(0);
        } else {
             // Fallback to browser TTS if API fails/quota
             const utterance = new SpeechSynthesisUtterance(text);
             utterance.onend = () => {
                 setIsPlayingAudio(false);
                 setCurrentlyPlayingText(null);
             };
             window.speechSynthesis.speak(utterance);
        }
    } catch (e) {
        console.error("Audio playback error", e);
        setIsPlayingAudio(false);
        setCurrentlyPlayingText(null);
    }
  };

  // --- CORE ENGINE ---

  const handleScanSector = async () => {
    if (isScanning || isGenerating) return;
    setIsScanning(true);
    globalSoundEngine.playSFX('click');
    addEchoMessage(AgentName.RPGNexusAgent, "Scanning sector for stability variances...", "text-indigo-300");

    const prompt = `Generate 3 unique, evocative RPG locations for a sci-fi/fantasy setting with entropy level ${currentEntropy.toFixed(2)}.
    Output strictly as JSON. Keys are location names.
    Values must be objects with:
    - "description": string (1 sentence)
    - "color": string (Tailwind text class, e.g. "text-red-400")
    - "risk": string ("Low", "Medium", "High", "Extreme")
    - "icon": string (RemixIcon class, e.g. "ri-skull-line")`;

    try {
      const response = await invokeGemini(prompt, "You are a JSON generator. Do not include markdown formatting.");
      const locations = cleanAndParseJSON<Record<string, RPGScanResultLocation>>(response);
      setScanResults(locations || FALLBACK_LOCATIONS);

      if (isNarratorEnabled) playNarrativeAudio("Sector scan complete. Anomalies detected.");
    } catch (err) {
      setScanResults(FALLBACK_LOCATIONS);
    } finally {
      setIsScanning(false);
    }
  };

  const handleTravel = async (locationName: string, locationData: RPGScanResultLocation) => {
    setScanResults(null); 
    setIsProcessingTurn(true);
    setCurrentSceneVideoUrl(null); // Reset video on travel
    addEchoMessage(AgentName.RPGNexusAgent, `Vectoring to ${locationName}...`, "text-cyan-300");
    globalSoundEngine.playSFX('pulse');

    setGameState(prev => ({
      ...prev,
      currentLocation: locationName as RPGGameLocation,
      narrativeHistory: [...prev.narrativeHistory, { text: `Arrived at ${locationName}.`, type: 'action', timestamp: Date.now() }]
    }));

    try {
      const textPrompt = `You are the Game Master. The player has just arrived at "${locationName}" (${locationData.description}).
      Current Entropy: ${currentEntropy}.
      1. Write a vivid, 2-sentence sensory description of the scene.
      2. Provide 3 distinct actions the player can take (Explore, Talk, Analyze, Ritual, etc.).
      3. Create a short quest title related to this location.

      Return JSON:
      {
        "description": "...",
        "actions": [ { "id": "act_1", "label": "...", "type": "explore", "risk": 0.2 }, ... ],
        "quest": { "title": "...", "description": "...", "rewards": { "xp": 100, "flux": 50 } }
      }`;

      const textResponseRaw = await invokeGemini(textPrompt, "Return valid JSON only.");
      const textData = cleanAndParseJSON<any>(textResponseRaw);

      if (textData) {
        // Image Gen
        const imagePrompt = `Sci-fi fantasy concept art, ${locationName}, ${textData.description}, cinematic lighting, atmospheric, ${currentEntropy > 0.6 ? 'glitch, chaos, fractal' : 'clean, ethereal, serene'}.`;
        generateImage(imagePrompt).then(url => {
          if (url) {
            setGameState(prev => {
                const newHistoryEntry: RPGSceneData = {
                    imageUrl: url,
                    location: locationName as RPGGameLocation,
                    description: textData.description,
                    timestamp: Date.now()
                };
                return { 
                    ...prev, 
                    currentSceneImageUrl: url,
                    sceneHistory: [...(prev.sceneHistory || []), newHistoryEntry] 
                };
            });
          }
        });

        setGameState(prev => ({
          ...prev,
          currentSceneDescription: textData.description,
          availableActions: textData.actions || DEFAULT_ACTIONS,
          activeQuests: prev.activeQuests.length < 3 ? [...prev.activeQuests, { ...textData.quest, id: `quest-${Date.now()}`, status: 'active' }] : prev.activeQuests,
          narrativeHistory: [...prev.narrativeHistory, { text: textData.description, type: 'narration', timestamp: Date.now() }]
        }));

        if (isNarratorEnabled) playNarrativeAudio(textData.description);
      }
    } catch (e) {
      console.error("Travel generation failed", e);
      addEchoMessage(AgentName.System, "Navigational data corrupted. Using fallback protocols.", "text-rose-400");
    } finally {
      setIsProcessingTurn(false);
    }
  };

  const handleAction = async (actionLabel: string, risk: number = 0.5) => {
    if (isProcessingTurn) return;
    setIsProcessingTurn(true);
    setCustomActionInput(""); // Clear input if used
    globalSoundEngine.playSFX('click');

    setGameState(prev => ({
        ...prev,
        narrativeHistory: [...prev.narrativeHistory, { text: `> ${actionLabel}`, type: 'action', timestamp: Date.now() }]
    }));

    const prompt = `Game Master Logic:
    Location: ${gameState.currentLocation}
    Action Taken: "${actionLabel}"
    Entropy: ${currentEntropy}
    Profile: ${activeProfile?.name || "Seeker"} (${activeProfile?.race} ${activeProfile?.class})
    Current Scene: ${gameState.currentSceneDescription}

    Determine the outcome. 
    1. Write a 1-2 sentence narrative result.
    2. Define any stat changes (integrity/sanity/flux).
    3. PROVIDE 3 NEW Available Actions for the player based on the new situation.

    Return JSON:
    {
      "resultText": "...",
      "deltaIntegrity": -5, 
      "deltaSanity": 0,
      "deltaFlux": 10,
      "newActions": [ { "id": "new_1", "label": "...", "type": "explore", "risk": 0.2 }, ... ]
    }`;

    try {
        const response = await invokeGemini(prompt, "Return valid JSON only. Do not wrap in markdown.");
        const outcome = cleanAndParseJSON<any>(response);

        if (outcome) {
            const newIntegrity = Math.max(0, Math.min(100, (gameState.vitals?.integrity || 100) + (outcome.deltaIntegrity || 0)));
            const newSanity = Math.max(0, Math.min(100, (gameState.vitals?.sanity || 100) + (outcome.deltaSanity || 0)));

            setGameState(prev => ({
                ...prev,
                vitals: { integrity: newIntegrity, sanity: newSanity },
                availableActions: (outcome.newActions && outcome.newActions.length > 0) ? outcome.newActions : DEFAULT_ACTIONS,
                narrativeHistory: [...prev.narrativeHistory, { text: outcome.resultText, type: 'narration', timestamp: Date.now() }]
            }));

            if (outcome.deltaFlux && onUpdateProfile && activeProfile) {
                onUpdateProfile({ ...activeProfile, flux: activeProfile.flux + outcome.deltaFlux });
                addEchoMessage(AgentName.RPGNexusAgent, `Flux ${outcome.deltaFlux > 0 ? '+' : ''}${outcome.deltaFlux}`, outcome.deltaFlux > 0 ? 'text-amber-300' : 'text-rose-400');
            }
            if (risk > 0.5) onUpdateSystemMetrics(0.01, -0.01); 

            if (isNarratorEnabled) playNarrativeAudio(outcome.resultText);

        } else {
             setGameState(prev => ({
                ...prev,
                availableActions: DEFAULT_ACTIONS,
                narrativeHistory: [...prev.narrativeHistory, { text: "The ether churns, obscuring the outcome. (Data corruption)", type: 'system', timestamp: Date.now() }]
            }));
        }
    } catch (e) {
        addEchoMessage(AgentName.System, "Action resolution failed. Systems rebooting...", "text-rose-400");
        setGameState(prev => ({ ...prev, availableActions: DEFAULT_ACTIONS }));
    } finally {
        setIsProcessingTurn(false);
    }
  };

  // --- NEW FEATURES ---

  const handleGenerateSceneVideo = async () => {
      if (isAnimatingScene || !gameState.currentSceneImageUrl) return;
      setIsAnimatingScene(true);
      addEchoMessage(AgentName.RPGNexusAgent, "Animating scene via Veo-3.1...", "text-fuchsia-300");

      try {
          const prompt = `Cinematic subtle motion, atmospheric video of ${gameState.currentSceneDescription}. ${currentEntropy > 0.6 ? 'Glitch art style, disturbing movement.' : 'Serene, flowing motion.'}`;
          const videoUrl = await generateVideo(prompt, gameState.currentSceneImageUrl);
          if (videoUrl) {
              setCurrentSceneVideoUrl(videoUrl);
              addEchoMessage(AgentName.RPGNexusAgent, "Scene animation compiled.", "text-emerald-300");
          } else {
              throw new Error("No video URL returned.");
          }
      } catch (e) {
          console.error(e);
          addEchoMessage(AgentName.System, "Video generation failed.", "text-rose-400");
      } finally {
          setIsAnimatingScene(false);
      }
  };

  const handleCompileStoryVideo = async () => {
      if (isCompilingStory || !gameState.sceneHistory || gameState.sceneHistory.length === 0) {
          addEchoMessage(AgentName.System, "No scene history to compile.", "text-yellow-400");
          return;
      }

      setIsCompilingStory(true);
      setCompilationProgress(0);
      addEchoMessage(AgentName.RPGNexusAgent, "Compiling narrative history into Quest Cinema...", "text-amber-300");

      try {
          if (!cinemaEngineRef.current) {
              cinemaEngineRef.current = new QuestCinemaEngine();
          }

          const slides = gameState.sceneHistory.map(scene => ({
              imageUrl: scene.imageUrl,
              text: scene.description
          }));

          const blob = await cinemaEngineRef.current.compileVideo(
              slides,
              (progress) => setCompilationProgress(Math.round(progress * 100)),
              async (text) => await generateSpeech(text) 
          );

          if (blob) {
              const url = URL.createObjectURL(blob);
              const a = document.createElement('a');
              a.href = url;
              a.download = `Nexus_Story_${Date.now()}.webm`; // Or mp4 based on engine support
              document.body.appendChild(a);
              a.click();
              document.body.removeChild(a);
              addEchoMessage(AgentName.RPGNexusAgent, "Story Compilation Complete. Downloading...", "text-emerald-300");

              if (onArtifactCreated) {
                  onArtifactCreated({
                      id: `cinema-${Date.now()}`,
                      name: "Quest Cinema Log",
                      type: ArtifactType.VisualMemory,
                      rarity: ArtifactRarity.Rare,
                      description: "A compiled video log of your recent journey.",
                      imageUrl: gameState.currentSceneImageUrl || "", // Thumbnail
                      timestamp: Date.now()
                  });
              }
          }
      } catch (e) {
          console.error(e);
          addEchoMessage(AgentName.System, "Story compilation failed.", "text-rose-400");
      } finally {
          setIsCompilingStory(false);
          setCompilationProgress(0);
      }
  };

  const handleDownloadStory = () => {
      const storyText = gameState.narrativeHistory.map(n => `[${new Date(n.timestamp).toLocaleTimeString()}] ${n.type.toUpperCase()}: ${n.text}`).join('\n\n');
      const blob = new Blob([storyText], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `Nexus_Log_${Date.now()}.txt`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      addEchoMessage(AgentName.RPGNexusAgent, "Narrative log exported.", "text-cyan-300");
  };

  const handleReimagineScene = async () => {
      if (isProcessingTurn || !gameState.currentSceneDescription) return;
      setIsProcessingTurn(true);
      addEchoMessage(AgentName.RPGNexusAgent, "Re-imagining reality matrix...", "text-purple-300");

      try {
          const imagePrompt = `Sci-fi fantasy concept art, ${gameState.currentLocation}, ${gameState.currentSceneDescription}, cinematic lighting, atmospheric, ${activeProfile?.visualFilter || 'cyberpunk'} style, ${currentEntropy > 0.6 ? 'glitch, chaos, fractal' : 'clean, ethereal, serene'}.`;

          const url = await generateImage(imagePrompt);
          if (url) {
             setGameState(prev => ({ 
                  ...prev, 
                  currentSceneImageUrl: url,
                  sceneHistory: [...(prev.sceneHistory || []), {
                      imageUrl: url,
                      location: prev.currentLocation,
                      description: prev.currentSceneDescription || "Reimagined scene",
                      timestamp: Date.now()
                  }]
              }));
              setCurrentSceneVideoUrl(null); // Clear video if scene changes
              addEchoMessage(AgentName.RPGNexusAgent, "Visuals re-synthesized.", "text-emerald-300");
          }
      } catch (e) {
          addEchoMessage(AgentName.System, "Reimagine failed.", "text-rose-400");
      } finally {
          setIsProcessingTurn(false);
      }
  };


  // -- Renders --

  const renderInitialization = () => (
    <div className="flex flex-col items-center justify-center h-full p-6 animate-fade-in-up bg-slate-900/50 text-center">
      <div className="text-5xl text-indigo-500 mb-6 animate-pulse"><i className="ri-radar-line"></i></div>
      <h3 className="text-2xl font-cinzel text-indigo-300 mb-3">Campaign Initialization</h3>
      <p className="text-base text-slate-400 mb-8 max-w-lg leading-relaxed">
        The Nexus Engine requires an insertion vector. Scan the local entropy field to materialize potential timelines.
      </p>

      {scanResults ? (
         <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl">
            {Object.entries(scanResults).map(([name, dataRaw]) => {
                const data = dataRaw as RPGScanResultLocation;
                return (
                    <button 
                        key={name}
                        onClick={() => handleTravel(name, data)}
                        className="flex flex-col p-6 bg-slate-800/80 border-2 border-slate-600 rounded-xl hover:bg-slate-700 hover:border-cyan-500 hover:shadow-2xl hover:shadow-cyan-500/20 transition-all group text-left transform hover:-translate-y-1"
                    >
                        <div className="flex items-center justify-between mb-4 w-full">
                            <i className={`${data.icon || 'ri-map-pin-line'} text-3xl ${data.color || 'text-slate-200'}`}></i>
                            <span className="text-xs uppercase font-bold tracking-wider bg-slate-900 px-3 py-1 rounded text-slate-400 group-hover:text-white transition-colors">{data.risk} Risk</span>
                        </div>
                        <h4 className="font-cinzel font-bold text-xl text-slate-200 group-hover:text-cyan-300 mb-2">{name}</h4>
                        <p className="text-sm text-slate-400 font-cormorant leading-relaxed">{data.description}</p>
                    </button>
                );
            })}
         </div>
      ) : (
        <Button onClick={handleScanSector} disabled={isScanning} className="px-10 py-4 text-base tracking-widest bg-indigo-600 hover:bg-indigo-500 shadow-xl shadow-indigo-500/20 font-bold">
            {isScanning ? <><i className="ri-loader-4-line animate-spin mr-3"></i>SCANNING SECTOR...</> : <><i className="ri-search-eye-line mr-3"></i>SCAN FOR ANOMALIES</>}
        </Button>
      )}
    </div>
  );

  const renderGameInterface = () => (
    <div className="relative h-full w-full overflow-hidden bg-slate-950 font-sans flex flex-col">
        {/* BACKGROUND LAYER */}
        <div className="absolute inset-0 z-0">
            {currentSceneVideoUrl ? (
                <video src={currentSceneVideoUrl} autoPlay loop muted className="w-full h-full object-cover" />
            ) : gameState.currentSceneImageUrl ? (
                <img src={gameState.currentSceneImageUrl} alt="Scene" className="w-full h-full object-cover transition-opacity duration-1000 ease-in-out" />
            ) : (
                 <div className="w-full h-full bg-slate-900 flex items-center justify-center">
                    <div className="text-slate-700 animate-pulse text-6xl"><i className="ri-image-line"></i></div>
                 </div>
            )}
            {/* VIGNETTE & GRADIENT OVERLAY */}
            <div className="absolute inset-0 bg-gradient-to-b from-slate-950/90 via-slate-950/20 to-slate-950/90 pointer-events-none"></div>
            <div className="absolute inset-0 bg-black/30 pointer-events-none"></div> 
        </div>

        {/* CONTENT LAYER */}
        <div className="relative z-10 flex flex-col h-full p-2 md:p-4 pointer-events-none overflow-hidden"> 

            {/* TOP BAR: Stats & Controls */}
            <div className="flex flex-wrap justify-between items-start gap-2 mb-2 pointer-events-auto shrink-0">
                 <div className="bg-slate-950/70 backdrop-blur-md border border-slate-700/50 rounded-lg p-3 shadow-lg flex-grow max-w-full md:max-w-md">
                    <h3 className="text-indigo-300 font-bold text-lg font-cinzel flex items-center gap-2 truncate">
                        <i className="ri-map-pin-user-fill"></i> {gameState.currentLocation}
