const RPGNexusPanel: React.FC<RPGNexusPanelProps> = ({
  width,
  height,
  addEchoMessage,
  activeProfile,
  onUpdateProfile,
  currentEntropy,
  onArtifactCreated,
  savedState,
  onSaveState,
  onUpdateSystemMetrics
}) => {
  const { invokeGemini, generateImage, generateVideo, generateSpeech, isGenerating } = useGemini();
  const chatEndRef = useRef<HTMLDivElement>(null);

  // -- State --
  const [gameState, setGameState] = useState<RPGGameState>(savedState || {
    currentLocation: 'The Void Edge',
    narrativeHistory: [{ text: "System Initialized. Awaiting Insertion Coordinates...", type: 'system', timestamp: Date.now() }],
    activeQuests: [],
    lastActionTimestamp: Date.now(),
    vitals: { integrity: 100, sanity: 100 },
    availableActions: DEFAULT_ACTIONS,
    achievements: [],
    combatState: { isActive: false, enemyName: '', enemyHp: 0, enemyMaxHp: 0, turn: 0, logs: [] },
    knownLocations: [],
    currentSceneDescription: "The initialization void. Static fills the air.",
    currentSceneImageUrl: null,
    sceneHistory: [] 
  });

  const [scanResults, setScanResults] = useState<Record<string, RPGScanResultLocation> | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [isProcessingTurn, setIsProcessingTurn] = useState(false);
  const [customActionInput, setCustomActionInput] = useState("");

  // -- Video & Cinema State --
  const [isAnimatingScene, setIsAnimatingScene] = useState(false);
  const [currentSceneVideoUrl, setCurrentSceneVideoUrl] = useState<string | null>(null);
  const [isCompilingStory, setIsCompilingStory] = useState(false);
  const [compilationProgress, setCompilationProgress] = useState(0);

  // -- Audio / Narrator State --
  const [isNarratorEnabled, setIsNarratorEnabled] = useState(false);
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);
  const [currentlyPlayingText, setCurrentlyPlayingText] = useState<string | null>(null);

  // -- Duel State --
  const [duelState, setDuelState] = useState<CardDuelState | null>(null);
  const [lootCard, setLootCard] = useState<MarketItem | null>(null);

  // -- Refs --
  const cinemaEngineRef = useRef<QuestCinemaEngine | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    return () => {
        if (cinemaEngineRef.current) cinemaEngineRef.current.dispose();
        if (audioContextRef.current) audioContextRef.current.close();
    }
  }, []);

  // -- Persistence --
  useEffect(() => {
    if (onSaveState) onSaveState(gameState);
  }, [gameState, onSaveState]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [gameState.narrativeHistory, duelState?.logs]); 

  const getRiskColor = (risk: number) => {
      if (risk >= 0.7) return 'border-rose-500 hover:bg-rose-900/30 text-rose-200';
      if (risk >= 0.4) return 'border-amber-500 hover:bg-amber-900/30 text-amber-200';
      return 'border-emerald-500 hover:bg-emerald-900/30 text-emerald-200';
  };

  // --- AUDIO HELPER ---
  const playNarrativeAudio = async (text: string) => {
    if (!text) return;
    setIsPlayingAudio(true);
    setCurrentlyPlayingText(text);

    try {
        if (!audioContextRef.current) {
            audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
        }
        if (audioContextRef.current.state === 'suspended') {
            await audioContextRef.current.resume();
        }

        const audioData = await generateSpeech(text);
        if (audioData) {
            const buffer = await audioContextRef.current.decodeAudioData(audioData);
            const source = audioContextRef.current.createBufferSource();
            source.buffer = buffer;
            source.connect(audioContextRef.current.destination);
            source.onended = () => {
                setIsPlayingAudio(false);
                setCurrentlyPlayingText(null);
            };
            source.start(0);
        } else {
             // Fallback
             const utterance = new SpeechSynthesisUtterance(text);
             utterance.onend = () => {
                 setIsPlayingAudio(false);
                 setCurrentlyPlayingText(null);
             };
             window.speechSynthesis.speak(utterance);
        }
    } catch (e) {
        console.error("Audio playback error", e);
        setIsPlayingAudio(false);
        setCurrentlyPlayingText(null);
    }
  };

  // --- CARD DUEL ENGINE ---
  const generateDuelCard = (level: number, type: 'player' | 'enemy'): DuelCard => {
      const isEnemy = type === 'enemy';
      const rarityRoll = Math.random();
      let rarity = ArtifactRarity.Common;
      if (rarityRoll > 0.95) rarity = ArtifactRarity.Legendary;
      else if (rarityRoll > 0.8) rarity = ArtifactRarity.Rare;
      else if (rarityRoll > 0.6) rarity = ArtifactRarity.Uncommon;

      const multiplier = (isEnemy ? 0.9 : 1.0) + (level * 0.1);

      // Procedural names based on location/entropy could go here
      const names = isEnemy 
        ? ["Void Shade", "Entropy Beast", "Data Glitch", "Null Sentinel", "Chaos Spark", "Abyssal Echo"] 
        : ["System Kernel", "Logic Gate", "Firewall", "Trace Router", "Ping Echo", "Code Weaver"];

      return {
          id: `card-${type}-${Date.now()}-${Math.random()}`,
          name: names[Math.floor(Math.random() * names.length)],
          type: 'Construct',
          rarity,
          stats: {
              atk: Math.floor((Math.random() * 10 + 5) * multiplier),
              def: Math.floor((Math.random() * 10 + 5) * multiplier),
              res: Math.floor((Math.random() * 10 + 5) * multiplier)
          },
          image: null 
      };
  };

  const convertMarketItemToDuelCard = (item: MarketItem): DuelCard => {
      // Use existing stats or generate
      const stats = item.combatStats || {
          atk: Math.floor(item.cost / 20) + 5,
          def: Math.floor(item.cost / 25) + 5,
          res: Math.floor(item.cost / 30) + 5
      };
      return {
          id: item.id,
          name: item.name,
          type: item.type,
          rarity: item.rarity,
          stats,
          image: null 
      };
  };

  const handleDuelStart = () => {
      if (duelState) return;

      // Player Deck: Random 3 from inventory or glitch cards
      let playerDeck: DuelCard[] = [];
      if (activeProfile && activeProfile.inventory.length > 0) {
          const shuffled = [...activeProfile.inventory].sort(() => 0.5 - Math.random());
          playerDeck = shuffled.slice(0, 3).map(convertMarketItemToDuelCard);
      }
      while (playerDeck.length < 3) {
          playerDeck.push({
              id: `glitch-${Date.now()}-${Math.random()}`,
              name: "Glitch Fragment",
              type: "Glitch",
              rarity: ArtifactRarity.Common,
              stats: { atk: 5, def: 5, res: 5 },
              image: null
          });
      }

      // Enemy Deck: Based on entropy
      const enemyLevel = Math.max(1, Math.floor(currentEntropy * 10));
      const enemyDeck: DuelCard[] = [
          generateDuelCard(enemyLevel, 'enemy'),
          generateDuelCard(enemyLevel, 'enemy'),
          generateDuelCard(enemyLevel, 'enemy')
      ];

      setDuelState({
          isActive: true,
          phase: BattlePhase.PLAYER_TURN,
          round: 1,
          playerHand: playerDeck,
          enemyHand: enemyDeck,
          playedCardPlayer: null,
          playedCardEnemy: null,
          playerScore: 0,
          enemyScore: 0,
          logs: ["Duel Initialized. Select a card to engage."],
          enemyName: `Level ${enemyLevel} Construct`,
          rewards: { flux: 50 + enemyLevel * 20 }
      });
      globalSoundEngine.playSFX('pulse');
  };

  const handleDuelCardSelect = (card: DuelCard) => {
      if (!duelState || duelState.phase !== BattlePhase.PLAYER_TURN) return;

      setDuelState(prev => {
          if (!prev) return null;
          // Enemy picks the card corresponding to the round index (simple AI)
          const enemyCard = prev.enemyHand[prev.round - 1]; 

          return {
              ...prev,
              playedCardPlayer: card,
              playedCardEnemy: enemyCard,
              phase: BattlePhase.ENEMY_REVEAL,
              logs: [`You deployed ${card.name}. Enemy engaging...`, ...prev.logs]
          };
      });

      // Sequence resolution
      setTimeout(() => {
          setDuelState(prev => prev ? ({ ...prev, phase: BattlePhase.RESOLUTION }) : null);
          resolveDuelRound();
      }, 1200);
  };

  const resolveDuelRound = () => {
      setDuelState(prev => {
          if (!prev || !prev.playedCardPlayer || !prev.playedCardEnemy) return prev;

          const pCard = prev.playedCardPlayer;
          const eCard = prev.playedCardEnemy;

          let pScore = prev.playerScore;
          let eScore = prev.enemyScore;
          const roundLogs = [];

          // 1. Clash Phase: Damage = ATK - DEF
          const pDmg = Math.max(0, pCard.stats.atk - eCard.stats.def);
          const eDmg = Math.max(0, eCard.stats.atk - pCard.stats.def);
          pScore += pDmg;
          eScore += eDmg;
          roundLogs.push(`Clash: ${pCard.name} deals ${pDmg}, ${eCard.name} deals ${eDmg}.`);

          // 2. Resonance Phase: Compare RES
          const pRes = pCard.stats.res;
          const eRes = eCard.stats.res;

          if (pRes > eRes) {
              const heal = Math.floor((pRes - eRes) * 1.5);
              pScore += heal;
              roundLogs.push(`Resonance Win: +${heal} Score (Stability).`);
          } else if (eRes > pRes) {
               const heal = Math.floor((eRes - pRes) * 1.5);
               eScore += heal;
               roundLogs.push(`Resonance Loss: Enemy gains +${heal} Score.`);
          } else {
              roundLogs.push(`Resonance Balanced.`);
          }

          let nextPhase = BattlePhase.PLAYER_TURN;
          let nextRound = prev.round + 1;

          // Check Victory
          if (prev.round >= 3) {
              const playerWon = pScore > eScore;
              nextPhase = playerWon ? BattlePhase.VICTORY : BattlePhase.DEFEAT;
              roundLogs.push(playerWon ? "PROTOCOL STABILIZED. VICTORY." : "CONNECTION SEVERED. DEFEAT.");

              if (playerWon) {
                   prepareLoot(prev.rewards?.flux || 0);
              }
          }

          return {
              ...prev,
              playerScore: pScore,
              enemyScore: eScore,
              phase: nextPhase,
              round: nextRound,
              logs: [...roundLogs, ...prev.logs],
              // Remove played card from hand visual for next round
              playerHand: prev.playerHand.filter(c => c.id !== pCard.id)
          };
      });
  };

