                                    className={`w-full text-left p-3 md:p-4 rounded-lg border ${borderColor} ${btnBg} backdrop-blur-sm transition-all group flex justify-between items-center shrink-0 shadow-lg`}
                                >
                                    <span className="text-sm md:text-base font-semibold text-slate-100 group-hover:text-white shadow-black drop-shadow-md">{action.label}</span>
                                    <span className={`text-[10px] uppercase opacity-70 font-mono bg-black/30 px-2 py-0.5 rounded`}>{action.type}</span>
                                </button>
                            );
                        })}
                    </div>
                </div>

                {/* NARRATIVE LOG */}
                <div className="lg:w-2/3 order-1 lg:order-2 pointer-events-auto flex flex-col min-h-0 h-full relative">
                     <div className="bg-slate-950/[0.02] backdrop-blur-md border border-slate-700/50 rounded-lg p-4 overflow-y-auto custom-scrollbar flex-grow shadow-2xl relative">
                        {gameState.narrativeHistory.slice(-10).map((entry, i) => ( 
                            <div key={i} className={`mb-3 last:mb-0 text-sm md:text-base leading-relaxed relative pr-8 group/entry drop-shadow-md ${entry.type === 'action' ? 'text-indigo-300 font-bold' : 'text-slate-300 font-cormorant'}`}>
                                {entry.type === 'action' && <span className="mr-2 opacity-50">></span>}
                                {entry.text}
                                <button 
                                    onClick={() => playNarrativeAudio(entry.text)}
                                    className={`absolute top-0 right-0 text-slate-500 hover:text-emerald-400 p-1 opacity-0 group-hover/entry:opacity-100 transition-opacity ${isPlayingAudio && currentlyPlayingText === entry.text ? 'text-emerald-400 opacity-100 animate-pulse' : ''}`}
                                    title="Play Audio"
                                    aria-label="Play narrative audio"
                                >
                                    <i className={`ri-${isPlayingAudio && currentlyPlayingText === entry.text ? 'volume-up' : 'play-circle'}-line text-lg`}></i>
                                </button>
                            </div>
                        ))}
                        <div ref={chatEndRef} />

                        {isProcessingTurn && (
                            <div className="flex items-center gap-2 text-indigo-400 animate-pulse mt-4 p-2 bg-indigo-900/20 rounded border border-indigo-500/30">
                                <i className="ri-quill-pen-line"></i> 
                                <span className="text-xs font-mono">The Game Master weaves the fate...</span>
                            </div>
                        )}

                        {/* Audio Status */}
                        {isPlayingAudio && (
                             <div className="sticky bottom-0 right-0 ml-auto w-fit mt-2 bg-black/80 backdrop-blur px-3 py-1 rounded-full text-[10px] text-emerald-400 flex items-center gap-2 border border-emerald-500/30 shadow-lg z-10">
                                 <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-ping"></span>
                                 Speaking...
                             </div>
                        )}
                     </div>

                     {/* Meta Controls (Footer of Log) */}
                     <div className="flex flex-wrap gap-2 justify-end mt-2 shrink-0">
                        <Button onClick={handleCompileStoryVideo} disabled={isCompilingStory || !gameState.sceneHistory?.length} className="text-[10px] py-2 bg-amber-700/80 hover:bg-amber-600/80 backdrop-blur-sm border border-amber-600/50">
                            {isCompilingStory ? `Compiling ${compilationProgress}%` : <><i className="ri-movie-2-line mr-1"></i> Story Movie</>}
                        </Button>
                        <Button onClick={handleDownloadStory} className="text-[10px] py-2 bg-cyan-700/80 hover:bg-cyan-600/80 backdrop-blur-sm border border-cyan-600/50">
                            <i className="ri-file-text-line mr-1"></i> Log
                        </Button>
                        <Button onClick={() => handleScanSector()} className="text-[10px] py-2 bg-indigo-700/80 hover:bg-indigo-600/80 backdrop-blur-sm border border-indigo-600/50">
                             <i className="ri-radar-line mr-1"></i> Rescan
                        </Button>
                     </div>
                </div>

                {/* DUEL OVERLAY */}
                {duelState && duelState.isActive && (
                    <div className="absolute inset-0 z-50 bg-slate-950/95 backdrop-blur-xl flex flex-col p-4 rounded-lg border-2 border-rose-500 animate-fade-in-up">
                        {/* Duel Header */}
                        <div className="flex justify-between items-center mb-4 border-b border-rose-700 pb-2">
                            <h3 className="text-xl font-cinzel font-bold text-rose-400 flex items-center">
                                <i className="ri-sword-fill mr-2"></i> PROTOCOL DUEL
                            </h3>
                            <div className="text-xs font-mono text-slate-300">Round {duelState.round}/3</div>
                            <div className="flex gap-4 text-sm font-bold bg-black/40 px-3 py-1 rounded-full border border-rose-900">
                                <span className="text-cyan-400">YOU: {duelState.playerScore}</span>
                                <span className="text-slate-500">|</span>
                                <span className="text-rose-400">ENEMY: {duelState.enemyScore}</span>
                            </div>
                        </div>

                        {/* Battle Area */}
                        <div className="flex-grow flex flex-col items-center justify-between py-2">
                            {/* Enemy Zone */}
                            <div className="w-full flex justify-center items-center mb-2 gap-4">
                                <div className="text-xs text-rose-500 font-bold uppercase tracking-widest vertical-rl rotate-180 hidden md:block">Enemy Signal</div>
                                <BattleCard 
                                    card={duelState.playedCardEnemy || duelState.enemyHand[0]} 
                                    isEnemy={true}
                                    isRevealed={!!duelState.playedCardEnemy}
                                />
                            </div>

                            {/* Combat Log / Status */}
                            <div className="w-full text-center my-2 p-3 bg-black/60 rounded border border-rose-900/50 min-h-[60px] flex items-center justify-center relative overflow-hidden">
                                <div className="absolute inset-0 bg-rose-900/10 animate-pulse"></div>
                                <p className="text-sm font-cormorant italic text-slate-100 relative z-10 drop-shadow-md">
                                    {duelState.logs[0] || "Select a card to engage..."}
                                </p>
                            </div>

                            {/* Player Zone */}
                            <div className="w-full flex flex-col items-center gap-2 mt-2">
                                <div className="flex justify-center gap-4">
                                    {duelState.playerHand.map((card) => (
                                        <BattleCard 
                                            key={card.id} 
                                            card={card} 
                                            isSelected={false}
                                            onClick={() => handleDuelCardSelect(card)}
                                        />
                                    ))}
                                    {duelState.playerHand.length === 0 && (
                                        <div className="text-slate-500 italic text-sm">Hand Empty</div>
                                    )}
                                </div>
                                <div className="text-xs text-cyan-500 font-bold uppercase tracking-widest mt-1">Your Construct</div>
                            </div>
                        </div>

                        {/* Footer / Exit */}
                        {(duelState.phase === BattlePhase.VICTORY || duelState.phase === BattlePhase.DEFEAT) && (
                            <div className="mt-4 flex flex-col items-center gap-3 bg-black/80 absolute inset-0 justify-center z-50 rounded-lg">
                                <h2 className={`text-4xl font-cinzel font-bold ${duelState.phase === BattlePhase.VICTORY ? 'text-emerald-400' : 'text-rose-500'}`}>
                                    {duelState.phase === BattlePhase.VICTORY ? 'VICTORY' : 'DEFEAT'}
                                </h2>
                                <p className="text-slate-300 italic">{duelState.phase === BattlePhase.VICTORY ? 'Protocol Stabilized. Artifact Recovered.' : 'Connection Severed. Entropy Rising.'}</p>

                                {lootCard && (
                                    <div className="my-4 transform scale-125">
                                        <BattleCard card={convertMarketItemToDuelCard(lootCard)} isRevealed={true} isWinner={true} />
                                        <div className="text-center mt-2 text-emerald-300 font-bold text-xs animate-pulse">New Artifact!</div>
                                    </div>
                                )}

                                <Button onClick={lootCard ? claimLootAndClose : closeDuel} className={`w-64 py-3 font-bold text-lg ${duelState.phase === BattlePhase.VICTORY ? 'bg-emerald-700 hover:bg-emerald-600' : 'bg-rose-700 hover:bg-rose-600'}`}>
                                    {lootCard ? 'COLLECT REWARD' : 'RETURN TO NEXUS'}
                                </Button>
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
    </div>
  );

  return (
    <div className="rpg-nexus-panel bg-slate-950 backdrop-blur-xl border border-indigo-600/50 rounded-xl shadow-2xl flex flex-col overflow-hidden transition-all duration-500 font-sans" style={{ width: width || '100%', height: height || '600px' }}>
      {/* Universal Header */}
      <div className="p-4 border-b border-indigo-800/50 bg-slate-900 flex justify-between items-center shrink-0 shadow-md z-20">
        <h3 className="text-xl font-cinzel font-bold text-indigo-300 flex items-center">
            <span className="bg-indigo-900/30 p-1.5 rounded-lg mr-3 border border-indigo-500/30"><i className="ri-gamepad-line text-indigo-400"></i></span>
            Nexus Engine
        </h3>
        {scanResults && (
             <button onClick={() => setScanResults(null)} className="text-xs font-bold text-slate-400 hover:text-white bg-slate-800 hover:bg-slate-700 px-3 py-1.5 rounded-lg transition-colors border border-slate-700">
                 <i className="ri-arrow-go-back-line mr-1"></i>Back to Game
             </button>
        )}
      </div>

      {/* Content Switcher */}
      <div className="flex-grow overflow-hidden relative">
          {(!scanResults && gameState.currentLocation === 'The Void Edge' && gameState.narrativeHistory.length <= 1) 
            ? renderInitialization() 
            : (scanResults ? renderInitialization() : renderGameInterface())
          }
      </div>
    </div>
  );
};

export default RPGNexusPanel;

