import React, { useEffect, useRef } from 'react';

interface Particle {
  x: number;
  y: number;
  size: number;
  color: string;
  vx: number;
  vy: number;
  life: number;
}

interface ClickWave {
    x: number;
    y: number;
    radius: number;
    maxRadius: number;
    alpha: number;
    color: string;
    growthRate: number;
    width: number;
}

const COLORS = [
  'rgba(56, 189, 248,', // Sky
  'rgba(168, 85, 247,', // Purple
  'rgba(52, 211, 153,', // Emerald
  'rgba(250, 204, 21,',  // Yellow
  'rgba(244, 63, 94,'   // Rose
];

const MagicalMouseTrail: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const particles = useRef<Particle[]>([]);
  const waves = useRef<ClickWave[]>([]);
  const mouse = useRef({ x: 0, y: 0 });

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const resize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };
    resize();
    window.addEventListener('resize', resize);

    const handleMouseMove = (e: MouseEvent) => {
      mouse.current = { x: e.clientX, y: e.clientY };
      // Spawn trail particles on move
      for (let i = 0; i < 2; i++) {
        particles.current.push({
          x: e.clientX,
          y: e.clientY,
          size: Math.random() * 3 + 1,
          color: COLORS[Math.floor(Math.random() * COLORS.length)],
          vx: (Math.random() - 0.5) * 1.5,
          vy: (Math.random() - 0.5) * 1.5,
          life: 1.0
        });
      }
    };

    const handleMouseDown = (e: MouseEvent) => {
        // 1. Spawn Reality Warp Wave
        waves.current.push({
            x: e.clientX,
            y: e.clientY,
            radius: 5,
            maxRadius: 200 + Math.random() * 100,
            alpha: 1.0,
            color: COLORS[Math.floor(Math.random() * COLORS.length)],
            growthRate: 8 + Math.random() * 5,
            width: 25 + Math.random() * 10
        });

        // 2. Spawn Particle Burst
        const burstCount = 12;
        for (let i = 0; i < burstCount; i++) {
            const angle = (Math.PI * 2 * i) / burstCount;
            const speed = 3 + Math.random() * 5;
            particles.current.push({
                x: e.clientX,
                y: e.clientY,
                size: Math.random() * 4 + 2,
                color: COLORS[Math.floor(Math.random() * COLORS.length)],
                vx: Math.cos(angle) * speed,
                vy: Math.sin(angle) * speed,
                life: 1.2 // Live slightly longer
            });
        }
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mousedown', handleMouseDown);

    const animate = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // -- Draw Waves (Reality Warp) --
      // We draw these first or separately to manage composite operations
      for (let i = waves.current.length - 1; i >= 0; i--) {
          const wave = waves.current[i];
          wave.radius += wave.growthRate;
          wave.alpha -= 0.02;
          wave.width *= 0.95; // Thin out

          if (wave.alpha <= 0) {
              waves.current.splice(i, 1);
              continue;
          }

          ctx.save();

          // The "Tear" - Difference mode inverts colors behind it
          ctx.globalCompositeOperation = 'difference';
          ctx.beginPath();
          ctx.arc(wave.x, wave.y, wave.radius, 0, Math.PI * 2);
          ctx.strokeStyle = `rgba(255, 255, 255, ${wave.alpha})`;
          ctx.lineWidth = wave.width;
          ctx.stroke();

          // The "Energy" - Lighter mode adds glow
          ctx.globalCompositeOperation = 'lighter';
          ctx.beginPath();
          ctx.arc(wave.x, wave.y, wave.radius * 0.9, 0, Math.PI * 2);
          ctx.strokeStyle = `${wave.color}${wave.alpha})`;
          ctx.lineWidth = 2;
          ctx.stroke();

          ctx.restore();
      }


      // -- Draw Particles --
      ctx.globalCompositeOperation = 'source-over'; // Reset to default
      for (let i = 0; i < particles.current.length; i++) {
        const p = particles.current[i];
        p.x += p.vx;
        p.y += p.vy;
        p.life -= 0.02;
        p.size *= 0.96;

        if (p.life <= 0) {
          particles.current.splice(i, 1);
          i--;
          continue;
        }

        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fillStyle = `${p.color}${p.life})`;
        ctx.fill();

        // Glow
        ctx.shadowBlur = 5;
        ctx.shadowColor = p.color + '1)';
      }
      ctx.shadowBlur = 0;

      requestAnimationFrame(animate);
    };
    animate();

    return () => {
      window.removeEventListener('resize', resize);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mousedown', handleMouseDown);
    };
  }, []);

  return (
    <canvas 
      ref={canvasRef} 
      className="fixed inset-0 pointer-events-none z-[9999]"
      style={{ mixBlendMode: 'screen' }} // Allows underlying UI to shine through particles nicely
    />
  );
};

